ll,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_NGUOIDUNG_VaiTro","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_PHANCONG_RAP_NguoiDung","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_PHANCONG_RAP_Rap","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_PHIM_DIENVIEN_DienVien","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_PHIM_DIENVIEN_Phim","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_PHIM_THELOAI_Phim","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_PHIM_THELOAI_TheLoai","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_PHONGCHIEU_Rap","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_SUATCHIEU_Phim","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_SUATCHIEU_Phong","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_TINNHAN_KHIEUNAI_KhieuNai","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_TINNHAN_KHIEUNAI_NguoiGui","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_THANHTOAN_DonDatVe","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_VAITRO_QUYEN_Quyen","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_VAITRO_QUYEN_VaiTro","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_XULY_KHIEUNAI_KhieuNai","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_XULY_KHIEUNAI_NguoiXuLy","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_YEUCAU_CHUYENCAP_AdminPhuTrach","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_YEUCAU_CHUYENCAP_KhieuNai","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"FK_YEUCAU_CHUYENCAP_NguoiYeuCau","type":"F ","type_desc":"FOREIGN_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"fn_BayGio","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_BayGio() RETURNS DATETIME2(7) AS\nBEGIN\n    -- Canonical instant: UTC components in datetime2, independent of host TZ.\n    RETURN SYSUTCDATETIME();\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_DonDangGiuGhe","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_DonDangGiuGhe(@TrangThai NVARCHAR(50), @HanGiuCho DATETIME2, @Now DATETIME2) RETURNS BIT AS\nBEGIN\n    RETURN CASE\n        WHEN @TrangThai IN (N''Đã thanh toán'', N''Hoàn thành'') THEN 1\n        WHEN @TrangThai = N''Chờ thanh toán''\n        AND @HanGiuCho > @Now THEN 1\n        ELSE 0\n    END;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_GheCoVeHieuLucSuatTuongLai","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"-- Baseline: migrations/014_showtime_lifecycle.sql:14 (dbo.fn_GheCoVeHieuLucSuatTuongLai)\nCREATE   FUNCTION dbo.fn_GheCoVeHieuLucSuatTuongLai(@GheID INT) RETURNS BIT AS\nBEGIN\n    DECLARE @CoVe BIT = 0;\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.CHITIETVE cv\n            INNER JOIN dbo.DONDATVE ddv ON ddv.DonDatVeID = cv.DonDatVeID\n            INNER JOIN dbo.SUATCHIEU sc ON sc.SuatChieuID = ddv.SuatChieuID\n        WHERE\n            cv.GheID = @GheID\n            AND cv.TrangThai = N''Đã đặt''\n            AND sc.ThoiGianBatDau > dbo.fn_BayGio()\n            AND dbo.fn_DonDangGiuGhe(ddv.TrangThai, ddv.HanGiuCho, dbo.fn_BayGio()) = 1\n    )\n        SET\n            @CoVe = 1;\n    RETURN @CoVe;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_GioiHanDonDangGiu","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_GioiHanDonDangGiu() RETURNS INT AS\nBEGIN\n    RETURN 3;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_GioiHanGheMoiDon","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_GioiHanGheMoiDon() RETURNS INT AS\nBEGIN\n    RETURN 10;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_GioiHanGiamGiaPhanTram","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_GioiHanGiamGiaPhanTram() RETURNS INT AS\nBEGIN\n    RETURN 99;\n    -- tối đa 99% (cũng là trần của khuyến mãi phần trăm, xem CK_KHUYENMAI_PhanTram99)\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_GioiHanSoLuongSanPham","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_GioiHanSoLuongSanPham() RETURNS INT AS\nBEGIN\n    RETURN 10;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_GioRap","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_GioRap(@UtcInstant DATETIME2(7)) RETURNS DATETIMEOFFSET(7) AS\nBEGIN\n    -- Windows zone corresponding to the application''s Asia/Ho_Chi_Minh.\n    RETURN @UtcInstant AT TIME ZONE ''UTC'' AT TIME ZONE ''SE Asia Standard Time'';\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_HomNay","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_HomNay() RETURNS DATE AS\nBEGIN\n    RETURN dbo.fn_NgayKinhDoanh(dbo.fn_BayGio());\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_KiemTraQuanLyRapScope","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"-- Baseline: functions/02_functions.sql:304 (dbo.fn_KiemTraQuanLyRapScope)\nCREATE   FUNCTION dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID INT, @RapID INT) RETURNS BIT AS\nBEGIN\n    -- Nếu là QUAN_LY_RAP, kiểm tra bảng PHANCONG_RAP còn hiệu lực\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.PHANCONG_RAP pcr\n            INNER JOIN dbo.NGUOIDUNG nd ON pcr.NguoiDungID = nd.NguoiDungID\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            pcr.NguoiDungID = @NguoiDungID\n            AND pcr.RapID = @RapID\n            AND pcr.TrangThai = N''Hiệu lực''\n            AND dbo.fn_HomNay() >= pcr.NgayBatDau\n            AND (\n                pcr.NgayKetThuc IS NULL\n                OR dbo.fn_HomNay() <= pcr.NgayKetThuc\n            )\n            AND nd.TrangThai = N''Hoạt động''\n            AND vt.MaVaiTro = ''QUAN_LY_RAP''\n    )\n    BEGIN\n        RETURN 1;\n    END\n    RETURN 0;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_KiemTraQuyenNguoiDung","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID INT, @MaQuyen VARCHAR(50)) RETURNS BIT AS\nBEGIN\n    DECLARE @HopLe BIT = 0;\n    -- Kiểm tra quyền cụ thể qua bảng nối VAITRO_QUYEN\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO_QUYEN vq ON nd.VaiTroID = vq.VaiTroID\n            INNER JOIN dbo.QUYEN q ON vq.QuyenID = q.QuyenID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND q.MaQuyen = @MaQuyen\n            AND nd.TrangThai = N''Hoạt động''\n    )\n    BEGIN\n        SET\n            @HopLe = 1;\n    END\n    RETURN @HopLe;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_NgayKinhDoanh","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_NgayKinhDoanh(@UtcInstant DATETIME2(7)) RETURNS DATE AS\nBEGIN\n    RETURN CONVERT(DATE, dbo.fn_GioRap(@UtcInstant));\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_TinhGiaVe","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"-- ---------------------------------------------------------------------------------------------\n-- (2) Weekend independent of configuration.\n-- Rule kept exactly as before: Saturday and Sunday are \"Cuối tuần\" (DATEPART(dw) IN (1, 7) under the default\n-- DATEFIRST 7 / us_english). 1900-01-01 was a Monday, so DATEDIFF(DAY, ''19000101'', date) % 7 is 0 = Monday ...\n-- 5 = Saturday, 6 = Sunday, whatever DATEFIRST or the language is (style 112 is language independent too).\n-- Everything else in the function is unchanged from migration 012.\n-- ---------------------------------------------------------------------------------------------\nCREATE   FUNCTION dbo.fn_TinhGiaVe(@SuatChieuID INT, @GheID INT) RETURNS DECIMAL(18, 2) AS\nBEGIN\n    DECLARE @GiaVeCoBan DECIMAL(18, 2) = 0;\n    DECLARE @RapID INT;\n    DECLARE @DinhDang NVARCHAR(50);\n    DECLARE @ThoiGianBatDau DATETIME2;\n    DECLARE @LoaiGhe NVARCHAR(50);\n    DECLARE @LoaiNgay NVARCHAR(50);\n    DECLARE @NgayChieu DATE;\n    DECLARE @PhuThu DECIMAL(18, 2) = 0;\n    SELECT\n        @GiaVeCoBan = sc.GiaVeCoBan,\n        @DinhDang = sc.DinhDang,\n        @ThoiGianBatDau = sc.ThoiGianBatDau,\n        @RapID = pc.RapID,\n        @NgayChieu = dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau)\n    FROM\n        dbo.SUATCHIEU sc\n        INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\n    WHERE\n        sc.SuatChieuID = @SuatChieuID;\n    IF @GiaVeCoBan IS NULL\n        RETURN 0;\n    SELECT\n        @LoaiGhe = LoaiGhe\n    FROM\n        dbo.GHE\n    WHERE\n        GheID = @GheID;\n    IF @LoaiGhe IS NULL\n        SET\n            @LoaiGhe = N''Thường'';\n    -- 5 = Saturday, 6 = Sunday counted from a Monday (independent of DATEFIRST and language)\n    IF DATEDIFF(DAY, CONVERT(DATE, ''19000101'', 112), @NgayChieu) % 7 IN (5, 6)\n        SET\n            @LoaiNgay = N''Cuối tuần'';\n    ELSE\n        SET\n            @LoaiNgay = N''Ngày thường'';\n    -- R0: Ngày thường / Cuối tuần / Tất cả. SQL remains the authoritative price calculator.\n    -- All matching surcharges are added (migration 012)\n    SELECT\n        @PhuThu = ISNULL(SUM(PhuThu), 0)\n    FROM\n        dbo.BANGGIA bg\n    WHERE\n        bg.RapID = @RapID\n        AND bg.TrangThai = N''Áp dụng''\n        AND @NgayChieu >= bg.NgayBatDau\n        AND (\n            @NgayChieu <= bg.NgayKetThuc\n            OR bg.NgayKetThuc IS NULL\n        )\n        AND (\n            bg.LoaiGhe = @LoaiGhe\n            OR bg.LoaiGhe = N''Tất cả''\n        )\n        AND (\n            bg.LoaiNgay = @LoaiNgay\n            OR bg.LoaiNgay = N''Tất cả''\n        )\n        AND (\n            bg.DinhDang = @DinhDang\n            OR bg.DinhDang = N''Tất cả''\n        );\n    RETURN(@GiaVeCoBan + ISNULL(@PhuThu, 0));\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_TinhTongTienDoAn","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_TinhTongTienDoAn(@DonDatVeID INT) RETURNS DECIMAL(18, 2) AS\nBEGIN\n    DECLARE @TongTienDoAn DECIMAL(18, 2) = 0;\n    SELECT\n        @TongTienDoAn = ISNULL(SUM(SoLuong * DonGia), 0)\n    FROM\n        dbo.CHITIETDOAN\n    WHERE\n        DonDatVeID = @DonDatVeID;\n    RETURN @TongTienDoAn;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_TinhTongTienDon","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_TinhTongTienDon(@DonDatVeID INT) RETURNS DECIMAL(18, 2) AS\nBEGIN\n    DECLARE @TongTienVe DECIMAL(18, 2) = 0;\n    DECLARE @TongTienDoAn DECIMAL(18, 2) = 0;\n    DECLARE @TienGiamGia DECIMAL(18, 2) = 0;\n    DECLARE @TongThanhToan DECIMAL(18, 2) = 0;\n    SELECT\n        @TongTienVe = TongTienVe,\n        @TongTienDoAn = TongTienDoAn,\n        @TienGiamGia = TienGiamGia\n    FROM\n        dbo.DONDATVE\n    WHERE\n        DonDatVeID = @DonDatVeID;\n    SET\n        @TongThanhToan = @TongTienVe + @TongTienDoAn - @TienGiamGia;\n    IF @TongThanhToan < 0\n        SET\n            @TongThanhToan = 0;\n    RETURN @TongThanhToan;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_TinhTongTienVe","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_TinhTongTienVe(@DonDatVeID INT) RETURNS DECIMAL(18, 2) AS\nBEGIN\n    DECLARE @TongTienVe DECIMAL(18, 2) = 0;\n    SELECT\n        @TongTienVe = ISNULL(SUM(GiaVe), 0)\n    FROM\n        dbo.CHITIETVE\n    WHERE\n        DonDatVeID = @DonDatVeID\n        AND TrangThai <> N''Đã hủy'';\n    RETURN @TongTienVe;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_ThoiGianGiaHanThanhToanPhut","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_ThoiGianGiaHanThanhToanPhut() RETURNS INT AS\nBEGIN\n    RETURN 5;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_ThoiGianGiuChoPhut","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"-- ---------------------------------------------------------------------------------------------\n-- Single places for the rules (same pattern as fn_ThoiGianGiuChoPhut)\n-- ---------------------------------------------------------------------------------------------\nCREATE   FUNCTION dbo.fn_ThoiGianGiuChoPhut() RETURNS INT AS\nBEGIN\n    RETURN 5;\n    -- Điểm duy nhất cấu hình thời gian giữ ghế; không gia hạn\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_UtcTuGioRap","type":"FN","type_desc":"SQL_SCALAR_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_UtcTuGioRap(@LocalDateTime DATETIME2(7)) RETURNS DATETIME2(7) AS\nBEGIN\n    RETURN CONVERT(\n        DATETIME2(7),\n        @LocalDateTime AT TIME ZONE ''SE Asia Standard Time'' AT TIME ZONE ''UTC''\n    );\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_DanhSachGheSuatChieu","type":"IF","type_desc":"SQL_INLINE_TABLE_VALUED_FUNCTION","definition":"-- Baseline: functions/02_functions.sql:203 (dbo.fn_DanhSachGheSuatChieu)\nCREATE   FUNCTION dbo.fn_DanhSachGheSuatChieu(@SuatChieuID INT) RETURNS\nTABLE AS\nRETURN(\n    WITH\n        GhePhong AS (\n            SELECT\n                g.GheID,\n                g.PhongID,\n                g.HangGhe,\n                g.SoGhe,\n                (g.HangGhe + CAST(g.SoGhe AS VARCHAR(10))) AS TenGhe,\n                g.LoaiGhe,\n                g.TrangThai AS TrangThaiGheVatLy\n            FROM\n                dbo.vw_LichChieuChiTiet sc\n                INNER JOIN dbo.GHE g ON sc.PhongID = g.PhongID\n            WHERE\n                sc.SuatChieuID = @SuatChieuID\n                AND sc.IsBookable = 1\n        ),\n        GheChiemCho AS (\n            -- Mức 2 = đã bán (đơn đã thanh toán), mức 1 = đang giữ chỗ chờ thanh toán\n            SELECT\n                cv.GheID,\n                MAX(\n                    CASE\n                        WHEN ddv.TrangThai = N''Chờ thanh toán'' THEN 1\n                        ELSE 2\n                    END\n                ) AS Muc\n            FROM\n                dbo.CHITIETVE cv\n                INNER JOIN dbo.DONDATVE ddv ON cv.DonDatVeID = ddv.DonDatVeID\n            WHERE\n                ddv.SuatChieuID = @SuatChieuID\n                AND cv.TrangThai <> N''Đã hủy''\n                AND dbo.fn_DonDangGiuGhe(ddv.TrangThai, ddv.HanGiuCho, dbo.fn_BayGio()) = 1\n            GROUP BY\n                cv.GheID\n        )\n    SELECT\n        gp.GheID,\n        gp.PhongID,\n        gp.HangGhe,\n        gp.SoGhe,\n        gp.TenGhe,\n        gp.LoaiGhe,\n        dbo.fn_TinhGiaVe(@SuatChieuID, gp.GheID) AS GiaVe,\n        CASE\n            WHEN gp.TrangThaiGheVatLy <> N''Hoạt động'' THEN N''Bảo trì''\n            WHEN gdd.Muc = 2 THEN N''Đã đặt''\n            WHEN gdd.Muc = 1 THEN N''Đang giữ''\n            ELSE N''Trống''\n        END AS TrangThaiGhe\n    FROM\n        GhePhong gp\n        LEFT JOIN GheChiemCho gdd ON gp.GheID = gdd.GheID\n);","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"fn_TinhBoiThuongVe","type":"IF","type_desc":"SQL_INLINE_TABLE_VALUED_FUNCTION","definition":"CREATE   FUNCTION dbo.fn_TinhBoiThuongVe(\n    @TongTienVe DECIMAL(18, 2),\n    @TongTienDoAn DECIMAL(18, 2),\n    @TienGiamGia DECIMAL(18, 2)\n) RETURNS\nTABLE AS\nRETURN(\n    -- Proportional allocation: Ve - Giam * Ve / (Ve + DoAn).\n    -- Integer cents are exact DECIMAL values, not a monetary rounding step.\n    -- Use the remainder to avoid division rounding a sub-point value up before FLOOR.\n    SELECT\n        CAST(\n            ISNULL(n.TuSo / NULLIF(c.TongCent * CAST(100 AS DECIMAL(3, 0)), 0), 0) AS DECIMAL(38, 6)\n        ) AS TienVeThucTra,\n        CAST(\n            FLOOR(\n                ISNULL((n.TuSo - n.TuSo % NULLIF(p.MauDiem, 0)) / NULLIF(p.MauDiem, 0), 0)\n            ) AS BIGINT\n        ) AS DiemCong\n    FROM\n        (\n            SELECT\n                CAST(ISNULL(@TongTienVe, 0) * 100 AS DECIMAL(19, 0)) AS VeCent,\n                CAST(\n                    (ISNULL(@TongTienVe, 0) + ISNULL(@TongTienDoAn, 0)) * 100 AS DECIMAL(19, 0)\n                ) AS TongCent,\n                CAST(ISNULL(@TienGiamGia, 0) * 100 AS DECIMAL(19, 0)) AS GiamCent\n        ) c\n        CROSS APPLY(\n            SELECT\n                CAST(\n                    CASE\n                        WHEN c.TongCent <= c.GiamCent\n                        OR c.VeCent <= 0 THEN 0\n                        ELSE c.VeCent * (c.TongCent - c.GiamCent)\n                    END AS DECIMAL(38, 0)\n                ) AS TuSo\n        ) n\n        CROSS APPLY(\n            SELECT\n                CAST(c.TongCent * CAST(100000 AS DECIMAL(6, 0)) AS DECIMAL(25, 0)) AS MauDiem\n        ) p\n);","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Actor_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Actor_Create\n    (\n    @ActorID INT,\n    @HoTen NVARCHAR(150),\n    @NgaySinh DATE = NULL,\n    @QuocTich NVARCHAR(100) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF @NgaySinh > dbo.fn_HomNay()\n        THROW 50400, N''Ngày sinh không được ở tương lai.'', 1;\n    INSERT INTO\n        dbo.DIENVIEN(HoTen, NgaySinh, QuocTich)\n    VALUES\n        (@HoTen, @NgaySinh, @QuocTich);\n    SELECT\n        DienVienID,\n        HoTen,\n        NgaySinh,\n        QuocTich\n    FROM\n        dbo.DIENVIEN\n    WHERE\n        DienVienID = SCOPE_IDENTITY();\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Actor_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Actor_Delete\n    (@ActorID INT, @DienVienID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SET XACT_ABORT ON;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END,\n        @LockedActor INT;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION AdminActorDelete;\n        -- X is incompatible with replacement''s shared validation lock. Acquire it\n        -- before the association read, preventing check-before-insert cascade races.\n        SELECT\n            @LockedActor = DienVienID\n        FROM\n            dbo.DIENVIEN\n        WITH\n            (XLOCK, HOLDLOCK)\n        WHERE\n            DienVienID = @DienVienID;\n        IF @LockedActor IS NULL\n            THROW 50100, N''Diễn viên không tồn tại.'', 1;\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.PHIM_DIENVIEN\n            WHERE\n                DienVienID = @DienVienID\n        )\n            THROW 50101, N''Diễn viên đang tham gia phim nên không thể xóa.'', 1;\n        -- Xóa các bản ghi thỏa điều kiện đã xác định.\n        DELETE FROM dbo.DIENVIEN\n        WHERE\n            DienVienID = @DienVienID;\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        SELECT\n            N''Đã xóa diễn viên.'' AS [Message];\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION;\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION AdminActorDelete;\n        END;\n        THROW;\n    END CATCH;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Actor_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Actor_List\n    @ActorID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SELECT\n        DienVienID,\n        HoTen,\n        NgaySinh,\n        QuocTich\n    FROM\n        dbo.DIENVIEN\n    ORDER BY\n        HoTen;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Actor_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Actor_Update\n    (\n    @ActorID INT,\n    @DienVienID INT,\n    @HoTen NVARCHAR(150),\n    @NgaySinh DATE = NULL,\n    @QuocTich NVARCHAR(100) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.DIENVIEN\n        WHERE\n            DienVienID = @DienVienID\n    )\n    BEGIN\n        ;\n        THROW 50100, N''Diễn viên không tồn tại.'', 1;\n    END\n    IF @NgaySinh > dbo.fn_HomNay()\n        THROW 50400, N''Ngày sinh không được ở tương lai.'', 1;\n    -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n    UPDATE dbo.DIENVIEN\n    SET\n        HoTen = @HoTen,\n        NgaySinh = @NgaySinh,\n        QuocTich = @QuocTich\n    WHERE\n        DienVienID = @DienVienID;\n    SELECT\n        DienVienID,\n        HoTen,\n        NgaySinh,\n        QuocTich\n    FROM\n        dbo.DIENVIEN\n    WHERE\n        DienVienID = @DienVienID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Assignment_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Assignment_Create\n    (\n    @ActorID INT,\n    @NguoiDungID INT,\n    @RapID INT,\n    @NgayBatDau DATE,\n    @NgayKetThuc DATE = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''PHANCONG_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Kiểm tra tài khoản phải là QUAN_LY_RAP\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro = ''QUAN_LY_RAP''\n    )\n    BEGIN\n        ;\n        THROW 50071, N''Tài khoản được phân công phải có vai trò QUAN_LY_RAP.'', 1;\n    END\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION AssignmentCreate;\n        -- Serialize equivalent creates and updates; do not invent a period-overlap restriction.\n        DECLARE @LockedRows BIGINT;\n        SELECT\n            @LockedRows = COUNT_BIG(*)\n        FROM\n            dbo.PHANCONG_RAP\n        WITH\n            (TABLOCKX, HOLDLOCK);\n        IF @NgayKetThuc < @NgayBatDau\n            THROW 50213, N''Khoảng thời gian phân công không hợp lệ.'', 1;\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.PHANCONG_RAP\n            WHERE\n                NguoiDungID = @NguoiDungID\n                AND RapID = @RapID\n                AND NgayBatDau = @NgayBatDau\n                AND (\n                    NgayKetThuc = @NgayKetThuc\n                    OR (\n                        NgayKetThuc IS NULL\n                        AND @NgayKetThuc IS NULL\n                    )\n                )\n                AND TrangThai = N''Hiệu lực''\n        )\n            THROW 50401, N''Phân công hoàn toàn giống nhau đã tồn tại.'', 1;\n        INSERT INTO\n            dbo.PHANCONG_RAP(NguoiDungID, RapID, NgayBatDau, NgayKetThuc, TrangThai)\n        VALUES\n            (@NguoiDungID, @RapID, @NgayBatDau, @NgayKetThuc, N''Hiệu lực'');\n        DECLARE @NewAssignmentID INT = SCOPE_IDENTITY();\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        SELECT\n            pcr.PhanCongID,\n            pcr.NguoiDungID,\n            nd.HoTen,\n            pcr.RapID,\n            r.TenRap,\n            pcr.NgayBatDau,\n            pcr.NgayKetThuc,\n            pcr.TrangThai\n        FROM\n            dbo.PHANCONG_RAP pcr\n            INNER JOIN dbo.NGUOIDUNG nd ON pcr.NguoiDungID = nd.NguoiDungID\n            INNER JOIN dbo.RAPCHIEUPHIM r ON pcr.RapID = r.RapID\n        WHERE\n            pcr.PhanCongID = @NewAssignmentID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION AssignmentCreate;\n        END;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Assignment_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Assignment_List\n    (@ActorID INT, @RapID INT = NULL, @NguoiDungID INT = NULL)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''PHANCONG_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SELECT\n        pcr.PhanCongID,\n        pcr.NguoiDungID,\n        nd.HoTen AS TenQuanLy,\n        nd.Email,\n        pcr.RapID,\n        r.TenRap,\n        r.ThanhPho,\n        pcr.NgayBatDau,\n        pcr.NgayKetThuc,\n        pcr.TrangThai\n    FROM\n        dbo.PHANCONG_RAP pcr\n        INNER JOIN dbo.NGUOIDUNG nd ON pcr.NguoiDungID = nd.NguoiDungID\n        INNER JOIN dbo.RAPCHIEUPHIM r ON pcr.RapID = r.RapID\n    WHERE\n        (\n            @RapID IS NULL\n            OR pcr.RapID = @RapID\n        )\n        AND (\n            @NguoiDungID IS NULL\n            OR pcr.NguoiDungID = @NguoiDungID\n        )\n    ORDER BY\n        pcr.NgayBatDau DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Cinema_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Cinema_Create\n    (\n    @ActorID INT,\n    @TenRap NVARCHAR(150),\n    @DiaChi NVARCHAR(255),\n    @ThanhPho NVARCHAR(100),\n    @SoDienThoai VARCHAR(20) = NULL,\n    @MoTa NVARCHAR(500) = NULL,\n    @NgayHoatDong DATE = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    INSERT INTO\n        dbo.RAPCHIEUPHIM(TenRap, DiaChi, ThanhPho, SoDienThoai, MoTa, NgayHoatDong, TrangThai)\n    VALUES\n        (\n            @TenRap,\n            @DiaChi,\n            @ThanhPho,\n            @SoDienThoai,\n            @MoTa,\n            @NgayHoatDong,\n            N''Hoạt động''\n        );\n    SELECT\n        RapID,\n        TenRap,\n        DiaChi,\n        ThanhPho,\n        SoDienThoai,\n        MoTa,\n        NgayHoatDong,\n        TrangThai\n    FROM\n        dbo.RAPCHIEUPHIM\n    WHERE\n        RapID = SCOPE_IDENTITY();\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Cinema_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Cinema_Delete\n    @ActorID INT,\n    @RapID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.RAPCHIEUPHIM\n        WHERE\n            RapID = @RapID\n    )\n        THROW 50095, N''Rạp không tồn tại.'', 1;\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.PHONGCHIEU\n        WHERE\n            RapID = @RapID\n    )\n        OR EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.PHANCONG_RAP\n        WHERE\n            RapID = @RapID\n    )\n        OR EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.BANGGIA\n        WHERE\n            RapID = @RapID\n    )\n        OR EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.HINHANH_RAPCHIEUPHIM\n        WHERE\n            RapID = @RapID\n    )\n        THROW 50096, N''Rạp đã có dữ liệu phụ thuộc; hãy chuyển trạng thái sang Tạm đóng thay vì xóa.'', 1;\n    -- Xóa các bản ghi thỏa điều kiện đã xác định.\n    DELETE dbo.RAPCHIEUPHIM\n    WHERE\n        RapID = @RapID;\n    SELECT\n        N''Đã xóa rạp.'' AS [Message];\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Cinema_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Cinema_Update\n    (\n    @ActorID INT,\n    @RapID INT,\n    @TenRap NVARCHAR(150),\n    @DiaChi NVARCHAR(255),\n    @ThanhPho NVARCHAR(100),\n    @SoDienThoai VARCHAR(20),\n    @MoTa NVARCHAR(500),\n    @TrangThai NVARCHAR(50)\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n    UPDATE dbo.RAPCHIEUPHIM\n    SET\n        TenRap = @TenRap,\n        DiaChi = @DiaChi,\n        ThanhPho = @ThanhPho,\n        SoDienThoai = @SoDienThoai,\n        MoTa = @MoTa,\n        TrangThai = @TrangThai\n    WHERE\n        RapID = @RapID;\n    IF @@ROWCOUNT = 0\n        THROW 50095, N''Rạp không tồn tại.'', 1;\n    SELECT\n        RapID,\n        TenRap,\n        DiaChi,\n        ThanhPho,\n        SoDienThoai,\n        MoTa,\n        TrangThai\n    FROM\n        dbo.RAPCHIEUPHIM\n    WHERE\n        RapID = @RapID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Dashboard","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/admin/admin_procedures.sql:651 (dbo.sp_Admin_Dashboard)\nCREATE   PROCEDURE dbo.sp_Admin_Dashboard\n    @ActorID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''XEM_BAO_CAO_TOANHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SELECT\n        (\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.NGUOIDUNG\n            WHERE\n                TrangThai = N''Hoạt động''\n        ) AS TongNguoiDung,\n        (\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.RAPCHIEUPHIM\n            WHERE\n                TrangThai = N''Hoạt động''\n        ) AS TongRap,\n        (\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.PHONGCHIEU\n            WHERE\n                TrangThai = N''Hoạt động''\n        ) AS TongPhongChieu,\n        (\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.PHIM\n            WHERE\n                TrangThai = N''Đang chiếu''\n        ) AS PhimDangChieu,\n        (\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.SUATCHIEU\n            WHERE\n                dbo.fn_NgayKinhDoanh(ThoiGianBatDau) = dbo.fn_HomNay()\n                AND TrangThai <> N''Đã hủy''\n        ) AS SuatChieuHomNay,\n        (\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.DONDATVE\n            WHERE\n                TrangThai IN (N''Đã thanh toán'', N''Hoàn thành'')\n        ) AS TongDonThanhCong,\n        -- STRICT 3NF: Tái dựng DoanhThu từ DONDATVE d thay vì t.SoTien\n        (\n            SELECT\n                ISNULL(SUM(CASE WHEN d.TongTienVe + d.TongTienDoAn - d.TienGiamGia < 0 THEN 0 ELSE d.TongTienVe + d.TongTienDoAn - d.TienGiamGia END), 0)\n            FROM\n                dbo.DONDATVE d\n            WHERE\n                EXISTS (SELECT 1 FROM dbo.THANHTOAN tt WHERE tt.DonDatVeID = d.DonDatVeID AND tt.TrangThai = N''Thành công'')\n        ) AS TongDoanhThuToanThoiGian,\n        (\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.DONDATVE d\n            WHERE\n                EXISTS (SELECT 1 FROM dbo.THANHTOAN tt WHERE tt.DonDatVeID = d.DonDatVeID AND tt.TrangThai = N''Thành công'')\n        ) AS TongDonThanhToanThanhCong,\n        (\n            SELECT\n                ISNULL(SUM(CASE WHEN d.TongTienVe + d.TongTienDoAn - d.TienGiamGia < 0 THEN 0 ELSE d.TongTienVe + d.TongTienDoAn - d.TienGiamGia END), 0)\n            FROM\n                dbo.DONDATVE d\n            WHERE\n                d.TrangThai = N''Đã hủy''\n                AND EXISTS (SELECT 1 FROM dbo.THANHTOAN tt WHERE tt.DonDatVeID = d.DonDatVeID AND tt.TrangThai = N''Thành công'')\n        ) AS TienThuocDonHuy,\n        (\n            SELECT\n                ISNULL(SUM(CAST(d.DiemSuDung AS DECIMAL(18, 2)) * 1000), 0)\n            FROM\n                dbo.DONDATVE d\n            WHERE\n                EXISTS (SELECT 1 FROM dbo.THANHTOAN tt WHERE tt.DonDatVeID = d.DonDatVeID AND tt.TrangThai = N''Thành công'')\n        ) AS TongGiaTriThanhToanBangDiem,\n        (\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.KHIEUNAI\n            WHERE\n                TrangThai = N''Mới''\n        ) AS KhieuNaiChuaXuLy;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Genre_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Genre_Create\n    (@ActorID INT, @TenTheLoai NVARCHAR(100))\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_THELOAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.THELOAI\n        WHERE\n            TenTheLoai = @TenTheLoai\n    )\n    BEGIN\n        ;\n        THROW 50097, N''Thể loại đã tồn tại.'', 1;\n    END\n    INSERT INTO\n        dbo.THELOAI(TenTheLoai)\n    VALUES\n        (@TenTheLoai);\n    SELECT\n        TheLoaiID,\n        TenTheLoai\n    FROM\n        dbo.THELOAI\n    WHERE\n        TheLoaiID = SCOPE_IDENTITY();\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Genre_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Genre_Delete\n    (@ActorID INT, @TheLoaiID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_THELOAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.THELOAI\n        WHERE\n            TheLoaiID = @TheLoaiID\n    )\n    BEGIN\n        ;\n        THROW 50098, N''Thể loại không tồn tại.'', 1;\n    END\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.PHIM_THELOAI\n        WHERE\n            TheLoaiID = @TheLoaiID\n    )\n    BEGIN\n        ;\n        THROW 50099, N''Thể loại đang được gán cho phim nên không thể xóa.'', 1;\n    END\n    -- Xóa các bản ghi thỏa điều kiện đã xác định.\n    DELETE FROM dbo.THELOAI\n    WHERE\n        TheLoaiID = @TheLoaiID;\n    SELECT\n        N''Đã xóa thể loại.'' AS [Message];\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Genre_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Genre_List\n    @ActorID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_THELOAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    EXEC dbo.sp_Genre_List;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Genre_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Genre_Update\n    (@ActorID INT, @TheLoaiID INT, @TenTheLoai NVARCHAR(100))\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_THELOAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.THELOAI\n        WHERE\n            TheLoaiID = @TheLoaiID\n    )\n    BEGIN\n        ;\n        THROW 50098, N''Thể loại không tồn tại.'', 1;\n    END\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.THELOAI\n        WHERE\n            TenTheLoai = @TenTheLoai\n            AND TheLoaiID <> @TheLoaiID\n    )\n    BEGIN\n        ;\n        THROW 50097, N''Thể loại đã tồn tại.'', 1;\n    END\n    -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n    UPDATE dbo.THELOAI\n    SET\n        TenTheLoai = @TenTheLoai\n    WHERE\n        TheLoaiID = @TheLoaiID;\n    SELECT\n        TheLoaiID,\n        TenTheLoai\n    FROM\n        dbo.THELOAI\n    WHERE\n        TheLoaiID = @TheLoaiID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Movie_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Movie_Create\n    (\n    @ActorID INT,\n    @TenPhim NVARCHAR(255),\n    @ThoiLuong INT,\n    @NgayKhoiChieu DATE,\n    @NgayKetThuc DATE = NULL,\n    @NgonNgu NVARCHAR(100) = NULL,\n    @PhuDe NVARCHAR(100) = NULL,\n    @DoTuoi NVARCHAR(20) = NULL,\n    @DaoDien NVARCHAR(150) = NULL,\n    @MoTa NVARCHAR(MAX) = NULL,\n    @PosterURL NVARCHAR(500) = NULL,\n    @TrailerURL NVARCHAR(500) = NULL,\n    @TheLoaiIdList VARCHAR(MAX) = NULL,\n    @NewPhimID INT OUTPUT\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        -- Mở transaction để các bước ghi được xử lý cùng nhau.\n        BEGIN TRANSACTION;\n        INSERT INTO\n            dbo.PHIM(\n                TenPhim,\n                ThoiLuong,\n                NgayKhoiChieu,\n                NgayKetThuc,\n                NgonNgu,\n                PhuDe,\n                DoTuoi,\n                DaoDien,\n                MoTa,\n                PosterURL,\n                TrailerURL,\n                TrangThai\n            )\n        VALUES\n            (\n                @TenPhim,\n                @ThoiLuong,\n                @NgayKhoiChieu,\n                @NgayKetThuc,\n                @NgonNgu,\n                @PhuDe,\n                @DoTuoi,\n                @DaoDien,\n                @MoTa,\n                @PosterURL,\n                @TrailerURL,\n                N''Đang chiếu''\n            );\n        SET\n            @NewPhimID = SCOPE_IDENTITY();\n        IF @TheLoaiIdList IS NOT NULL\n        BEGIN\n            INSERT INTO\n                dbo.PHIM_THELOAI(PhimID, TheLoaiID)\n            SELECT DISTINCT\n                @NewPhimID,\n                CAST(value AS INT)\n            FROM\n                STRING_SPLIT(@TheLoaiIdList, '','')\n            WHERE\n                LTRIM(RTRIM(value)) <> '''';\n        END\n        -- Chốt các thay đổi của transaction.\n        COMMIT TRANSACTION;\n        EXEC dbo.sp_Movie_GetDetail @PhimID = @NewPhimID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Movie_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Movie_Delete\n    (@ActorID INT, @PhimID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.PHIM\n        WHERE\n            PhimID = @PhimID\n    )\n    BEGIN\n        ;\n        THROW 50102, N''Phim không tồn tại.'', 1;\n    END\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.SUATCHIEU\n        WHERE\n            PhimID = @PhimID\n    )\n        OR EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.DANHGIAPHIM\n        WHERE\n            PhimID = @PhimID\n    )\n    BEGIN\n        ;\n        THROW 50104, N''Phim đã có suất chiếu hoặc đánh giá. Hãy chuyển trạng thái sang Ngừng chiếu thay vì xóa.'', 1;\n    END\n    -- Xóa các bản ghi thỏa điều kiện đã xác định.\n    DELETE FROM dbo.PHIM\n    WHERE\n        PhimID = @PhimID;\n    SELECT\n        N''Đã xóa phim.'' AS [Message];\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Movie_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Movie_Update\n    (\n    @ActorID INT,\n    @PhimID INT,\n    @TenPhim NVARCHAR(255),\n    @ThoiLuong INT,\n    @NgayKhoiChieu DATE,\n    @NgayKetThuc DATE = NULL,\n    @NgonNgu NVARCHAR(100) = NULL,\n    @PhuDe NVARCHAR(100) = NULL,\n    @DoTuoi NVARCHAR(20) = NULL,\n    @DaoDien NVARCHAR(150) = NULL,\n    @MoTa NVARCHAR(MAX) = NULL,\n    @PosterURL NVARCHAR(500) = NULL,\n    @TrailerURL NVARCHAR(500) = NULL,\n    @TrangThai NVARCHAR(50),\n    @TheLoaiIdList VARCHAR(MAX) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        -- Mở transaction để các bước ghi được xử lý cùng nhau.\n        BEGIN TRANSACTION;\n        -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n        UPDATE dbo.PHIM\n        SET\n            TenPhim = @TenPhim,\n            ThoiLuong = @ThoiLuong,\n            NgayKhoiChieu = @NgayKhoiChieu,\n            NgayKetThuc = @NgayKetThuc,\n            NgonNgu = @NgonNgu,\n            PhuDe = @PhuDe,\n            DoTuoi = @DoTuoi,\n            DaoDien = @DaoDien,\n            MoTa = @MoTa,\n            PosterURL = @PosterURL,\n            TrailerURL = @TrailerURL,\n            TrangThai = @TrangThai\n        WHERE\n            PhimID = @PhimID;\n        IF @@ROWCOUNT = 0\n            THROW 50102, N''Phim không tồn tại.'', 1;\n        IF @TheLoaiIdList IS NOT NULL\n        BEGIN\n            -- Xóa các bản ghi thỏa điều kiện đã xác định.\n            DELETE FROM dbo.PHIM_THELOAI\n            WHERE\n                PhimID = @PhimID;\n            INSERT INTO\n                dbo.PHIM_THELOAI(PhimID, TheLoaiID)\n            SELECT DISTINCT\n                @PhimID,\n                CAST(value AS INT)\n            FROM\n                STRING_SPLIT(@TheLoaiIdList, '','')\n            WHERE\n                LTRIM(RTRIM(value)) <> '''';\n        END\n        -- Chốt các thay đổi của transaction.\n        COMMIT TRANSACTION;\n        EXEC dbo.sp_Movie_GetDetail @PhimID = @PhimID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_MovieActor_Set","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_MovieActor_Set\n    (@ActorID INT, @PhimID INT, @DanhSachJson NVARCHAR(MAX))\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SET XACT_ABORT ON;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END,\n        @LockedMovie INT,\n        @Requested INT,\n        @Matched INT;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION AdminMovieActorSet;\n        -- Serialize replacements and protect the parent against concurrent deletion.\n        SELECT\n            @LockedMovie = PhimID\n        FROM\n            dbo.PHIM\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            PhimID = @PhimID;\n        IF @LockedMovie IS NULL\n            THROW 50102, N''Phim không tồn tại.'', 1;\n        IF @DanhSachJson IS NULL\n            OR ISJSON(@DanhSachJson) <> 1\n            THROW 50103, N''Danh sách diễn viên phải là JSON hợp lệ.'', 1;\n        IF LEFT(\n            LTRIM(\n                REPLACE(\n                    REPLACE(REPLACE(@DanhSachJson, NCHAR(9), N'' ''), NCHAR(10), N'' ''),\n                    NCHAR(13),\n                    N'' ''\n                )\n            ),\n            1\n        ) <> N''[''\n            THROW 50103, N''Danh sách diễn viên phải là JSON array.'', 1;\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                OPENJSON(@DanhSachJson)\n            WHERE\n                [type] <> 5\n        )\n            THROW 50103, N''Mỗi diễn viên phải là một JSON object.'', 1;\n        -- Keep raw values/types/counts until validation, avoiding implicit conversion,\n        -- truncation and silent omission. SQL roles remain nullable as in the schema.\n        DECLARE @Raw\n        TABLE (\n            IDValue NVARCHAR(MAX),\n            IDType INT,\n            IDCount INT,\n            RoleValue NVARCHAR(MAX),\n            RoleType INT,\n            RoleCount INT\n        );\n        INSERT\n            @Raw\n        SELECT\n            p.IDValue,\n            p.IDType,\n            p.IDCount,\n            p.RoleValue,\n            p.RoleType,\n            p.RoleCount\n        FROM\n            OPENJSON(@DanhSachJson) item\n            CROSS APPLY(\n                SELECT\n                    MAX(\n                        CASE\n                            WHEN [key] = N''DienVienID'' THEN [value]\n                        END\n                    ) IDValue,\n                    MAX(\n                        CASE\n                            WHEN [key] = N''DienVienID'' THEN [type]\n                        END\n                    ) IDType,\n                    COUNT(\n                        CASE\n                            WHEN [key] = N''DienVienID'' THEN 1\n                        END\n                    ) IDCount,\n                    MAX(\n                        CASE\n                            WHEN [key] = N''VaiDien'' THEN [value]\n                        END\n                    ) RoleValue,\n                    MAX(\n                        CASE\n                            WHEN [key] = N''VaiDien'' THEN [type]\n                        END\n                    ) RoleType,\n                    COUNT(\n                        CASE\n                            WHEN [key] = N''VaiDien'' THEN 1\n                        END\n                    ) RoleCount\n                FROM\n                    OPENJSON(item.[value])\n            ) p;\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                @Raw\n            WHERE\n                IDCount <> 1\n                OR IDType <> 2\n                OR IDValue COLLATE Latin1_General_100_BIN2 LIKE N''%[^0-9]%''\n                OR TRY_CONVERT(INT, IDValue) IS NULL\n                OR TRY_CONVERT(INT, IDValue) < 1\n                OR RoleCount > 1\n                OR RoleType NOT IN (0, 1)\n                OR DATALENGTH(RoleValue) > 300\n        )\n            THROW 50103, N''Mã hoặc vai diễn không hợp lệ.'', 1;\n        DECLARE @Cast\n        TABLE (DienVienID INT NOT NULL, VaiDien NVARCHAR(150) NULL);\n        INSERT\n            @Cast\n        SELECT\n            CONVERT(INT, IDValue),\n            CONVERT(NVARCHAR(150), RoleValue)\n        FROM\n            @Raw;\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                @Cast\n            GROUP BY\n                DienVienID\n            HAVING\n                COUNT(*) > 1\n        )\n            THROW 50103, N''Danh sách chứa mã diễn viên trùng lặp.'', 1;\n        SELECT\n            @Requested = COUNT(*)\n        FROM\n            @Cast;\n        -- Shared actor key locks live until transaction end. Actor Delete takes X\n        -- on that same parent before checking associations, including under RCSI.\n        SELECT\n            @Matched = COUNT(*)\n        FROM\n            @Cast c\n            INNER JOIN dbo.DIENVIEN dv\n        WITH\n            (HOLDLOCK) ON dv.DienVienID = c.DienVienID;\n        IF @Matched <> @Requested\n            THROW 50100, N''Diễn viên không tồn tại.'', 1;\n        -- Xóa các bản ghi thỏa điều kiện đã xác định.\n        DELETE FROM dbo.PHIM_DIENVIEN\n        WHERE\n            PhimID = @PhimID;\n        INSERT INTO\n            dbo.PHIM_DIENVIEN(PhimID, DienVienID, VaiDien)\n        SELECT\n            @PhimID,\n            DienVienID,\n            VaiDien\n        FROM\n            @Cast;\n        IF @@ROWCOUNT <> @Requested\n            THROW 50103, N''Danh sách diễn viên chưa được lưu đầy đủ.'', 1;\n        -- Snapshot this replacement''s persisted response while the movie is locked.\n        DECLARE @Result\n        TABLE (\n            PhimID INT,\n            DienVienID INT,\n            HoTen NVARCHAR(150),\n            VaiDien NVARCHAR(150)\n        );\n        INSERT\n            @Result\n        SELECT\n            pd.PhimID,\n            dv.DienVienID,\n            dv.HoTen,\n            pd.VaiDien\n        FROM\n            dbo.PHIM_DIENVIEN pd\n            INNER JOIN dbo.DIENVIEN dv ON dv.DienVienID = pd.DienVienID\n        WHERE\n            pd.PhimID = @PhimID;\n        IF(\n            SELECT\n                COUNT(*)\n            FROM\n                @Result\n        ) <> @Requested\n            THROW 50103, N''Danh sách diễn viên chưa được lưu đầy đủ.'', 1;\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        SELECT\n            PhimID,\n            DienVienID,\n            HoTen,\n            VaiDien\n        FROM\n            @Result\n        ORDER BY\n            DienVienID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION;\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION AdminMovieActorSet;\n        END;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Permission_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Permission_Create\n    (\n    @ActorID INT,\n    @MaQuyen VARCHAR(50),\n    @TenQuyen NVARCHAR(100),\n    @MoTa NVARCHAR(255) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- ADM-03/04/05 RETIRED. Kept as a refusal point; no RBAC writes remain.\n    THROW 50405, N''Vai trò, danh mục quyền và ma trận quyền là cố định.'', 1;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Permission_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Permission_Delete\n    (@ActorID INT, @QuyenID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- ADM-03/04/05 RETIRED. Kept as a refusal point; no RBAC writes remain.\n    THROW 50405, N''Vai trò, danh mục quyền và ma trận quyền là cố định.'', 1;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Permission_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Permission_List\n    @ActorID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_QUYEN'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SELECT\n        QuyenID,\n        MaQuyen,\n        TenQuyen,\n        MoTa\n    FROM\n        dbo.QUYEN\n    ORDER BY\n        MaQuyen;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Permission_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Permission_Update\n    (\n    @ActorID INT,\n    @QuyenID INT,\n    @TenQuyen NVARCHAR(100),\n    @MoTa NVARCHAR(255) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- ADM-03/04/05 RETIRED. Kept as a refusal point; no RBAC writes remain.\n    THROW 50405, N''Vai trò, danh mục quyền và ma trận quyền là cố định.'', 1;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Product_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Product_Create\n    (\n    @ActorID INT,\n    @TenSanPham NVARCHAR(150),\n    @LoaiSanPham NVARCHAR(50),\n    @Gia DECIMAL(18, 2),\n    @MoTa NVARCHAR(255) = NULL,\n    @HinhAnh NVARCHAR(500) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SANPHAM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    INSERT INTO\n        dbo.SANPHAM(TenSanPham, LoaiSanPham, Gia, MoTa, HinhAnh, TrangThai)\n    VALUES\n        (@TenSanPham, @LoaiSanPham, @Gia, @MoTa, @HinhAnh, N''Đang bán'');\n    SELECT\n        SanPhamID,\n        TenSanPham,\n        LoaiSanPham,\n        Gia,\n        MoTa,\n        HinhAnh,\n        TrangThai\n    FROM\n        dbo.SANPHAM\n    WHERE\n        SanPhamID = SCOPE_IDENTITY();\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Product_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Product_Delete\n    (@ActorID INT, @SanPhamID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SANPHAM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.SANPHAM\n        WHERE\n            SanPhamID = @SanPhamID\n    )\n    BEGIN\n        ;\n        THROW 50105, N''Sản phẩm không tồn tại.'', 1;\n    END\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.CHITIETDOAN\n        WHERE\n            SanPhamID = @SanPhamID\n    )\n    BEGIN\n        ;\n        THROW 50106, N''Sản phẩm đã có trong đơn hàng. Hãy chuyển trạng thái sang Ngừng bán thay vì xóa.'', 1;\n    END\n    -- Xóa các bản ghi thỏa điều kiện đã xác định.\n    DELETE FROM dbo.SANPHAM\n    WHERE\n        SanPhamID = @SanPhamID;\n    SELECT\n        N''Đã xóa sản phẩm.'' AS [Message];\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Product_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Product_Update\n    (\n    @ActorID INT,\n    @SanPhamID INT,\n    @TenSanPham NVARCHAR(150),\n    @LoaiSanPham NVARCHAR(50),\n    @Gia DECIMAL(18, 2),\n    @MoTa NVARCHAR(255),\n    @HinhAnh NVARCHAR(500),\n    @TrangThai NVARCHAR(50)\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SANPHAM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n    UPDATE dbo.SANPHAM\n    SET\n        TenSanPham = @TenSanPham,\n        LoaiSanPham = @LoaiSanPham,\n        Gia = @Gia,\n        MoTa = @MoTa,\n        HinhAnh = @HinhAnh,\n        TrangThai = @TrangThai\n    WHERE\n        SanPhamID = @SanPhamID;\n    IF @@ROWCOUNT = 0\n        THROW 50105, N''Sản phẩm không tồn tại.'', 1;\n    SELECT\n        SanPhamID,\n        TenSanPham,\n        LoaiSanPham,\n        Gia,\n        MoTa,\n        HinhAnh,\n        TrangThai\n    FROM\n        dbo.SANPHAM\n    WHERE\n        SanPhamID = @SanPhamID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Promotion_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Promotion_Create\n    (\n    @ActorID INT,\n    @MaCode VARCHAR(50),\n    @MoTa NVARCHAR(255) = NULL,\n    @LoaiGiamGia NVARCHAR(20),\n    @GiaTriGiam DECIMAL(18, 2),\n    @DonHangToiThieu DECIMAL(18, 2) = 0,\n    @GiamToiDa DECIMAL(18, 2) = NULL,\n    @NgayBatDau DATETIME2,\n    @NgayKetThuc DATETIME2,\n    @SoLuong INT\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_KHUYENMAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.KHUYENMAI\n        WHERE\n            MaCode = @MaCode\n    )\n    BEGIN\n        ;\n        THROW 50072, N''Mã khuyến mãi đã tồn tại.'', 1;\n    END\n    INSERT INTO\n        dbo.KHUYENMAI(\n            MaCode,\n            MoTa,\n            LoaiGiamGia,\n            GiaTriGiam,\n            DonHangToiThieu,\n            GiamToiDa,\n            NgayBatDau,\n            NgayKetThuc,\n            SoLuong,\n            SoLuongDaDung,\n            TrangThai\n        )\n    VALUES\n        (\n            @MaCode,\n            @MoTa,\n            @LoaiGiamGia,\n            @GiaTriGiam,\n            @DonHangToiThieu,\n            @GiamToiDa,\n            @NgayBatDau,\n            @NgayKetThuc,\n            @SoLuong,\n            0,\n            N''Hoạt động''\n        );\n    SELECT\n        [KhuyenMaiID],\n        [MaCode],\n        [MoTa],\n        [LoaiGiamGia],\n        [GiaTriGiam],\n        [DonHangToiThieu],\n        [GiamToiDa],\n        [NgayBatDau],\n        [NgayKetThuc],\n        [SoLuong],\n        [SoLuongDaDung],\n        [TrangThai]\n    FROM\n        dbo.KHUYENMAI\n    WHERE\n        KhuyenMaiID = SCOPE_IDENTITY();\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Promotion_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Promotion_Delete\n    (@ActorID INT, @KhuyenMaiID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_KHUYENMAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END,\n        @LockedID INT,\n        @LockedUsage INT,\n        @Code VARCHAR(50);\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION AdminPromotionDelete;\n        -- Discovery is an RCSI read. Acquire the same code-index -> clustered-row\n        -- locks as booking, before relationship reads or DELETE index maintenance.\n        SELECT\n            @Code = MaCode\n        FROM\n            dbo.KHUYENMAI\n        WHERE\n            KhuyenMaiID = @KhuyenMaiID;\n        SELECT\n            @LockedID = KhuyenMaiID,\n            @LockedUsage = SoLuongDaDung\n        FROM\n            dbo.KHUYENMAI\n        WITH\n            (\n                UPDLOCK,\n                HOLDLOCK,\n                INDEX(UQ_KHUYENMAI_MaCode)\n            )\n        WHERE\n            MaCode = @Code;\n        IF @LockedID IS NULL\n            OR @LockedID <> @KhuyenMaiID\n            OR @LockedUsage < 0\n            THROW 50107, N''Khuyến mãi không tồn tại.'', 1;\n        -- Under canonical RCSI the relationship read does not retain order locks.\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.DONDATVE\n            WHERE\n                KhuyenMaiID = @KhuyenMaiID\n        )\n            THROW 50108, N''Khuyến mãi đã được dùng trong đơn hàng. Hãy chuyển trạng thái sang Tạm dừng thay vì xóa.'', 1;\n        -- Xóa các bản ghi thỏa điều kiện đã xác định.\n        DELETE FROM dbo.KHUYENMAI\n        WHERE\n            KhuyenMaiID = @KhuyenMaiID;\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        SELECT\n            N''Đã xóa khuyến mãi.'' AS [Message];\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION;\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION AdminPromotionDelete;\n        END;\n        THROW;\n    END CATCH;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Promotion_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Promotion_List\n    @ActorID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_KHUYENMAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SELECT\n        KhuyenMaiID,\n        MaCode,\n        MoTa,\n        LoaiGiamGia,\n        GiaTriGiam,\n        DonHangToiThieu,\n        GiamToiDa,\n        NgayBatDau,\n        NgayKetThuc,\n        SoLuong,\n        SoLuongDaDung,\n        TrangThai\n    FROM\n        dbo.KHUYENMAI\n    ORDER BY\n        NgayBatDau DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Promotion_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Promotion_Update\n    (\n    @ActorID INT,\n    @KhuyenMaiID INT,\n    @MoTa NVARCHAR(255) = NULL,\n    @LoaiGiamGia NVARCHAR(20),\n    @GiaTriGiam DECIMAL(18, 2),\n    @DonHangToiThieu DECIMAL(18, 2) = 0,\n    @GiamToiDa DECIMAL(18, 2) = NULL,\n    @NgayBatDau DATETIME2,\n    @NgayKetThuc DATETIME2,\n    @SoLuong INT,\n    @TrangThai NVARCHAR(50)\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_KHUYENMAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.KHUYENMAI\n        WHERE\n            KhuyenMaiID = @KhuyenMaiID\n    )\n    BEGIN\n        ;\n        THROW 50107, N''Khuyến mãi không tồn tại.'', 1;\n    END\n    -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n    UPDATE dbo.KHUYENMAI\n    SET\n        MoTa = @MoTa,\n        LoaiGiamGia = @LoaiGiamGia,\n        GiaTriGiam = @GiaTriGiam,\n        DonHangToiThieu = @DonHangToiThieu,\n        GiamToiDa = @GiamToiDa,\n        NgayBatDau = @NgayBatDau,\n        NgayKetThuc = @NgayKetThuc,\n        SoLuong = @SoLuong,\n        TrangThai = @TrangThai\n    WHERE\n        KhuyenMaiID = @KhuyenMaiID;\n    SELECT\n        KhuyenMaiID,\n        MaCode,\n        MoTa,\n        LoaiGiamGia,\n        GiaTriGiam,\n        DonHangToiThieu,\n        GiamToiDa,\n        NgayBatDau,\n        NgayKetThuc,\n        SoLuong,\n        SoLuongDaDung,\n        TrangThai\n    FROM\n        dbo.KHUYENMAI\n    WHERE\n        KhuyenMaiID = @KhuyenMaiID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Report_Revenue","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Report_Revenue\n    (\n    @ActorID INT,\n    @TuNgay DATE = NULL,\n    @DenNgay DATE = NULL,\n    @RapID INT = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''XEM_BAO_CAO_TOANHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Existing cash-receipt contract: successful payment snapshots, independent of\n    -- order status. Compensation is loyalty points, not a cash refund.\n    -- One row/order keeps ticket, food and discount snapshots from being multiplied.\n    CREATE TABLE #DonDaThu(\n        DonDatVeID INT PRIMARY KEY,\n        RapID INT NOT NULL,\n        PhimID INT NOT NULL,\n        NgayThu DATE NOT NULL,\n        TongTienVe DECIMAL(18, 2),\n        TongTienDoAn DECIMAL(18, 2),\n        TienGiamGia DECIMAL(18, 2),\n        DiemSuDung INT,\n        TrangThaiDon NVARCHAR(50),\n        TienDaThu DECIMAL(18, 2),\n        SoVe INT\n    );\n    INSERT INTO\n        #DonDaThu(\n            DonDatVeID,\n            RapID,\n            PhimID,\n            NgayThu,\n            TongTienVe,\n            TongTienDoAn,\n            TienGiamGia,\n            DiemSuDung,\n            TrangThaiDon,\n            TienDaThu,\n            SoVe\n        )\n    SELECT\n        ddv.DonDatVeID,\n        pc.RapID,\n        sc.PhimID,\n        dbo.fn_NgayKinhDoanh(MAX(ISNULL(tt.NgayThanhToan, tt.NgayTao))),\n        ddv.TongTienVe,\n        ddv.TongTienDoAn,\n        ddv.TienGiamGia,\n        ddv.DiemSuDung,\n        ddv.TrangThai,\n        -- Tiền thực thu = tiền thật đã trả sau tổng mọi khoản giảm; một dòng/đơn.\n        CASE WHEN ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia < 0 THEN 0 ELSE ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia END,\n        (\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.CHITIETVE cv\n            WHERE\n                cv.DonDatVeID = ddv.DonDatVeID\n                AND cv.TrangThai <> N''Đã hủy''\n        )\n    FROM\n        dbo.DONDATVE ddv\n        INNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\n        INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\n        INNER JOIN dbo.THANHTOAN tt ON tt.DonDatVeID = ddv.DonDatVeID\n        AND tt.TrangThai = N''Thành công''\n    WHERE\n        (\n            @RapID IS NULL\n            OR pc.RapID = @RapID\n        )\n    GROUP BY\n        ddv.DonDatVeID,\n        pc.RapID,\n        sc.PhimID,\n        ddv.TongTienVe,\n        ddv.TongTienDoAn,\n        ddv.TienGiamGia,\n        ddv.DiemSuDung,\n        ddv.TrangThai\n    HAVING\n        (\n            @TuNgay IS NULL\n            OR dbo.fn_NgayKinhDoanh(MAX(ISNULL(tt.NgayThanhToan, tt.NgayTao))) >= @TuNgay\n        )\n        AND (\n            @DenNgay IS NULL\n            OR dbo.fn_NgayKinhDoanh(MAX(ISNULL(tt.NgayThanhToan, tt.NgayTao))) <= @DenNgay\n        );\n    -- Recordset 1: Summary (same metrics as the former second recordset).\n    SELECT\n        -- Đơn có thanh toán thành công (tiền và/hoặc điểm). Các cột sau tách rõ từng loại mẫu số.\n        COUNT(DonDatVeID) AS TongSoDonToanHeThong,\n        ISNULL(SUM(CASE WHEN TrangThaiDon IN (N''Đã thanh toán'', N''Hoàn thành'') THEN 1 ELSE 0 END), 0) AS SoDonHopLe,\n        ISNULL(SUM(CASE WHEN TienDaThu > 0 THEN 1 ELSE 0 END), 0) AS SoDonCoTienThucThu,\n        ISNULL(SUM(CASE WHEN TrangThaiDon = N''Đã hủy'' THEN TienDaThu ELSE 0 END), 0) AS TienThuocDonHuy,\n        ISNULL(SUM(CAST(DiemSuDung AS DECIMAL(18, 2)) * 1000), 0) AS TongGiaTriThanhToanBangDiem,\n        ISNULL(SUM(DiemSuDung), 0) AS TongDiemSuDung,\n        ISNULL(SUM(SoVe), 0) AS TongSoVeBan,\n        ISNULL(SUM(TongTienVe), 0) AS TongDoanhThuVe,\n        ISNULL(SUM(TongTienDoAn), 0) AS TongDoanhThuDoAn,\n        ISNULL(SUM(TienGiamGia), 0) AS TongTienGiam,\n        ISNULL(SUM(TienDaThu), 0) AS TongDoanhThuThucTe\n    FROM\n        #DonDaThu;\n    -- Recordset 2: RevenueByCinema; preserve zero rows for existing cinemas.\n    SELECT\n        r.RapID,\n        r.TenRap,\n        r.ThanhPho,\n        COUNT(d.DonDatVeID) AS SoDon,\n        ISNULL(SUM(d.SoVe), 0) AS SoVeBan,\n        ISNULL(SUM(d.TongTienVe), 0) AS DoanhThuVe,\n        ISNULL(SUM(d.TongTienDoAn), 0) AS DoanhThuDoAn,\n        ISNULL(SUM(d.TienGiamGia), 0) AS TongTienGiam,\n        ISNULL(SUM(d.TienDaThu), 0) AS DoanhThuThucTe,\n        ISNULL(SUM(CAST(d.DiemSuDung AS DECIMAL(18, 2)) * 1000), 0) AS GiaTriThanhToanBangDiem\n    FROM\n        dbo.RAPCHIEUPHIM r\n        LEFT JOIN #DonDaThu d ON d.RapID = r.RapID\n    WHERE\n        (\n            @RapID IS NULL\n            OR r.RapID = @RapID\n        )\n    GROUP BY\n        r.RapID,\n        r.TenRap,\n        r.ThanhPho\n    ORDER BY\n        r.RapID;\n    -- Recordset 3: RevenueByMovie. Every order has exactly one show/movie;\n    -- its complete receipt (including food/discount) belongs to that movie.\n    SELECT\n        p.PhimID,\n        p.TenPhim,\n        COUNT(d.DonDatVeID) AS SoDon,\n        SUM(d.SoVe) AS SoVeBan,\n        SUM(d.TongTienVe) AS DoanhThuVe,\n        SUM(d.TongTienDoAn) AS DoanhThuDoAn,\n        SUM(d.TienGiamGia) AS TongTienGiam,\n        SUM(d.TienDaThu) AS DoanhThuThucTe,\n        SUM(CAST(d.DiemSuDung AS DECIMAL(18, 2)) * 1000) AS GiaTriThanhToanBangDiem\n    FROM\n        #DonDaThu d\n        INNER JOIN dbo.PHIM p ON p.PhimID = d.PhimID\n    GROUP BY\n        p.PhimID,\n        p.TenPhim\n    ORDER BY\n        p.PhimID;\n    -- Recordset 4: RevenueByDate, inclusive Vietnam business-date bounds.\n    SELECT\n        NgayThu AS Ngay,\n        COUNT(DonDatVeID) AS SoDon,\n        SUM(SoVe) AS SoVeBan,\n        SUM(TongTienVe) AS DoanhThuVe,\n        SUM(TongTienDoAn) AS DoanhThuDoAn,\n        SUM(TienGiamGia) AS TongTienGiam,\n        SUM(TienDaThu) AS DoanhThuThucTe,\n        SUM(CAST(DiemSuDung AS DECIMAL(18, 2)) * 1000) AS GiaTriThanhToanBangDiem\n    FROM\n        #DonDaThu\n    GROUP BY\n        NgayThu\n    ORDER BY\n        NgayThu;\n    DROP TABLE #DonDaThu;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Role_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Role_Create\n    (\n    @ActorID INT,\n    @MaVaiTro VARCHAR(50),\n    @TenVaiTro NVARCHAR(100),\n    @MoTa NVARCHAR(255) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- ADM-03/04/05 RETIRED. Kept as a refusal point; no RBAC writes remain.\n    THROW 50405, N''Vai trò, danh mục quyền và ma trận quyền là cố định.'', 1;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Role_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Role_Delete\n    (@ActorID INT, @VaiTroID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- ADM-03/04/05 RETIRED. Kept as a refusal point; no RBAC writes remain.\n    THROW 50405, N''Vai trò, danh mục quyền và ma trận quyền là cố định.'', 1;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Role_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Role_List\n    @ActorID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_NGUOIDUNG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Read-only lookup for the existing internal-account creation workflow.\n    SELECT\n        VaiTroID,\n        MaVaiTro,\n        TenVaiTro,\n        MoTa\n    FROM\n        dbo.VAITRO\n    WHERE\n        MaVaiTro IN (''ADMIN'', ''QUAN_LY_RAP'', ''CSKH'', ''KHACH_HANG'')\n    ORDER BY\n        VaiTroID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_Role_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_Role_Update\n    (\n    @ActorID INT,\n    @VaiTroID INT,\n    @TenVaiTro NVARCHAR(100),\n    @MoTa NVARCHAR(255) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- ADM-03/04/05 RETIRED. Kept as a refusal point; no RBAC writes remain.\n    THROW 50405, N''Vai trò, danh mục quyền và ma trận quyền là cố định.'', 1;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_RolePermission_Set","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/admin/admin_procedures.sql:156 (dbo.sp_Admin_RolePermission_Set)\nCREATE   PROCEDURE dbo.sp_Admin_RolePermission_Set\n    (\n    @ActorID INT,\n    @VaiTroID INT,\n    @QuyenIdList VARCHAR(MAX)\n    -- ''1,2,3,4''\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- ADM-03/04/05 RETIRED. Kept as a refusal point; no RBAC writes remain.\n    THROW 50405, N''Vai trò, danh mục quyền và ma trận quyền là cố định.'', 1;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_User_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/admin/admin_procedures.sql:75 (dbo.sp_Admin_User_Create)\nCREATE   PROCEDURE dbo.sp_Admin_User_Create\n    (\n    @ActorID INT,\n    @HoTen NVARCHAR(100),\n    @Email VARCHAR(150),\n    @MatKhauHash VARCHAR(255),\n    @SoDienThoai VARCHAR(20) = NULL,\n    @VaiTroID INT\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_NGUOIDUNG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION AdminCreateUser;\n        -- R7.2 approved policy: internal Manager/CSKH/Admin accounts only.\n        -- Only fixed internal roles may be assigned at account creation.\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.VAITRO\n            WITH\n                (HOLDLOCK)\n            WHERE\n                VaiTroID = @VaiTroID\n                AND MaVaiTro IN (''QUAN_LY_RAP'', ''CSKH'', ''ADMIN'')\n        )\n            THROW 50404, N''Admin chỉ được tạo tài khoản Manager, CSKH hoặc Admin.'', 1;\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.NGUOIDUNG\n            WHERE\n                Email = @Email\n        )\n        BEGIN\n            ;\n            THROW 50070, N''Email đã tồn tại.'', 1;\n        END\n        INSERT INTO\n            dbo.NGUOIDUNG(VaiTroID, HoTen, Email, MatKhau, SoDienThoai, NgayTao, TrangThai)\n        VALUES\n            (\n                @VaiTroID,\n                @HoTen,\n                @Email,\n                @MatKhauHash,\n                @SoDienThoai,\n                dbo.fn_BayGio(),\n                N''Hoạt động''\n            );\n        DECLARE @NewUserID INT = SCOPE_IDENTITY();\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        SELECT\n            nd.NguoiDungID,\n            nd.HoTen,\n            nd.Email,\n            nd.SoDienThoai,\n            vt.MaVaiTro,\n            vt.TenVaiTro,\n            nd.TrangThai\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NewUserID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION AdminCreateUser;\n        END;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_User_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_User_List\n    (\n    @ActorID INT,\n    @VaiTroID INT = NULL,\n    @TrangThai NVARCHAR(50) = NULL,\n    @SearchTerm NVARCHAR(100) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_NGUOIDUNG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SELECT\n        nd.NguoiDungID,\n        nd.HoTen,\n        nd.Email,\n        nd.SoDienThoai,\n        nd.NgayTao,\n        nd.TrangThai,\n        vt.VaiTroID,\n        vt.MaVaiTro,\n        vt.TenVaiTro,\n        hk.DiemTichLuy\n    FROM\n        dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID\n        LEFT JOIN dbo.HOSOKHACHHANG hk ON nd.NguoiDungID = hk.NguoiDungID\n    WHERE\n        (\n            @VaiTroID IS NULL\n            OR nd.VaiTroID = @VaiTroID\n        )\n        AND (\n            @TrangThai IS NULL\n            OR nd.TrangThai = @TrangThai\n        )\n        AND (\n            @SearchTerm IS NULL\n            OR nd.HoTen LIKE ''%'' + @SearchTerm + ''%''\n            OR nd.Email LIKE ''%'' + @SearchTerm + ''%''\n            OR nd.SoDienThoai LIKE ''%'' + @SearchTerm + ''%''\n        )\n    ORDER BY\n        nd.NgayTao DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Admin_User_UpdateStatus","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Admin_User_UpdateStatus\n    (\n    @ActorID INT,\n    @NguoiDungID INT,\n    @TrangThai NVARCHAR(50)\n    -- ''Hoạt động'', ''Bị khóa''\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_NGUOIDUNG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n    UPDATE dbo.NGUOIDUNG\n    SET\n        TrangThai = @TrangThai\n    WHERE\n        NguoiDungID = @NguoiDungID;\n    IF @@ROWCOUNT = 0\n        THROW 50403, N''Người dùng không tồn tại.'', 1;\n    SELECT\n        NguoiDungID,\n        HoTen,\n        Email,\n        TrangThai\n    FROM\n        dbo.NGUOIDUNG\n    WHERE\n        NguoiDungID = @NguoiDungID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Auth_Login","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/auth/auth_procedures.sql:132 (dbo.sp_Auth_Login)\nCREATE   PROCEDURE dbo.sp_Auth_Login\n    (@Email VARCHAR(150))\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- Mật khẩu được băm (bcrypt) và so sánh ở backend. Thủ tục này chỉ trả về hash để backend đối chiếu.\n    -- Recordset 1: 0 dòng nếu email không tồn tại. Recordset 2, 3 chỉ có dữ liệu khi tài khoản đang hoạt động.\n    DECLARE @NguoiDungID INT;\n    DECLARE @VaiTroID INT;\n    DECLARE @TrangThai NVARCHAR(50);\n    SELECT\n        @NguoiDungID = NguoiDungID,\n        @VaiTroID = VaiTroID,\n        @TrangThai = TrangThai\n    FROM\n        dbo.NGUOIDUNG\n    WHERE\n        Email = @Email;\n    -- Recordset 1: Thông tin người dùng + hash mật khẩu\n    SELECT\n        nd.NguoiDungID,\n        nd.HoTen,\n        nd.Email,\n        nd.SoDienThoai,\n        nd.MatKhau AS MatKhauHash,\n        nd.TrangThai,\n        vt.VaiTroID,\n        vt.MaVaiTro,\n        vt.TenVaiTro,\n        hk.DiemTichLuy\n    FROM\n        dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID\n        LEFT JOIN dbo.HOSOKHACHHANG hk ON nd.NguoiDungID = hk.NguoiDungID\n    WHERE\n        nd.NguoiDungID = @NguoiDungID;\n    -- Recordset 2: Danh sách quyền (Permissions)\n    SELECT DISTINCT\n        q.QuyenID,\n        q.MaQuyen,\n        q.TenQuyen\n    FROM\n        dbo.VAITRO_QUYEN vq\n        INNER JOIN dbo.QUYEN q ON vq.QuyenID = q.QuyenID\n    WHERE\n        vq.VaiTroID = @VaiTroID\n        AND @TrangThai = N''Hoạt động'';\n    -- Recordset 3: Danh sách rạp được phân công còn hiệu lực (Quản lý rạp)\n    SELECT\n        pcr.RapID,\n        r.TenRap,\n        r.ThanhPho,\n        pcr.NgayBatDau,\n        pcr.NgayKetThuc\n    FROM\n        dbo.PHANCONG_RAP pcr\n        INNER JOIN dbo.RAPCHIEUPHIM r ON pcr.RapID = r.RapID\n    WHERE\n        pcr.NguoiDungID = @NguoiDungID\n        AND @TrangThai = N''Hoạt động''\n        AND pcr.TrangThai = N''Hiệu lực''\n        AND dbo.fn_HomNay() >= pcr.NgayBatDau\n        AND (\n            pcr.NgayKetThuc IS NULL\n            OR dbo.fn_HomNay() <= pcr.NgayKetThuc\n        );\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Auth_RegisterCustomer","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/auth/auth_procedures.sql:18 (dbo.sp_Auth_RegisterCustomer)\nCREATE   PROCEDURE dbo.sp_Auth_RegisterCustomer\n    (\n    @HoTen NVARCHAR(100),\n    @Email VARCHAR(150),\n    @MatKhauHash VARCHAR(255),\n    @SoDienThoai VARCHAR(20) = NULL,\n    @NgaySinh DATE = NULL,\n    @GioiTinh NVARCHAR(10) = NULL,\n    @NewUserId INT OUTPUT\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    IF @NgaySinh > dbo.fn_HomNay()\n        THROW 50400, N''Ngày sinh không được ở tương lai.'', 1;\n    -- Transaction lồng nhau đúng kỹ thuật:\n    --  * Gọi độc lập (@@TRANCOUNT = 0): thủ tục tự BEGIN/COMMIT/ROLLBACK.\n    --  * Gọi trong transaction của bên gọi: dùng SAVE TRANSACTION, khi lỗi chỉ rollback phần của mình,\n    --    không hủy transaction ngoài.\n    DECLARE @TuMoTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @TuMoTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION;\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION sp_Auth_RegisterCustomer;\n        -- 1. Kiểm tra email đã tồn tại chưa\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.NGUOIDUNG\n            WHERE\n                Email = @Email\n        )\n        BEGIN\n            ;\n            THROW 50010, N''Email này đã được sử dụng trong hệ thống.'', 1;\n        END\n        -- 2. Kiểm tra số điện thoại (nếu có)\n        IF @SoDienThoai IS NOT NULL\n            AND EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.NGUOIDUNG\n            WHERE\n                SoDienThoai = @SoDienThoai\n        )\n        BEGIN\n            ;\n            THROW 50011, N''Số điện thoại này đã được sử dụng trong hệ thống.'', 1;\n        END\n        -- 3. Lấy VaiTroID của vai trò KHACH_HANG\n        DECLARE @VaiTroID INT;\n        SELECT\n            @VaiTroID = VaiTroID\n        FROM\n            dbo.VAITRO\n        WHERE\n            MaVaiTro = ''KHACH_HANG'';\n        IF @VaiTroID IS NULL\n        BEGIN\n            ;\n            THROW 50012, N''Vai trò KHACH_HANG chưa được cấu hình.'', 1;\n        END\n        -- 4. Thêm tài khoản mới vào NGUOIDUNG\n        INSERT INTO\n            dbo.NGUOIDUNG(VaiTroID, HoTen, Email, MatKhau, SoDienThoai, NgayTao, TrangThai)\n        VALUES\n            (\n                @VaiTroID,\n                @HoTen,\n                @Email,\n                @MatKhauHash,\n                @SoDienThoai,\n                dbo.fn_BayGio(),\n                N''Hoạt động''\n            );\n        SET\n            @NewUserId = SCOPE_IDENTITY();\n        -- 5. Tạo bản ghi HOSOKHACHHANG tương ứng\n        INSERT INTO\n            dbo.HOSOKHACHHANG(NguoiDungID, NgaySinh, GioiTinh, DiemTichLuy)\n        VALUES\n            (@NewUserId, @NgaySinh, @GioiTinh, 0);\n        IF @TuMoTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        -- Trả về thông tin tài khoản vừa tạo\n        SELECT\n            nd.NguoiDungID,\n            nd.HoTen,\n            nd.Email,\n            nd.SoDienThoai,\n            vt.MaVaiTro,\n            vt.TenVaiTro,\n            nd.TrangThai,\n            hk.DiemTichLuy\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID\n            LEFT JOIN dbo.HOSOKHACHHANG hk ON nd.NguoiDungID = hk.NguoiDungID\n        WHERE\n            nd.NguoiDungID = @NewUserId;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        DECLARE @LoiSo INT = ERROR_NUMBER();\n        DECLARE @LoiMsg NVARCHAR(2048) = ERROR_MESSAGE();\n        SET\n            @NewUserId = NULL;\n        IF XACT_STATE() = - 1\n        BEGIN\n            -- Transaction đã không thể commit: bắt buộc rollback toàn bộ\n            ROLLBACK TRANSACTION;\n        END\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @TuMoTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION;\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION sp_Auth_RegisterCustomer;\n        END\n        -- Hai yêu cầu đăng ký đồng thời có thể cùng qua bước kiểm tra; UNIQUE là chốt chặn cuối cùng\n        IF @LoiSo IN (2601, 2627)\n            AND @LoiMsg LIKE N''%UQ_NGUOIDUNG_Email%''\n        BEGIN\n            ;\n            THROW 50010, N''Email này đã được sử dụng trong hệ thống.'', 1;\n        END\n        IF @LoiSo IN (2601, 2627)\n            AND @LoiMsg LIKE N''%UQ_NGUOIDUNG_SoDienThoai%''\n        BEGIN\n            ;\n            THROW 50011, N''Số điện thoại này đã được sử dụng trong hệ thống.'', 1;\n        END;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Booking_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/012_booking_limits_and_pricing.sql:253 (dbo.sp_Booking_Create)\nCREATE   PROCEDURE dbo.sp_Booking_Create\n    (\n    @NguoiDungID INT,\n    @SuatChieuID INT,\n    @MaKhuyenMai VARCHAR(50) = NULL,\n    -- Danh sách ID ghế ngăn cách bởi dấu phẩy, ví dụ ''101,102''\n    @DanhSachGheId VARCHAR(MAX),\n    -- Chuỗi JSON danh sách đồ ăn: ''[{\"SanPhamID\":1,\"SoLuong\":2},{\"SanPhamID\":2,\"SoLuong\":1}]''\n    @DanhSachDoAnJson NVARCHAR(MAX) = NULL,\n    -- Số điểm khách muốn dùng để trả tiền vé (1 điểm = 1.000 VNĐ). Máy chủ tự giới hạn theo số dư và giá vé.\n    @DiemSuDung INT = 0,\n    -- 1: chỉ tính và trả về bản xem trước, rồi hoàn tác toàn bộ (không ghi dữ liệu).\n    @ChiXemTruoc BIT = 0,\n    @NewDonDatVeID INT OUTPUT\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''KHACH_HANG'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''DAT_VE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Gọi được cả độc lập lẫn trong transaction của bên gọi: chỉ COMMIT/ROLLBACK khi tự mở transaction,\n    -- ngược lại dùng SAVE TRANSACTION và chỉ rollback phần của mình.\n    DECLARE @TuMoTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        -- Preserve own transaction/savepoint and existing seat-conflict coordination.\n        IF @TuMoTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION;\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION sp_Booking_Create;\n        -- 1. Kiểm tra tài khoản khách hàng hợp lệ. Khóa dòng khách (UPDLOCK, HOLDLOCK, gán vào biến, không phát\n        -- result set) TRƯỚC khóa suất chiếu: các đơn song song của cùng một khách bị xếp hàng, nên giới hạn số đơn\n        -- đang giữ chỗ bên dưới không thể bị vượt bằng race. R2.1 thêm parent trước suất/ghế.\n        DECLARE @KhoaKhach INT;\n        SELECT\n            @KhoaKhach = NguoiDungID\n        FROM\n            dbo.NGUOIDUNG\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động'';\n        IF @KhoaKhach IS NULL\n        BEGIN\n            ;\n            THROW 50020, N''Tài khoản người dùng không tồn tại hoặc đã bị khóa.'', 1;\n        END\n        -- 1b. Tối đa fn_GioiHanDonDangGiu() đơn đang giữ chỗ (chưa thanh toán và chưa quá HanGiuCho) mỗi khách\n        IF(\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.DONDATVE\n            WHERE\n                NguoiDungID = @NguoiDungID\n                AND TrangThai = N''Chờ thanh toán''\n                AND HanGiuCho > dbo.fn_BayGio()\n        ) >= dbo.fn_GioiHanDonDangGiu()\n        BEGIN\n            ;\n            THROW 50028, N''Bạn đang giữ chỗ tối đa số đơn cho phép. Hãy thanh toán hoặc chờ đơn cũ hết hạn.'', 1;\n        END\n        -- R2.1 discovery is an RCSI read, without retained child locks. Never invert R1 room -> show.\n        DECLARE @PhongID INT,\n            @PhimID INT,\n            @RapID INT,\n            @LockedID INT;\n        SELECT\n            @PhongID = s.PhongID,\n            @PhimID = s.PhimID,\n            @RapID = p.RapID\n        FROM\n            dbo.SUATCHIEU s\n            JOIN dbo.PHONGCHIEU p ON p.PhongID = s.PhongID\n        WHERE\n            s.SuatChieuID = @SuatChieuID;\n        IF @PhongID IS NULL\n            THROW 50021, N''Suất chiếu không tồn tại.'', 1;\n        -- Shared parent locks retain current movie dates/status and cinema status until commit.\n        -- Existing parent UPDATE statements need X locks and therefore coordinate without rewrites.\n        SELECT\n            @LockedID = PhimID\n        FROM\n            dbo.PHIM\n        WITH\n            (HOLDLOCK)\n        WHERE\n            PhimID = @PhimID;\n        SET\n            @LockedID = NULL;\n        SELECT\n            @LockedID = RapID\n        FROM\n            dbo.RAPCHIEUPHIM\n        WITH\n            (HOLDLOCK)\n        WHERE\n            RapID = @RapID;\n        SET\n            @LockedID = NULL;\n        SELECT\n            @LockedID = PhongID\n        FROM\n            dbo.PHONGCHIEU\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            PhongID = @PhongID\n            AND RapID = @RapID;\n        IF @LockedID IS NULL\n            THROW 50022, N''Suất chiếu không còn đủ điều kiện đặt vé.'', 1;\n        SET\n            @LockedID = NULL;\n        SELECT\n            @LockedID = SuatChieuID\n        FROM\n            dbo.SUATCHIEU\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            SuatChieuID = @SuatChieuID\n            AND PhongID = @PhongID\n            AND PhimID = @PhimID;\n        -- A concurrent edit may change the discovered movie. Reject and reload instead of locking\n        -- a different movie after the child, which would violate the parent-first protocol.\n        IF @LockedID IS NULL\n            OR NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.vw_LichChieuChiTiet\n            WHERE\n                SuatChieuID = @SuatChieuID\n                AND IsBookable = 1\n        )\n            THROW 50022, N''Suất chiếu không còn đủ điều kiện đặt vé.'', 1;\n        -- 2b. Giải phóng các đơn đã quá hạn giữ ghế của suất chiếu này (đã khóa suất chiếu ở trên)\n        EXEC dbo.sp_Order_ExpirePending @SuatChieuID = @SuatChieuID,\n            @TraVeKetQua = 0;\n        -- 3. Tách danh sách ghế cần đặt vào bảng tạm\n        DECLARE @BangGheCanDat\n        TABLE (GheID INT PRIMARY KEY);\n        INSERT INTO\n            @BangGheCanDat(GheID)\n        SELECT DISTINCT\n            CAST(value AS INT)\n        FROM\n            STRING_SPLIT(@DanhSachGheId, '','')\n        WHERE\n            LTRIM(RTRIM(value)) <> '''';\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                @BangGheCanDat\n        )\n        BEGIN\n            ;\n            THROW 50023, N''Vui lòng chọn ít nhất một ghế để đặt vé.'', 1;\n        END\n        IF(\n            SELECT\n                COUNT(*)\n            FROM\n                @BangGheCanDat\n        ) > dbo.fn_GioiHanGheMoiDon()\n        BEGIN\n            ;\n            THROW 50026, N''Mỗi đơn chỉ được đặt tối đa số ghế cho phép.'', 1;\n        END\n        -- 4. KHÓA CÁC GHẾ VÀ KIỂM TRA TOÀN VẸN:\n        -- Khóa hàng trong GHE để ngăn chặn xung đột giữa các giao dịch đồng thời\n        DECLARE @GheCount INT;\n        SELECT\n            @GheCount = COUNT(*)\n        FROM\n            dbo.GHE g\n        WITH\n            (UPDLOCK, HOLDLOCK)\n            INNER JOIN @BangGheCanDat bg ON g.GheID = bg.GheID\n        WHERE\n            g.PhongID = @PhongID\n            AND g.TrangThai = N''Hoạt động'';\n        IF @GheCount <> (\n            SELECT\n                COUNT(*)\n            FROM\n                @BangGheCanDat\n        )\n        BEGIN\n            ;\n            THROW 50024, N''Một số ghế được chọn không hợp lệ, không thuộc phòng chiếu này hoặc đang bảo trì.'', 1;\n        END\n        -- 5. KIỂM TRA TRÙNG GHẾ: Đảm bảo không có ghế nào trong danh sách đã được đặt trong đơn hợp lệ\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.CHITIETVE cv\n            WITH\n                (UPDLOCK, HOLDLOCK)\n                INNER JOIN dbo.DONDATVE ddv ON cv.DonDatVeID = ddv.DonDatVeID\n                INNER JOIN @BangGheCanDat bg ON cv.GheID = bg.GheID\n            WHERE\n                ddv.SuatChieuID = @SuatChieuID\n                AND cv.TrangThai <> N''Đã hủy''\n                AND dbo.fn_DonDangGiuGhe(ddv.TrangThai, ddv.HanGiuCho, dbo.fn_BayGio()) = 1\n        )\n        BEGIN\n            ;\n            THROW 50025, N''Một hoặc nhiều ghế bạn chọn vừa được khách hàng khác đặt. Vui lòng chọn ghế khác.'', 1;\n        END\n        -- 6. TÍNH SNAPSHOT GIÁ VÉ CHO TỪNG GHẾ (dùng hàm fn_TinhGiaVe)\n        DECLARE @BangChiTietVe\n        TABLE (GheID INT, GiaVe DECIMAL(18, 2), MaVe VARCHAR(100));\n        INSERT INTO\n            @BangChiTietVe(GheID, GiaVe, MaVe)\n        SELECT\n            bg.GheID,\n            dbo.fn_TinhGiaVe(@SuatChieuID, bg.GheID),\n            CONCAT(\n                ''TK-'',\n                FORMAT(dbo.fn_BayGio(), ''yyyyMMddHHmmss''),\n                ''-'',\n                CAST(bg.GheID AS VARCHAR(10)),\n                ''-'',\n                LEFT(REPLACE(CONVERT(VARCHAR(36), NEWID()), ''-'', ''''), 6)\n            )\n        FROM\n            @BangGheCanDat bg;\n        DECLARE @TongTienVe DECIMAL(18, 2) = 0;\n        SELECT\n            @TongTienVe = ISNULL(SUM(GiaVe), 0)\n        FROM\n            @BangChiTietVe;\n        -- 7. TÍNH SNAPSHOT ĐỒ ĂN (NẾU CÓ TRUYỀN JSON)\n        DECLARE @BangChiTietDoAn\n        TABLE (SanPhamID INT, SoLuong INT, DonGia DECIMAL(18, 2));\n        IF @DanhSachDoAnJson IS NOT NULL\n        BEGIN\n            IF ISJSON(@DanhSachDoAnJson) <> 1\n                OR LEFT(LTRIM(@DanhSachDoAnJson), 1) <> ''[''\n                THROW 50402, N''Danh sách sản phẩm phải là mảng JSON hợp lệ.'', 1;\n            IF EXISTS (\n                SELECT\n                    1\n                FROM\n                    OPENJSON(@DanhSachDoAnJson)\n                WHERE\n                    [type] <> 5\n            )\n                THROW 50402, N''Mỗi sản phẩm phải là một object hợp lệ.'', 1;\n            IF EXISTS (\n                SELECT\n                    1\n                FROM\n                    OPENJSON(@DanhSachDoAnJson) item\n                    OUTER APPLY(\n                        SELECT\n                            [value],\n                            [type]\n                        FROM\n                            OPENJSON(item.value)\n                        WHERE\n                            [key] = ''SanPhamID''\n                    ) product\n                    OUTER APPLY(\n                        SELECT\n                            [value],\n                            [type]\n                        FROM\n                            OPENJSON(item.value)\n                        WHERE\n                            [key] = ''SoLuong''\n                    ) quantity\n                WHERE\n                    product.[type] IS NULL\n                    OR product.[type] <> 2\n                    OR quantity.[type] IS NULL\n                    OR quantity.[type] <> 2\n                    OR product.value LIKE ''%[^0-9]%''\n                    OR quantity.value LIKE ''%[^0-9]%''\n                    OR TRY_CONVERT(INT, product.value) IS NULL\n                    OR TRY_CONVERT(INT, product.value) <= 0\n                    OR TRY_CONVERT(BIGINT, quantity.value) IS NULL\n                    OR TRY_CONVERT(BIGINT, quantity.value) <= 0\n                    OR (\n                        SELECT\n                            COUNT(*)\n                        FROM\n                            OPENJSON(item.value)\n                        WHERE\n                            [key] = ''SanPhamID''\n                    ) <> 1\n                    OR (\n                        SELECT\n                            COUNT(*)\n                        FROM\n                            OPENJSON(item.value)\n                        WHERE\n                            [key] = ''SoLuong''\n                    ) <> 1\n            )\n                THROW 50402, N''Mọi mã sản phẩm và số lượng phải là số nguyên hợp lệ.'', 1;\n            DECLARE @ProductInput\n            TABLE (SanPhamID INT NOT NULL, SoLuong BIGINT NOT NULL);\n            INSERT\n                @ProductInput(SanPhamID, SoLuong)\n            SELECT\n                CONVERT(INT, product.value),\n                CONVERT(BIGINT, quantity.value)\n            FROM\n                OPENJSON(@DanhSachDoAnJson) item\n                CROSS APPLY(\n                    SELECT\n                        [value]\n                    FROM\n                        OPENJSON(item.value)\n                    WHERE\n                        [key] = ''SanPhamID''\n                ) product\n                CROSS APPLY(\n                    SELECT\n                        [value]\n                    FROM\n                        OPENJSON(item.value)\n                    WHERE\n                        [key] = ''SoLuong''\n                ) quantity;\n            -- Cộng dồn các dòng trùng sản phẩm TRƯỚC khi kiểm trần (không lách được bằng cách tách dòng).\n            -- SoLuong đọc BIGINT để giá trị ngoài miền INT bị chặn bởi trần thay vì gây lỗi tràn số.\n            IF EXISTS (\n                SELECT\n                    1\n                FROM\n                    @ProductInput j\n                GROUP BY\n                    j.SanPhamID\n                HAVING\n                    SUM(j.SoLuong) > dbo.fn_GioiHanSoLuongSanPham()\n            )\n            BEGIN\n                ;\n                THROW 50027, N''Số lượng mỗi sản phẩm vượt quá mức cho phép.'', 1;\n            END\n            DECLARE @ValidProducts INT;\n            SELECT\n                @ValidProducts = COUNT(*)\n            FROM\n                dbo.SANPHAM sp\n            WITH\n                (UPDLOCK, HOLDLOCK)\n                INNER JOIN (\n                    SELECT DISTINCT\n                        SanPhamID\n                    FROM\n                        @ProductInput\n                ) requested ON requested.SanPhamID = sp.SanPhamID\n            WHERE\n                sp.TrangThai = N''Đang bán'';\n            IF @ValidProducts <> (\n                SELECT\n                    COUNT(DISTINCT SanPhamID)\n                FROM\n                    @ProductInput\n            )\n                THROW 50402, N''Một hoặc nhiều sản phẩm không tồn tại hoặc không đang bán.'', 1;\n            INSERT INTO\n                @BangChiTietDoAn(SanPhamID, SoLuong, DonGia)\n            SELECT\n                j.SanPhamID,\n                CAST(SUM(j.SoLuong) AS INT),\n                sp.Gia\n            FROM\n                @ProductInput j\n                INNER JOIN dbo.SANPHAM sp\n            WITH\n                (UPDLOCK, HOLDLOCK) ON j.SanPhamID = sp.SanPhamID\n            WHERE\n                j.SoLuong > 0\n                AND sp.TrangThai = N''Đang bán''\n            GROUP BY\n                j.SanPhamID,\n                sp.Gia;\n        END\n        DECLARE @TongTienDoAn DECIMAL(18, 2) = 0;\n        SELECT\n            @TongTienDoAn = ISNULL(SUM(SoLuong * DonGia), 0)\n        FROM\n            @BangChiTietDoAn;\n        -- Re-check DB time immediately before the first booking write (promotion usage/order).\n        -- Resource/seat locks above remain held; a parent cannot change between check and commit.\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.vw_LichChieuChiTiet\n            WHERE\n                SuatChieuID = @SuatChieuID\n                AND IsBookable = 1\n        )\n            THROW 50022, N''Suất chiếu không còn đủ điều kiện đặt vé.'', 1;\n        -- 8. TÍNH KHUYẾN MÃI (NẾU CÓ)\n        DECLARE @KhuyenMaiID INT = NULL;\n        DECLARE @TienGiamGia DECIMAL(18, 2) = 0;\n        DECLARE @TongTruocGiam DECIMAL(18, 2) = @TongTienVe + @TongTienDoAn;\n        IF @MaKhuyenMai IS NOT NULL\n            AND LTRIM(RTRIM(@MaKhuyenMai)) <> ''''\n        BEGIN\n            DECLARE @LockedPromotionUsage INT;\n            -- R2.2: promotion follows booking resources/products in the lock hierarchy.\n            -- Lock BEFORE validation; the current state and final quota stay protected\n            -- until the owning transaction commits/rolls back (also for caller transactions).\n            -- Read a non-covered column as well as the ID: the unique code index\n            -- alone does not protect status/quota updates on the clustered row.\n            SELECT\n                @KhuyenMaiID = KhuyenMaiID,\n                @LockedPromotionUsage = SoLuongDaDung\n            FROM\n                dbo.KHUYENMAI\n            WITH\n                (\n                    UPDLOCK,\n                    HOLDLOCK,\n                    INDEX(UQ_KHUYENMAI_MaCode)\n                )\n            WHERE\n                MaCode = @MaKhuyenMai;\n            IF @KhuyenMaiID IS NULL\n                OR @LockedPromotionUsage < 0\n                THROW 50029, N''Khuyến mãi yêu cầu không còn khả dụng. Vui lòng kiểm tra lại đơn.'', 1;\n            DECLARE @LoaiGiamGia NVARCHAR(20);\n            DECLARE @GiaTriGiam DECIMAL(18, 2);\n            DECLARE @IsValid BIT;\n            DECLARE @Msg NVARCHAR(255);\n            EXEC dbo.sp_Promotion_Validate @NguoiDungID = @NguoiDungID,\n                @MaCode = @MaKhuyenMai,\n                @TongTienDon = @TongTruocGiam,\n                @KhuyenMaiID = @KhuyenMaiID OUTPUT,\n                @LoaiGiamGia = @LoaiGiamGia OUTPUT,\n                @GiaTriGiam = @GiaTriGiam OUTPUT,\n                @TienGiam = @TienGiamGia OUTPUT,\n                @IsValid = @IsValid OUTPUT,\n                @Message = @Msg OUTPUT;\n            IF ISNULL(@IsValid, 0) <> 1\n                OR @KhuyenMaiID IS NULL\n                THROW 50029, N''Khuyến mãi yêu cầu không còn khả dụng. Vui lòng kiểm tra lại đơn.'', 1;\n            -- Chặn cứng lần nữa: giảm tối đa 99% tổng tạm tính, tổng đơn luôn > 0\n            DECLARE @TranGiam DECIMAL(18, 2) = ROUND(@TongTruocGiam * dbo.fn_GioiHanGiamGiaPhanTram() / 100.0, 2, 1);\n            IF @TienGiamGia > @TranGiam\n                SET\n                    @TienGiamGia = @TranGiam;\n            -- Validation and consumption use the same protected row/transaction.\n            UPDATE dbo.KHUYENMAI\n            SET\n                SoLuongDaDung = SoLuongDaDung + 1\n            WHERE\n                KhuyenMaiID = @KhuyenMaiID\n                AND SoLuongDaDung < SoLuong;\n            IF @@ROWCOUNT <> 1\n                THROW 50029, N''Khuyến mãi yêu cầu không còn khả dụng. Vui lòng kiểm tra lại đơn.'', 1;\n        END\n        -- Promotion acquisition can wait. Keep R2.1''s final DB-time check current\n        -- before order writes; rejection also rolls back any promotion consumption.\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.vw_LichChieuChiTiet\n            WHERE\n                SuatChieuID = @SuatChieuID\n                AND IsBookable = 1\n        )\n            THROW 50022, N''Suất chiếu không còn đủ điều kiện đặt vé.'', 1;\n        -- 8b. THANH TOÁN BẰNG ĐIỂM. Máy chủ quyết định mọi con số; điểm chỉ giảm phần TIỀN VÉ còn phải trả\n        -- sau khuyến mãi (không giảm đồ ăn). 1 điểm = 1.000 VNĐ, tỷ lệ nghịch đảo của điểm bồi thường\n        -- (dbo.fn_TinhBoiThuongVe: 1.000 VNĐ tiền vé = 1 điểm). Không bao giờ quy đổi điểm ra tiền mặt.\n        DECLARE @VndMoiDiem DECIMAL(18, 2) = 1000;\n        DECLARE @DiemYeuCau INT = ISNULL(@DiemSuDung, 0);\n        DECLARE @SoDuDiem INT = 0;\n        DECLARE @TienVeSauKhuyenMai DECIMAL(18, 2) = @TongTienVe;\n        IF @TongTruocGiam > 0\n            SET\n                @TienVeSauKhuyenMai = @TongTienVe - CEILING(@TienGiamGia * @TongTienVe * 100.0 / @TongTruocGiam) / 100.0;\n        IF @TienVeSauKhuyenMai < 0\n            SET\n                @TienVeSauKhuyenMai = 0;\n        DECLARE @DiemToiDaTheoVe INT = CAST(FLOOR(@TienVeSauKhuyenMai / @VndMoiDiem) AS INT);\n        SELECT\n            @SoDuDiem = DiemTichLuy\n        FROM\n            dbo.HOSOKHACHHANG\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            NguoiDungID = @NguoiDungID;\n        SET\n            @SoDuDiem = ISNULL(@SoDuDiem, 0);\n        DECLARE @DiemToiDa INT = CASE\n            WHEN @SoDuDiem < @DiemToiDaTheoVe THEN @SoDuDiem\n            ELSE @DiemToiDaTheoVe\n        END;\n        IF @DiemYeuCau < 0\n            THROW 50410, N''Số điểm sử dụng không hợp lệ.'', 1;\n        IF @DiemYeuCau > @SoDuDiem\n            THROW 50411, N''Số điểm sử dụng vượt quá số dư điểm hiện có.'', 1;\n        IF @DiemYeuCau > @DiemToiDaTheoVe\n            THROW 50412, N''Số điểm sử dụng vượt quá giá trị tiền vé còn phải trả.'', 1;\n        -- TienGiamGia is the sole discount snapshot: promotion plus the value of points used.\n        SET\n            @TienGiamGia = @TienGiamGia + @DiemYeuCau * @VndMoiDiem;\n        IF @ChiXemTruoc = 1\n        BEGIN\n            -- Xem trước: cùng đường tính với đặt vé thật, sau đó hoàn tác (không giữ ghế, không dùng điểm/khuyến mãi).\n            SELECT\n                @SuatChieuID AS SuatChieuID,\n                @TongTienVe AS TongTienVe,\n                @TongTienDoAn AS TongTienDoAn,\n                @TienGiamGia AS TienGiamGia,\n                @DiemYeuCau AS DiemSuDung,\n                CASE\n                    WHEN @TongTienVe + @TongTienDoAn - @TienGiamGia < 0 THEN 0\n                    ELSE @TongTienVe + @TongTienDoAn - @TienGiamGia\n                END AS TongThanhToan,\n                @SoDuDiem AS SoDuDiem,\n                @DiemToiDa AS DiemToiDa,\n                (@SoDuDiem - @DiemYeuCau) AS SoDuDiemSauKhiDat;\n            IF @TuMoTran = 1\n                ROLLBACK TRANSACTION;\n            ELSE\n                ROLLBACK TRANSACTION sp_Booking_Create;\n            RETURN;\n        END\n        IF @DiemYeuCau > 0\n        BEGIN\n            UPDATE dbo.HOSOKHACHHANG\n            SET\n                DiemTichLuy = DiemTichLuy - @DiemYeuCau\n            WHERE\n                NguoiDungID = @NguoiDungID\n                AND DiemTichLuy >= @DiemYeuCau;\n            IF @@ROWCOUNT <> 1\n                THROW 50411, N''Số điểm sử dụng vượt quá số dư điểm hiện có.'', 1;\n        END\n        -- 9. TẠO BẢN GHI DONDATVE\n        INSERT INTO\n            dbo.DONDATVE(\n                NguoiDungID,\n                SuatChieuID,\n                KhuyenMaiID,\n                NgayDat,\n                TongTienVe,\n                TongTienDoAn,\n                TienGiamGia,\n                DiemSuDung,\n                TrangThai,\n                HanGiuCho\n            )\n        VALUES\n            (\n                @NguoiDungID,\n                @SuatChieuID,\n                @KhuyenMaiID,\n                dbo.fn_BayGio(),\n                @TongTienVe,\n                @TongTienDoAn,\n                @TienGiamGia,\n                @DiemYeuCau,\n                N''Chờ thanh toán'',\n                DATEADD(MINUTE, dbo.fn_ThoiGianGiuChoPhut(), dbo.fn_BayGio())\n            );\n        SET\n            @NewDonDatVeID = SCOPE_IDENTITY();\n        -- 10. TẠO CÁC BẢN GHI CHITIETVE\n        INSERT INTO\n            dbo.CHITIETVE(DonDatVeID, GheID, GiaVe, MaVe, TrangThai)\n        SELECT\n            @NewDonDatVeID,\n            GheID,\n            GiaVe,\n            MaVe,\n            N''Đã đặt''\n        FROM\n            @BangChiTietVe;\n        -- 11. TẠO CÁC BẢN GHI CHITIETDOAN (NẾU CÓ)\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                @BangChiTietDoAn\n        )\n        BEGIN\n            INSERT INTO\n                dbo.CHITIETDOAN(DonDatVeID, SanPhamID, SoLuong, DonGia)\n            SELECT\n                @NewDonDatVeID,\n                SanPhamID,\n                SoLuong,\n                DonGia\n            FROM\n                @BangChiTietDoAn;\n        END\n        IF @TuMoTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        -- Trả về kết quả chốt của đơn đặt vé\n        SELECT\n            ddv.DonDatVeID,\n            ddv.NguoiDungID,\n            ddv.SuatChieuID,\n            ddv.NgayDat,\n            ddv.TongTienVe,\n            ddv.TongTienDoAn,\n            ddv.TienGiamGia,\n            ddv.DiemSuDung,\n            CASE\n                WHEN ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia < 0 THEN 0\n                ELSE ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia\n            END AS TongThanhToan,\n            ddv.TrangThai,\n            ddv.HanGiuCho,\n            (\n                SELECT\n                    COUNT(*)\n                FROM\n                    dbo.CHITIETVE\n                WHERE\n                    DonDatVeID = ddv.DonDatVeID\n            ) AS SoLuongVe\n        FROM\n            dbo.DONDATVE ddv\n        WHERE\n            ddv.DonDatVeID = @NewDonDatVeID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @TuMoTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION;\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION sp_Booking_Create;\n        END;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Cinema_GetImages","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Cinema_GetImages\n    @RapID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT\n        i.HinhAnhRapID,\n        i.RapID,\n        i.URL,\n        i.MoTa,\n        i.LaAnhDaiDien,\n        i.ThuTuHienThi,\n        i.TrangThai,\n        i.NgayTao\n    FROM\n        dbo.HINHANH_RAPCHIEUPHIM i\n        INNER JOIN dbo.RAPCHIEUPHIM r ON r.RapID = i.RapID\n    WHERE\n        i.RapID = @RapID\n        AND r.TrangThai = N''Hoạt động''\n        AND i.TrangThai = N''Hoạt động''\n    ORDER BY\n        i.ThuTuHienThi,\n        i.HinhAnhRapID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Cinema_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Cinema_List\n    @ThanhPho NVARCHAR(100) = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT\n        r.RapID,\n        r.TenRap,\n        r.DiaChi,\n        r.ThanhPho,\n        r.SoDienThoai,\n        r.MoTa,\n        r.NgayHoatDong,\n        r.TrangThai,\n        cover.URL AS AnhDaiDienURL\n    FROM\n        dbo.RAPCHIEUPHIM r\n        OUTER APPLY(\n            SELECT\n                TOP(1) i.URL\n            FROM\n                dbo.HINHANH_RAPCHIEUPHIM i\n            WHERE\n                i.RapID = r.RapID\n                AND i.LaAnhDaiDien = 1\n                AND i.TrangThai = N''Hoạt động''\n            ORDER BY\n                i.HinhAnhRapID\n        ) cover\n    WHERE\n        (\n            @ThanhPho IS NULL\n            OR r.ThanhPho = @ThanhPho\n        )\n        AND r.TrangThai = N''Hoạt động''\n    ORDER BY\n        r.ThanhPho,\n        r.TenRap;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Clock_GetNow","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Clock_GetNow\n    @PhimID INT = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT\n        dbo.fn_BayGio() AS BayGio,\n        (\n            SELECT\n                ThoiLuong\n            FROM\n                dbo.PHIM\n            WHERE\n                PhimID = @PhimID\n        ) AS ThoiLuong;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Complaint_Assign_Admin","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Complaint_Assign_Admin\n    (\n    @AdminID INT,\n    @KhieuNaiID INT,\n    @NhanVienMoiID INT = NULL,\n    @LyDo NVARCHAR(500) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n\n    -- Kiểm tra tài khoản Admin\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG\n        WHERE NguoiDungID = @AdminID AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n\n    -- Kiểm tra vai trò ADMIN\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE nd.NguoiDungID = @AdminID AND vt.MaVaiTro = ''ADMIN''\n    )\n        THROW 50301, N''Chỉ Quản trị viên mới có quyền phân công nhân viên.'', 1;\n\n    -- Kiểm tra quyền KHIEUNAI_PHANCONG\n    IF dbo.fn_KiemTraQuyenNguoiDung(@AdminID, ''KHIEUNAI_PHANCONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    -- Nếu phân công cho nhân viên mới, kiểm tra nhân viên đó có hợp lệ không\n    IF @NhanVienMoiID IS NOT NULL\n    BEGIN\n        IF NOT EXISTS (\n            SELECT 1 FROM dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n            WHERE nd.NguoiDungID = @NhanVienMoiID\n              AND nd.TrangThai = N''Hoạt động''\n              AND vt.MaVaiTro = ''CSKH''\n        )\n            THROW 50603, N''Nhân viên được phân công không hợp lệ hoặc đã bị khóa.'', 1;\n    END;\n\n    BEGIN TRY\n        BEGIN TRANSACTION;\n\n        DECLARE @NhanVienCuID INT, @CurrentTrangThai NVARCHAR(50);\n        SELECT\n            @NhanVienCuID = NhanVienPhuTrachID,\n            @CurrentTrangThai = TrangThai\n        FROM dbo.KHIEUNAI WITH (UPDLOCK, HOLDLOCK)\n        WHERE KhieuNaiID = @KhieuNaiID;\n\n        IF @CurrentTrangThai IS NULL\n            THROW 50061, N''Khiếu nại không tồn tại.'', 1;\n\n        DECLARE @TrangThaiMoi NVARCHAR(50) = @CurrentTrangThai;\n        IF @NhanVienMoiID IS NOT NULL AND @CurrentTrangThai = N''Mới''\n            SET @TrangThaiMoi = N''Đang xử lý'';\n\n        -- Cập nhật người phụ trách\n        UPDATE dbo.KHIEUNAI\n        SET\n            NhanVienPhuTrachID = @NhanVienMoiID,\n            TrangThai = @TrangThaiMoi\n        WHERE KhieuNaiID = @KhieuNaiID;\n\n        -- Ghi lịch sử phân công\n        INSERT INTO dbo.LICHSU_PHANCONG_KHIEUNAI (\n            KhieuNaiID,\n            NhanVienCuID,\n            NhanVienMoiID,\n            NguoiThucHienID,\n            ThoiGian,\n            LyDo\n        )\n        VALUES (\n            @KhieuNaiID,\n            @NhanVienCuID,\n            @NhanVienMoiID,\n            @AdminID,\n            dbo.fn_BayGio(),\n            ISNULL(@LyDo, CASE\n                WHEN @NhanVienMoiID IS NULL THEN N''Admin thu hồi phân công nhân viên''\n                WHEN @NhanVienCuID IS NULL THEN N''Admin phân công nhân viên phụ trách''\n                ELSE N''Admin chuyển giao nhân viên phụ trách''\n            END)\n        );\n\n        -- Ghi nhật ký xử lý\n        INSERT INTO dbo.XULY_KHIEUNAI (\n            KhieuNaiID,\n            NguoiXuLyID,\n            NoiDungXuLy,\n            NgayXuLy,\n            TrangThaiSauXuLy\n        )\n        VALUES (\n            @KhieuNaiID,\n            @AdminID,\n            CASE\n                WHEN @NhanVienMoiID IS NULL THEN N''Admin thu hồi phân công nhân viên.''\n                ELSE N''Admin phân công/chuyển giao nhân viên phụ trách khiếu nại.''\n            END,\n            dbo.fn_BayGio(),\n            @TrangThaiMoi\n        );\n\n        COMMIT TRANSACTION;\n\n        SELECT\n            kn.KhieuNaiID,\n            kn.NguoiDungID,\n            kn.DonDatVeID,\n            kn.LoaiKhieuNai,\n            kn.TieuDe,\n            kn.NoiDung,\n            kn.MucDoUuTien,\n            kn.NgayTao,\n            kn.TrangThai,\n            kn.NhanVienPhuTrachID,\n            nd.HoTen AS TenNhanVienPhuTrach\n        FROM dbo.KHIEUNAI kn\n        LEFT JOIN dbo.NGUOIDUNG nd ON nd.NguoiDungID = kn.NhanVienPhuTrachID\n        WHERE kn.KhieuNaiID = @KhieuNaiID;\n    END TRY\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0\n            ROLLBACK TRANSACTION;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Complaint_Assign_Self","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Complaint_Assign_Self\n    (\n    @NguoiDungID INT,\n    @KhieuNaiID INT\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n\n    -- Kiểm tra tài khoản\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG\n        WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n\n    -- Kiểm tra vai trò CSKH\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro = ''CSKH''\n    )\n        THROW 50301, N''Chỉ nhân viên Chăm sóc khách hàng mới được tự tiếp nhận khiếu nại.'', 1;\n\n    -- Kiểm tra quyền KHIEUNAI_TIEPNHAN\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''KHIEUNAI_TIEPNHAN'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    BEGIN TRY\n        BEGIN TRANSACTION;\n\n        -- Khóa bản ghi khiếu nại để chống tranh chấp đồng thời\n        DECLARE @CurrentPhuTrach INT, @CurrentTrangThai NVARCHAR(50);\n        SELECT\n            @CurrentPhuTrach = NhanVienPhuTrachID,\n            @CurrentTrangThai = TrangThai\n        FROM dbo.KHIEUNAI WITH (UPDLOCK, HOLDLOCK)\n        WHERE KhieuNaiID = @KhieuNaiID;\n\n        IF @CurrentTrangThai IS NULL\n            THROW 50061, N''Khiếu nại không tồn tại.'', 1;\n\n        IF @CurrentPhuTrach IS NOT NULL\n            THROW 50601, N''Khiếu nại này đã có nhân viên khác tiếp nhận.'', 1;\n\n        IF @CurrentTrangThai IN (N''Đã đóng'', N''Từ chối'', N''Đã giải quyết'')\n            THROW 50602, N''Không thể tiếp nhận khiếu nại đã hoàn tất.'', 1;\n\n        DECLARE @TrangThaiMoi NVARCHAR(50) = CASE\n            WHEN @CurrentTrangThai = N''Mới'' THEN N''Đang xử lý''\n            ELSE @CurrentTrangThai\n        END;\n\n        -- Cập nhật người phụ trách và trạng thái\n        UPDATE dbo.KHIEUNAI\n        SET\n            NhanVienPhuTrachID = @NguoiDungID,\n            TrangThai = @TrangThaiMoi\n        WHERE KhieuNaiID = @KhieuNaiID;\n\n        -- Ghi lịch sử phân công\n        INSERT INTO dbo.LICHSU_PHANCONG_KHIEUNAI (\n            KhieuNaiID,\n            NhanVienCuID,\n            NhanVienMoiID,\n            NguoiThucHienID,\n            ThoiGian,\n            LyDo\n        )\n        VALUES (\n            @KhieuNaiID,\n            NULL,\n            @NguoiDungID,\n            @NguoiDungID,\n            dbo.fn_BayGio(),\n            N''Nhân viên CSKH tự tiếp nhận xử lý''\n        );\n\n        -- Ghi nhật ký xử lý\n        INSERT INTO dbo.XULY_KHIEUNAI (\n            KhieuNaiID,\n            NguoiXuLyID,\n            NoiDungXuLy,\n            NgayXuLy,\n            TrangThaiSauXuLy\n        )\n        VALUES (\n            @KhieuNaiID,\n            @NguoiDungID,\n            N''Nhân viên CSKH tiếp nhận xử lý khiếu nại.'',\n            dbo.fn_BayGio(),\n            @TrangThaiMoi\n        );\n\n        COMMIT TRANSACTION;\n\n        -- Trả về thông tin khiếu nại sau cập nhật\n        SELECT\n            kn.KhieuNaiID,\n            kn.NguoiDungID,\n            kn.DonDatVeID,\n            kn.LoaiKhieuNai,\n            kn.TieuDe,\n            kn.NoiDung,\n            kn.MucDoUuTien,\n            kn.NgayTao,\n            kn.TrangThai,\n            kn.NhanVienPhuTrachID,\n            nd.HoTen AS TenNhanVienPhuTrach\n        FROM dbo.KHIEUNAI kn\n        LEFT JOIN dbo.NGUOIDUNG nd ON nd.NguoiDungID = kn.NhanVienPhuTrachID\n        WHERE kn.KhieuNaiID = @KhieuNaiID;\n    END TRY\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0\n            ROLLBACK TRANSACTION;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Complaint_Assignment_History","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Complaint_Assignment_History\n    (\n    @NguoiDungID INT,\n    @KhieuNaiID INT\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n\n    -- Kiểm tra tài khoản\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG\n        WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n\n    -- Kiểm tra vai trò CSKH hoặc ADMIN\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''CSKH'', ''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n\n    -- Kiểm tra quyền QL_KHIEUNAI\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF NOT EXISTS (SELECT 1 FROM dbo.KHIEUNAI WHERE KhieuNaiID = @KhieuNaiID)\n        THROW 50061, N''Khiếu nại không tồn tại.'', 1;\n\n    SELECT\n        ls.LichSuID,\n        ls.KhieuNaiID,\n        ls.NhanVienCuID,\n        nd_cu.HoTen AS TenNhanVienCu,\n        ls.NhanVienMoiID,\n        nd_moi.HoTen AS TenNhanVienMoi,\n        ls.NguoiThucHienID,\n        nd_th.HoTen AS TenNguoiThucHien,\n        vt_th.TenVaiTro AS VaiTroNguoiThucHien,\n        ls.ThoiGian,\n        ls.LyDo\n    FROM dbo.LICHSU_PHANCONG_KHIEUNAI ls\n    LEFT JOIN dbo.NGUOIDUNG nd_cu ON nd_cu.NguoiDungID = ls.NhanVienCuID\n    LEFT JOIN dbo.NGUOIDUNG nd_moi ON nd_moi.NguoiDungID = ls.NhanVienMoiID\n    INNER JOIN dbo.NGUOIDUNG nd_th ON nd_th.NguoiDungID = ls.NguoiThucHienID\n    INNER JOIN dbo.VAITRO vt_th ON vt_th.VaiTroID = nd_th.VaiTroID\n    WHERE ls.KhieuNaiID = @KhieuNaiID\n    ORDER BY ls.ThoiGian ASC, ls.LichSuID ASC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Complaint_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/003_complaint_order_ownership.sql:3 (dbo.sp_Complaint_Create)\nCREATE   PROCEDURE dbo.sp_Complaint_Create\n    (\n    @NguoiDungID INT,\n    @DonDatVeID INT = NULL,\n    @LoaiKhieuNai NVARCHAR(100),\n    @TieuDe NVARCHAR(200),\n    @NoiDung NVARCHAR(MAX),\n    @MucDoUuTien NVARCHAR(50) = N''Trung bình''\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''KHACH_HANG'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''GUI_KHIEU_NAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF @DonDatVeID IS NOT NULL\n        AND NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.DONDATVE\n        WHERE\n            DonDatVeID = @DonDatVeID\n            AND NguoiDungID = @NguoiDungID\n    )\n    BEGIN\n        -- Same non-disclosing error for a missing or foreign order reference.\n        ;\n        THROW 50041, N''Đơn đặt vé tham chiếu không hợp lệ.'', 1;\n    END\n    INSERT INTO\n        dbo.KHIEUNAI(\n            NguoiDungID,\n            DonDatVeID,\n            LoaiKhieuNai,\n            TieuDe,\n            NoiDung,\n            MucDoUuTien,\n            NgayTao,\n            TrangThai\n        )\n    VALUES\n        (\n            @NguoiDungID,\n            @DonDatVeID,\n            @LoaiKhieuNai,\n            @TieuDe,\n            @NoiDung,\n            @MucDoUuTien,\n            dbo.fn_BayGio(),\n            N''Mới''\n        );\n    SELECT\n        KhieuNaiID,\n        NguoiDungID,\n        DonDatVeID,\n        LoaiKhieuNai,\n        TieuDe,\n        NoiDung,\n        MucDoUuTien,\n        NgayTao,\n        TrangThai\n    FROM\n        dbo.KHIEUNAI\n    WHERE\n        KhieuNaiID = SCOPE_IDENTITY();\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Complaint_Chat_AddInternalNote","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Complaint_Chat_AddInternalNote\n    (\n    @NguoiDungID INT,\n    @KhieuNaiID INT,\n    @NoiDung NVARCHAR(MAX)\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n\n    EXEC dbo.sp_Complaint_Chat_Send\n        @NguoiDungID = @NguoiDungID,\n        @KhieuNaiID = @KhieuNaiID,\n        @NoiDung = @NoiDung,\n        @LoaiTinNhan = N''Nội bộ'';\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Complaint_Chat_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Complaint_Chat_List\n    (\n    @NguoiDungID INT,\n    @KhieuNaiID INT,\n    @Page INT = 1,\n    @PageSize INT = 50\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n\n    -- Kiểm tra tài khoản người gọi\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG\n        WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n\n    -- Lấy thông tin vai trò của người gọi\n    DECLARE @MaVaiTro VARCHAR(50);\n    SELECT @MaVaiTro = vt.MaVaiTro\n    FROM dbo.NGUOIDUNG nd\n    INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n    WHERE nd.NguoiDungID = @NguoiDungID;\n\n    -- Kiểm tra quyền xem hội thoại\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''KHIEUNAI_CHAT_XEM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    -- Kiểm tra khiếu nại tồn tại\n    DECLARE @NguoiDungKhieuNaiID INT, @NhanVienPhuTrachID INT;\n    SELECT\n        @NguoiDungKhieuNaiID = kn.NguoiDungID,\n        @NhanVienPhuTrachID = kn.NhanVienPhuTrachID\n    FROM dbo.KHIEUNAI kn\n    WHERE kn.KhieuNaiID = @KhieuNaiID;\n\n    IF @NguoiDungKhieuNaiID IS NULL\n    BEGIN\n        IF @MaVaiTro = ''KHACH_HANG''\n            THROW 50042, N''Khiếu nại không tồn tại hoặc bạn không có quyền xem.'', 1;\n        ELSE\n            THROW 50061, N''Khiếu nại không tồn tại.'', 1;\n    END;\n\n    -- Kiểm tra quyền truy cập theo vai trò\n    IF @MaVaiTro = ''KHACH_HANG''\n    BEGIN\n        -- Khách hàng chỉ được xem khiếu nại của chính mình\n        IF @NguoiDungKhieuNaiID <> @NguoiDungID\n            THROW 50042, N''Khiếu nại không tồn tại hoặc bạn không có quyền xem.'', 1;\n    END\n    ELSE IF @MaVaiTro NOT IN (''CSKH'', ''ADMIN'')\n    BEGIN\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    END;\n\n    -- Xác định có quyền xem tin nhắn nội bộ hay không\n    DECLARE @XemNoiBo BIT = 0;\n    IF @MaVaiTro IN (''CSKH'', ''ADMIN'') AND dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''KHIEUNAI_NOIBO_XEM'') = 1\n    BEGIN\n        SET @XemNoiBo = 1;\n    END;\n\n    IF @Page < 1 SET @Page = 1;\n    IF @PageSize < 1 OR @PageSize > 200 SET @PageSize = 50;\n    DECLARE @Offset INT = (@Page - 1) * @PageSize;\n\n    -- Đếm tổng số tin nhắn được phép xem\n    DECLARE @TotalCount INT;\n    SELECT @TotalCount = COUNT(*)\n    FROM dbo.TINNHAN_KHIEUNAI tn\n    WHERE tn.KhieuNaiID = @KhieuNaiID\n      AND (@XemNoiBo = 1 OR tn.LoaiTinNhan = N''Công khai'');\n\n    -- Trả về danh sách tin nhắn có phân trang\n    SELECT\n        tn.TinNhanID,\n        tn.KhieuNaiID,\n        tn.NguoiGuiID,\n        nd.HoTen AS HoTenNguoiGui,\n        vt.MaVaiTro AS MaVaiTroNguoiGui,\n        vt.TenVaiTro AS TenVaiTroNguoiGui,\n        tn.NoiDung,\n        tn.LoaiTinNhan,\n        tn.ThoiGianGui,\n        CASE WHEN tn.NguoiGuiID = @NguoiDungID THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END AS LaNguoiGui,\n        @TotalCount AS TotalCount\n    FROM dbo.TINNHAN_KHIEUNAI tn\n    INNER JOIN dbo.NGUOIDUNG nd ON nd.NguoiDungID = tn.NguoiGuiID\n    INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n    WHERE tn.KhieuNaiID = @KhieuNaiID\n      AND (@XemNoiBo = 1 OR tn.LoaiTinNhan = N''Công khai'')\n    ORDER BY tn.ThoiGianGui ASC, tn.TinNhanID ASC\n    OFFSET @Offset ROWS\n    FETCH NEXT @PageSize ROWS ONLY;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Complaint_Chat_Send","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Complaint_Chat_Send\n    (\n    @NguoiDungID INT,\n    @KhieuNaiID INT,\n    @NoiDung NVARCHAR(MAX),\n    @LoaiTinNhan NVARCHAR(50) = N''Công khai''\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n\n    -- Kiểm tra tài khoản người gọi\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG\n        WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n\n    -- Kiểm tra tính hợp lệ của nội dung tin nhắn\n    IF @NoiDung IS NULL OR LEN(LTRIM(RTRIM(@NoiDung))) = 0\n        THROW 50401, N''Nội dung tin nhắn không được để trống.'', 1;\n\n    IF LEN(@NoiDung) > 4000\n        THROW 50401, N''Nội dung tin nhắn không được vượt quá 4000 ký tự.'', 1;\n\n    -- Kiểm tra loại tin nhắn\n    IF @LoaiTinNhan NOT IN (N''Công khai'', N''Nội bộ'')\n        THROW 50402, N''Loại tin nhắn không hợp lệ.'', 1;\n\n    -- Lấy vai trò của người gọi\n    DECLARE @MaVaiTro VARCHAR(50);\n    SELECT @MaVaiTro = vt.MaVaiTro\n    FROM dbo.NGUOIDUNG nd\n    INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n    WHERE nd.NguoiDungID = @NguoiDungID;\n\n    -- Kiểm tra khiếu nại tồn tại\n    DECLARE @NguoiDungKhieuNaiID INT, @NhanVienPhuTrachID INT, @TrangThaiKhieuNai NVARCHAR(50);\n    SELECT\n        @NguoiDungKhieuNaiID = kn.NguoiDungID,\n        @NhanVienPhuTrachID = kn.NhanVienPhuTrachID,\n        @TrangThaiKhieuNai = kn.TrangThai\n    FROM dbo.KHIEUNAI kn\n    WHERE kn.KhieuNaiID = @KhieuNaiID;\n\n    IF @NguoiDungKhieuNaiID IS NULL\n    BEGIN\n        IF @MaVaiTro = ''KHACH_HANG''\n            THROW 50042, N''Khiếu nại không tồn tại hoặc bạn không có quyền xem.'', 1;\n        ELSE\n            THROW 50061, N''Khiếu nại không tồn tại.'', 1;\n    END;\n\n    -- Kiểm tra quyền nghiệp vụ và phạm vi phân công theo vai trò\n    IF @MaVaiTro = ''KHACH_HANG''\n    BEGIN\n        -- Khách hàng chỉ được gửi tin trong khiếu nại của chính mình\n        IF @NguoiDungKhieuNaiID <> @NguoiDungID\n            THROW 50042, N''Khiếu nại không tồn tại hoặc bạn không có quyền xem.'', 1;\n\n        -- Khách hàng không được phép gửi tin nhắn nội bộ\n        IF @LoaiTinNhan = N''Nội bộ''\n            THROW 50304, N''Khách hàng không được phép gửi ghi chú nội bộ.'', 1;\n\n        -- Kiểm tra quyền gửi tin nhắn\n        IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''KHIEUNAI_CHAT_GUI'') = 0\n            THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    END\n    ELSE IF @MaVaiTro = ''CSKH''\n    BEGIN\n        -- CSKH chỉ được phản hồi trong khiếu nại được phân công phụ trách\n        IF @NhanVienPhuTrachID IS NULL OR @NhanVienPhuTrachID <> @NguoiDungID\n            THROW 50305, N''Bạn chỉ có thể gửi phản hồi đối với khiếu nại được phân công cho mình.'', 1;\n\n        IF @LoaiTinNhan = N''Công khai''\n        BEGIN\n            IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''KHIEUNAI_CHAT_GUI'') = 0\n                THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n        END\n        ELSE IF @LoaiTinNhan = N''Nội bộ''\n        BEGIN\n            IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''KHIEUNAI_NOIBO_GHI'') = 0\n                THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n        END;\n    END\n    ELSE IF @MaVaiTro = ''ADMIN''\n    BEGIN\n        IF @LoaiTinNhan = N''Công khai''\n        BEGIN\n            IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''KHIEUNAI_CHAT_GUI'') = 0\n                THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n        END\n        ELSE IF @LoaiTinNhan = N''Nội bộ''\n        BEGIN\n            IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''KHIEUNAI_NOIBO_GHI'') = 0\n                THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n        END;\n    END\n    ELSE\n    BEGIN\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    END;\n\n    -- Thêm tin nhắn vào bảng\n    INSERT INTO dbo.TINNHAN_KHIEUNAI (\n        KhieuNaiID,\n        NguoiGuiID,\n        NoiDung,\n        LoaiTinNhan,\n        ThoiGianGui\n    )\n    VALUES (\n        @KhieuNaiID,\n        @NguoiDungID,\n        @NoiDung,\n        @LoaiTinNhan,\n        dbo.fn_BayGio()\n    );\n\n    DECLARE @NewID INT = SCOPE_IDENTITY();\n\n    -- Trả về tin nhắn vừa tạo kèm thông tin người gửi\n    SELECT\n        tn.TinNhanID,\n        tn.KhieuNaiID,\n        tn.NguoiGuiID,\n        nd.HoTen AS HoTenNguoiGui,\n        vt.MaVaiTro AS MaVaiTroNguoiGui,\n        vt.TenVaiTro AS TenVaiTroNguoiGui,\n        tn.NoiDung,\n        tn.LoaiTinNhan,\n        tn.ThoiGianGui,\n        CAST(1 AS BIT) AS LaNguoiGui\n    FROM dbo.TINNHAN_KHIEUNAI tn\n    INNER JOIN dbo.NGUOIDUNG nd ON nd.NguoiDungID = tn.NguoiGuiID\n    INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n    WHERE tn.TinNhanID = @NewID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Complaint_GetByCustomer","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Complaint_GetByCustomer\n    (@NguoiDungID INT, @KhieuNaiID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''KHACH_HANG'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.KHIEUNAI\n        WHERE\n            KhieuNaiID = @KhieuNaiID\n            AND NguoiDungID = @NguoiDungID\n    )\n    BEGIN\n        ;\n        THROW 50042, N''Khiếu nại không tồn tại hoặc bạn không có quyền xem.'', 1;\n    END\n    -- Recordset 1: Chi tiết khiếu nại\n    SELECT\n        kn.KhieuNaiID,\n        kn.NguoiDungID,\n        kn.DonDatVeID,\n        kn.LoaiKhieuNai,\n        kn.TieuDe,\n        kn.NoiDung,\n        kn.MucDoUuTien,\n        kn.NgayTao,\n        kn.TrangThai,\n        kn.NhanVienPhuTrachID,\n        nv.HoTen AS TenNhanVienPhuTrach\n    FROM\n        dbo.KHIEUNAI kn\n        LEFT JOIN dbo.NGUOIDUNG nv ON kn.NhanVienPhuTrachID = nv.NguoiDungID\n    WHERE\n        kn.KhieuNaiID = @KhieuNaiID;\n    -- Recordset 2: Các lần xử lý từ CSKH\n    SELECT\n        xl.XuLyID,\n        xl.NoiDungXuLy,\n        xl.NgayXuLy,\n        xl.TrangThaiSauXuLy\n    FROM\n        dbo.XULY_KHIEUNAI xl\n    WHERE\n        xl.KhieuNaiID = @KhieuNaiID\n    ORDER BY\n        xl.NgayXuLy ASC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Complaint_ListByCustomer","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Complaint_ListByCustomer\n    (@NguoiDungID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''KHACH_HANG'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    SELECT\n        KhieuNaiID,\n        NguoiDungID,\n        DonDatVeID,\n        LoaiKhieuNai,\n        TieuDe,\n        NoiDung,\n        MucDoUuTien,\n        NgayTao,\n        TrangThai\n    FROM\n        dbo.KHIEUNAI\n    WHERE\n        NguoiDungID = @NguoiDungID\n    ORDER BY\n        NgayTao DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Complaint_Unassigned_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Complaint_Unassigned_List\n    (\n    @NguoiDungID INT,\n    @LoaiKhieuNai NVARCHAR(100) = NULL,\n    @SearchTerm NVARCHAR(100) = NULL,\n    @MucDoUuTien NVARCHAR(50) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n\n    -- Kiểm tra tài khoản\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG\n        WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n\n    -- Kiểm tra vai trò CSKH hoặc ADMIN\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''CSKH'', ''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n\n    -- Kiểm tra quyền QL_KHIEUNAI\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF @MucDoUuTien IS NOT NULL\n        AND @MucDoUuTien NOT IN (N''Thấp'', N''Trung bình'', N''Cao'', N''Khẩn cấp'')\n        THROW 50405, N''Mức ưu tiên không hợp lệ.'', 1;\n\n    SELECT\n        kn.KhieuNaiID,\n        kn.NguoiGuiID,\n        kn.HoTenNguoiGui,\n        kn.EmailNguoiGui,\n        kn.SoDienThoaiNguoiGui,\n        kn.DonDatVeID,\n        kn.LoaiKhieuNai,\n        kn.TieuDe,\n        kn.NoiDung,\n        kn.MucDoUuTien,\n        kn.NgayTao,\n        kn.TrangThaiKhieuNai,\n        kn.NhanVienPhuTrachID,\n        kn.TenNhanVienPhuTrach,\n        kn.SoLanXuLy,\n        kn.NgayXuLyCuoi,\n        kn.NguoiXuLyCuoi,\n        kn.NoiDungXuLyCuoi\n    FROM dbo.vw_DanhSachKhieuNai kn\n    WHERE kn.NhanVienPhuTrachID IS NULL\n      AND kn.TrangThaiKhieuNai NOT IN (N''Đã đóng'', N''Từ chối'', N''Đã giải quyết'')\n      AND (@LoaiKhieuNai IS NULL OR kn.LoaiKhieuNai = @LoaiKhieuNai)\n      AND (@MucDoUuTien IS NULL OR kn.MucDoUuTien = @MucDoUuTien)\n      AND (\n          @SearchTerm IS NULL\n          OR kn.TieuDe LIKE ''%'' + @SearchTerm + ''%''\n          OR kn.HoTenNguoiGui LIKE ''%'' + @SearchTerm + ''%''\n          OR kn.EmailNguoiGui LIKE ''%'' + @SearchTerm + ''%''\n      )\n    ORDER BY\n        CASE kn.MucDoUuTien\n            WHEN N''Khẩn cấp'' THEN 1\n            WHEN N''Cao'' THEN 2\n            WHEN N''Trung bình'' THEN 3\n            ELSE 4\n        END ASC,\n        kn.NgayTao DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_DatVe","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Alias sp_DatVe cho sp_Booking_Create theo bảng hợp đồng Use Case\nCREATE   PROCEDURE dbo.sp_DatVe\n    (\n    @NguoiDungID INT,\n    @SuatChieuID INT,\n    @MaKhuyenMai VARCHAR(50) = NULL,\n    @DanhSachGheId VARCHAR(MAX),\n    @DanhSachDoAnJson NVARCHAR(MAX) = NULL,\n    @NewDonDatVeID INT OUTPUT\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    EXEC dbo.sp_Booking_Create @NguoiDungID = @NguoiDungID,\n        @SuatChieuID = @SuatChieuID,\n        @MaKhuyenMai = @MaKhuyenMai,\n        @DanhSachGheId = @DanhSachGheId,\n        @DanhSachDoAnJson = @DanhSachDoAnJson,\n        @NewDonDatVeID = @NewDonDatVeID OUTPUT;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Escalation_Claim","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Escalation_Claim\n    (\n    @AdminID INT,\n    @YeuCauID INT\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n\n    -- Kiểm tra tài khoản Admin\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG\n        WHERE NguoiDungID = @AdminID AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n\n    -- Kiểm tra vai trò ADMIN\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE nd.NguoiDungID = @AdminID AND vt.MaVaiTro = ''ADMIN''\n    )\n        THROW 50301, N''Chỉ Quản trị viên mới được tiếp nhận yêu cầu chuyển cấp.'', 1;\n\n    -- Kiểm tra quyền CHUYENCAP_TIEPNHAN\n    IF dbo.fn_KiemTraQuyenNguoiDung(@AdminID, ''CHUYENCAP_TIEPNHAN'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    BEGIN TRY\n        BEGIN TRANSACTION;\n\n        -- Khóa hàng yêu cầu chuyển cấp để ngăn hai Admin cùng nhận\n        DECLARE @KhieuNaiID INT, @CurrentAdmin INT, @CurrentTrangThai NVARCHAR(50);\n        SELECT\n            @KhieuNaiID = KhieuNaiID,\n            @CurrentAdmin = AdminPhuTrachID,\n            @CurrentTrangThai = TrangThai\n        FROM dbo.YEUCAU_CHUYENCAP WITH (UPDLOCK, HOLDLOCK)\n        WHERE YeuCauID = @YeuCauID;\n\n        IF @KhieuNaiID IS NULL\n            THROW 50700, N''Yêu cầu chuyển cấp không tồn tại.'', 1;\n\n        IF @CurrentTrangThai <> N''Chờ tiếp nhận'' OR @CurrentAdmin IS NOT NULL\n            THROW 50701, N''Yêu cầu này đã được tiếp nhận hoặc đã được xử lý.'', 1;\n\n        -- Cập nhật Admin tiếp nhận\n        UPDATE dbo.YEUCAU_CHUYENCAP\n        SET\n            AdminPhuTrachID = @AdminID,\n            TrangThai = N''Đang xử lý'',\n            ThoiGianTiepNhan = dbo.fn_BayGio()\n        WHERE YeuCauID = @YeuCauID;\n\n        -- Ghi nhật ký xử lý khiếu nại\n        INSERT INTO dbo.XULY_KHIEUNAI (\n            KhieuNaiID,\n            NguoiXuLyID,\n            NoiDungXuLy,\n            NgayXuLy,\n            TrangThaiSauXuLy\n        )\n        VALUES (\n            @KhieuNaiID,\n            @AdminID,\n            N''Quản trị viên tiếp nhận yêu cầu chuyển cấp.'',\n            dbo.fn_BayGio(),\n            (SELECT TrangThai FROM dbo.KHIEUNAI WHERE KhieuNaiID = @KhieuNaiID)\n        );\n\n        -- Ghi tin nhắn nội bộ thông báo\n        INSERT INTO dbo.TINNHAN_KHIEUNAI (\n            KhieuNaiID,\n            NguoiGuiID,\n            NoiDung,\n            LoaiTinNhan,\n            ThoiGianGui\n        )\n        VALUES (\n            @KhieuNaiID,\n            @AdminID,\n            N''[ADMIN TIẾP NHẬN YÊU CẦU CHUYỂN CẤP]: Quản trị viên đã tiếp nhận yêu cầu và đang tiến hành xử lý.'',\n            N''Nội bộ'',\n            dbo.fn_BayGio()\n        );\n\n        COMMIT TRANSACTION;\n\n        SELECT\n            yc.YeuCauID,\n            yc.KhieuNaiID,\n            yc.NguoiYeuCauID,\n            nd_yc.HoTen AS TenNguoiYeuCau,\n            yc.LyDo,\n            yc.MucDoUuTien,\n            yc.AdminPhuTrachID,\n            nd_adm.HoTen AS TenAdminPhuTrach,\n            yc.TrangThai,\n            yc.ThoiGianGui,\n            yc.ThoiGianTiepNhan,\n            yc.KetQuaXuLy,\n            yc.ThoiGianHoanTat\n        FROM dbo.YEUCAU_CHUYENCAP yc\n        INNER JOIN dbo.NGUOIDUNG nd_yc ON nd_yc.NguoiDungID = yc.NguoiYeuCauID\n        LEFT JOIN dbo.NGUOIDUNG nd_adm ON nd_adm.NguoiDungID = yc.AdminPhuTrachID\n        WHERE yc.YeuCauID = @YeuCauID;\n    END TRY\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0\n            ROLLBACK TRANSACTION;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Escalation_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Escalation_Create\n    (\n    @NguoiDungID INT,\n    @KhieuNaiID INT,\n    @LyDo NVARCHAR(500),\n    @MucDoUuTien NVARCHAR(50) = N''Trung bình''\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n\n    -- Kiểm tra tài khoản\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG\n        WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n\n    -- Kiểm tra vai trò CSKH\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro = ''CSKH''\n    )\n        THROW 50301, N''Chỉ nhân viên Chăm sóc khách hàng mới được tạo yêu cầu chuyển cấp.'', 1;\n\n    -- Kiểm tra quyền CHUYENCAP_TAO\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''CHUYENCAP_TAO'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    -- Kiểm tra tính hợp lệ của dữ liệu đầu vào\n    IF @LyDo IS NULL OR LEN(LTRIM(RTRIM(@LyDo))) = 0\n        THROW 50403, N''Lý do chuyển cấp không được để trống.'', 1;\n\n    IF @MucDoUuTien NOT IN (N''Khẩn cấp'', N''Cao'', N''Trung bình'', N''Thấp'')\n        THROW 50405, N''Mức ưu tiên không hợp lệ.'', 1;\n\n    -- Kiểm tra khiếu nại\n    DECLARE @NhanVienPhuTrachID INT, @TrangThaiKhieuNai NVARCHAR(50);\n    SELECT\n        @NhanVienPhuTrachID = kn.NhanVienPhuTrachID,\n        @TrangThaiKhieuNai = kn.TrangThai\n    FROM dbo.KHIEUNAI kn\n    WHERE kn.KhieuNaiID = @KhieuNaiID;\n\n    IF @TrangThaiKhieuNai IS NULL\n        THROW 50061, N''Khiếu nại không tồn tại.'', 1;\n\n    IF @NhanVienPhuTrachID IS NULL OR @NhanVienPhuTrachID <> @NguoiDungID\n        THROW 50305, N''Chỉ nhân viên đang phụ trách khiếu nại mới được gửi yêu cầu chuyển cấp.'', 1;\n\n    BEGIN TRY\n        BEGIN TRANSACTION;\n\n        -- Khóa kiểm tra yêu cầu chuyển cấp đang mở\n        IF EXISTS (\n            SELECT 1 FROM dbo.YEUCAU_CHUYENCAP WITH (UPDLOCK, HOLDLOCK)\n            WHERE KhieuNaiID = @KhieuNaiID\n              AND TrangThai IN (N''Chờ tiếp nhận'', N''Đang xử lý'')\n        )\n            THROW 50702, N''Khiếu nại này đang có một yêu cầu chuyển cấp chưa hoàn tất.'', 1;\n\n        -- Thêm yêu cầu chuyển cấp\n        INSERT INTO dbo.YEUCAU_CHUYENCAP (\n            KhieuNaiID,\n            NguoiYeuCauID,\n            LyDo,\n            MucDoUuTien,\n            AdminPhuTrachID,\n            TrangThai,\n            ThoiGianGui,\n            ThoiGianTiepNhan,\n            KetQuaXuLy,\n            ThoiGianHoanTat\n        )\n        VALUES (\n            @KhieuNaiID,\n            @NguoiDungID,\n            @LyDo,\n            @MucDoUuTien,\n            NULL,\n            N''Chờ tiếp nhận'',\n            dbo.fn_BayGio(),\n            NULL,\n            NULL,\n            NULL\n        );\n\n        DECLARE @NewYeuCauID INT = SCOPE_IDENTITY();\n\n        -- Ghi nhật ký xử lý khiếu nại\n        INSERT INTO dbo.XULY_KHIEUNAI (\n            KhieuNaiID,\n            NguoiXuLyID,\n            NoiDungXuLy,\n            NgayXuLy,\n            TrangThaiSauXuLy\n        )\n        VALUES (\n            @KhieuNaiID,\n            @NguoiDungID,\n            N''CSKH chuyển cấp lên Admin ('' + @MucDoUuTien + N''): '' + @LyDo,\n            dbo.fn_BayGio(),\n            @TrangThaiKhieuNai\n        );\n\n        -- Ghi tin nhắn nội bộ trong cuộc hội thoại\n        INSERT INTO dbo.TINNHAN_KHIEUNAI (\n            KhieuNaiID,\n            NguoiGuiID,\n            NoiDung,\n            LoaiTinNhan,\n            ThoiGianGui\n        )\n        VALUES (\n            @KhieuNaiID,\n            @NguoiDungID,\n            N''[YÊU CẦU CHUYỂN CẤP LÊN ADMIN - Mức độ: '' + @MucDoUuTien + N'']: '' + @LyDo,\n            N''Nội bộ'',\n            dbo.fn_BayGio()\n        );\n\n        COMMIT TRANSACTION;\n\n        -- Trả về chi tiết yêu cầu vừa tạo\n        SELECT\n            yc.YeuCauID,\n            yc.KhieuNaiID,\n            yc.NguoiYeuCauID,\n            nd_yc.HoTen AS TenNguoiYeuCau,\n            yc.LyDo,\n            yc.MucDoUuTien,\n            yc.AdminPhuTrachID,\n            yc.TrangThai,\n            yc.ThoiGianGui,\n            yc.ThoiGianTiepNhan,\n            yc.KetQuaXuLy,\n            yc.ThoiGianHoanTat\n        FROM dbo.YEUCAU_CHUYENCAP yc\n        INNER JOIN dbo.NGUOIDUNG nd_yc ON nd_yc.NguoiDungID = yc.NguoiYeuCauID\n        WHERE yc.YeuCauID = @NewYeuCauID;\n    END TRY\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0\n            ROLLBACK TRANSACTION;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Escalation_GetDetail","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Escalation_GetDetail\n    (\n    @NguoiDungID INT,\n    @YeuCauID INT\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n\n    -- Kiểm tra tài khoản\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG\n        WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n\n    -- Kiểm tra vai trò CSKH hoặc ADMIN\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''CSKH'', ''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n\n    -- Kiểm tra quyền CHUYENCAP_XEM\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''CHUYENCAP_XEM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    DECLARE @KhieuNaiID INT;\n    SELECT @KhieuNaiID = KhieuNaiID FROM dbo.YEUCAU_CHUYENCAP WHERE YeuCauID = @YeuCauID;\n\n    IF @KhieuNaiID IS NULL\n        THROW 50700, N''Yêu cầu chuyển cấp không tồn tại.'', 1;\n\n    -- Recordset 1: Chi tiết yêu cầu chuyển cấp & khiếu nại liên quan\n    SELECT\n        yc.YeuCauID,\n        yc.KhieuNaiID,\n        kn.TieuDe AS TieuDeKhieuNai,\n        kn.LoaiKhieuNai,\n        kn.NoiDung AS NoiDungKhieuNai,\n        kn.MucDoUuTien AS MucDoUuTienKhieuNai,\n        kn.TrangThai AS TrangThaiKhieuNai,\n        kn.DonDatVeID,\n        nd_kh.NguoiDungID AS KhachHangID,\n        nd_kh.HoTen AS HoTenKhachHang,\n        nd_kh.Email AS EmailKhachHang,\n        nd_kh.SoDienThoai AS SoDienThoaiKhachHang,\n        yc.NguoiYeuCauID,\n        nd_yc.HoTen AS TenNguoiYeuCau,\n        nd_yc.Email AS EmailNguoiYeuCau,\n        yc.LyDo,\n        yc.MucDoUuTien,\n        yc.AdminPhuTrachID,\n        nd_adm.HoTen AS TenAdminPhuTrach,\n        nd_adm.Email AS EmailAdminPhuTrach,\n        yc.TrangThai,\n        yc.ThoiGianGui,\n        yc.ThoiGianTiepNhan,\n        yc.KetQuaXuLy,\n        yc.ThoiGianHoanTat\n    FROM dbo.YEUCAU_CHUYENCAP yc\n    INNER JOIN dbo.KHIEUNAI kn ON kn.KhieuNaiID = yc.KhieuNaiID\n    INNER JOIN dbo.NGUOIDUNG nd_kh ON nd_kh.NguoiDungID = kn.NguoiDungID\n    INNER JOIN dbo.NGUOIDUNG nd_yc ON nd_yc.NguoiDungID = yc.NguoiYeuCauID\n    LEFT JOIN dbo.NGUOIDUNG nd_adm ON nd_adm.NguoiDungID = yc.AdminPhuTrachID\n    WHERE yc.YeuCauID = @YeuCauID;\n\n    -- Recordset 2: Toàn bộ tin nhắn liên quan (cả nội bộ vì đây là CSKH/Admin)\n    SELECT\n        tn.TinNhanID,\n        tn.KhieuNaiID,\n        tn.NguoiGuiID,\n        nd.HoTen AS HoTenNguoiGui,\n        vt.MaVaiTro AS MaVaiTroNguoiGui,\n        vt.TenVaiTro AS TenVaiTroNguoiGui,\n        tn.NoiDung,\n        tn.LoaiTinNhan,\n        tn.ThoiGianGui\n    FROM dbo.TINNHAN_KHIEUNAI tn\n    INNER JOIN dbo.NGUOIDUNG nd ON nd.NguoiDungID = tn.NguoiGuiID\n    INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n    WHERE tn.KhieuNaiID = @KhieuNaiID\n    ORDER BY tn.ThoiGianGui ASC, tn.TinNhanID ASC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Escalation_List_Admin","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Escalation_List_Admin\n    (\n    @AdminID INT,\n    @TrangThai NVARCHAR(50) = NULL,\n    @MucDoUuTien NVARCHAR(50) = NULL,\n    @SearchTerm NVARCHAR(100) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n\n    -- Kiểm tra tài khoản Admin\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG\n        WHERE NguoiDungID = @AdminID AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n\n    -- Kiểm tra vai trò ADMIN\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE nd.NguoiDungID = @AdminID AND vt.MaVaiTro = ''ADMIN''\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n\n    -- Kiểm tra quyền CHUYENCAP_XEM\n    IF dbo.fn_KiemTraQuyenNguoiDung(@AdminID, ''CHUYENCAP_XEM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    IF @MucDoUuTien IS NOT NULL\n        AND @MucDoUuTien NOT IN (N''Thấp'', N''Trung bình'', N''Cao'', N''Khẩn cấp'')\n        THROW 50405, N''Mức ưu tiên không hợp lệ.'', 1;\n\n    SELECT\n        yc.YeuCauID,\n        yc.KhieuNaiID,\n        kn.TieuDe AS TieuDeKhieuNai,\n        kn.LoaiKhieuNai,\n        kn.MucDoUuTien AS MucDoUuTienKhieuNai,\n        nd_kh.HoTen AS HoTenKhachHang,\n        nd_kh.Email AS EmailKhachHang,\n        yc.NguoiYeuCauID,\n        nd_yc.HoTen AS TenNguoiYeuCau,\n        nd_yc.Email AS EmailNguoiYeuCau,\n        yc.LyDo,\n        yc.MucDoUuTien,\n        yc.AdminPhuTrachID,\n        nd_adm.HoTen AS TenAdminPhuTrach,\n        yc.TrangThai,\n        yc.ThoiGianGui,\n        yc.ThoiGianTiepNhan,\n        yc.KetQuaXuLy,\n        yc.ThoiGianHoanTat\n    FROM dbo.YEUCAU_CHUYENCAP yc\n    INNER JOIN dbo.KHIEUNAI kn ON kn.KhieuNaiID = yc.KhieuNaiID\n    INNER JOIN dbo.NGUOIDUNG nd_kh ON nd_kh.NguoiDungID = kn.NguoiDungID\n    INNER JOIN dbo.NGUOIDUNG nd_yc ON nd_yc.NguoiDungID = yc.NguoiYeuCauID\n    LEFT JOIN dbo.NGUOIDUNG nd_adm ON nd_adm.NguoiDungID = yc.AdminPhuTrachID\n    WHERE (@TrangThai IS NULL OR yc.TrangThai = @TrangThai)\n      AND (@MucDoUuTien IS NULL OR yc.MucDoUuTien = @MucDoUuTien)\n      AND (\n          @SearchTerm IS NULL\n          OR kn.TieuDe LIKE ''%'' + @SearchTerm + ''%''\n          OR yc.LyDo LIKE ''%'' + @SearchTerm + ''%''\n          OR nd_kh.HoTen LIKE ''%'' + @SearchTerm + ''%''\n          OR nd_yc.HoTen LIKE ''%'' + @SearchTerm + ''%''\n      )\n    ORDER BY\n        CASE yc.TrangThai\n            WHEN N''Chờ tiếp nhận'' THEN 1\n            WHEN N''Đang xử lý'' THEN 2\n            ELSE 3\n        END ASC,\n        CASE yc.MucDoUuTien\n            WHEN N''Khẩn cấp'' THEN 1\n            WHEN N''Cao'' THEN 2\n            WHEN N''Trung bình'' THEN 3\n            ELSE 4\n        END ASC,\n        yc.ThoiGianGui DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Escalation_List_CSKH","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Escalation_List_CSKH\n    (\n    @NguoiDungID INT,\n    @KhieuNaiID INT = NULL,\n    @TrangThai NVARCHAR(50) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n\n    -- Kiểm tra tài khoản\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG\n        WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n\n    -- Kiểm tra vai trò CSKH\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro = ''CSKH''\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n\n    -- Kiểm tra quyền CHUYENCAP_XEM\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''CHUYENCAP_XEM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    SELECT\n        yc.YeuCauID,\n        yc.KhieuNaiID,\n        kn.TieuDe AS TieuDeKhieuNai,\n        kn.LoaiKhieuNai,\n        kn.MucDoUuTien AS MucDoUuTienKhieuNai,\n        nd_kh.HoTen AS HoTenKhachHang,\n        yc.NguoiYeuCauID,\n        nd_yc.HoTen AS TenNguoiYeuCau,\n        yc.LyDo,\n        yc.MucDoUuTien,\n        yc.AdminPhuTrachID,\n        nd_adm.HoTen AS TenAdminPhuTrach,\n        yc.TrangThai,\n        yc.ThoiGianGui,\n        yc.ThoiGianTiepNhan,\n        yc.KetQuaXuLy,\n        yc.ThoiGianHoanTat\n    FROM dbo.YEUCAU_CHUYENCAP yc\n    INNER JOIN dbo.KHIEUNAI kn ON kn.KhieuNaiID = yc.KhieuNaiID\n    INNER JOIN dbo.NGUOIDUNG nd_kh ON nd_kh.NguoiDungID = kn.NguoiDungID\n    INNER JOIN dbo.NGUOIDUNG nd_yc ON nd_yc.NguoiDungID = yc.NguoiYeuCauID\n    LEFT JOIN dbo.NGUOIDUNG nd_adm ON nd_adm.NguoiDungID = yc.AdminPhuTrachID\n    WHERE (yc.NguoiYeuCauID = @NguoiDungID OR kn.NhanVienPhuTrachID = @NguoiDungID)\n      AND (@KhieuNaiID IS NULL OR yc.KhieuNaiID = @KhieuNaiID)\n      AND (@TrangThai IS NULL OR yc.TrangThai = @TrangThai)\n    ORDER BY\n        CASE yc.TrangThai\n            WHEN N''Chờ tiếp nhận'' THEN 1\n            WHEN N''Đang xử lý'' THEN 2\n            ELSE 3\n        END ASC,\n        yc.ThoiGianGui DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Escalation_Process","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Escalation_Process\n    (\n    @AdminID INT,\n    @YeuCauID INT,\n    @KetQuaXuLy NVARCHAR(MAX),\n    @TrangThaiMoi NVARCHAR(50)\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n\n    -- Kiểm tra tài khoản Admin\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG\n        WHERE NguoiDungID = @AdminID AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n\n    -- Kiểm tra vai trò ADMIN\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE nd.NguoiDungID = @AdminID AND vt.MaVaiTro = ''ADMIN''\n    )\n        THROW 50301, N''Chỉ Quản trị viên mới được xử lý yêu cầu chuyển cấp.'', 1;\n\n    -- Kiểm tra quyền CHUYENCAP_XULY\n    IF dbo.fn_KiemTraQuyenNguoiDung(@AdminID, ''CHUYENCAP_XULY'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    -- Kiểm tra trạng thái mới\n    IF @TrangThaiMoi NOT IN (N''Đã giải quyết'', N''Từ chối'')\n        THROW 50406, N''Trạng thái kết thúc không hợp lệ (chỉ chấp nhận Đã giải quyết hoặc Từ chối).'', 1;\n\n    -- Kiểm tra kết quả xử lý\n    IF @KetQuaXuLy IS NULL OR LEN(LTRIM(RTRIM(@KetQuaXuLy))) = 0\n        THROW 50407, N''Kết luận xử lý bắt buộc không được để trống.'', 1;\n\n    BEGIN TRY\n        BEGIN TRANSACTION;\n\n        DECLARE @KhieuNaiID INT, @CurrentAdmin INT, @CurrentTrangThai NVARCHAR(50);\n        SELECT\n            @KhieuNaiID = KhieuNaiID,\n            @CurrentAdmin = AdminPhuTrachID,\n            @CurrentTrangThai = TrangThai\n        FROM dbo.YEUCAU_CHUYENCAP WITH (UPDLOCK, HOLDLOCK)\n        WHERE YeuCauID = @YeuCauID;\n\n        IF @KhieuNaiID IS NULL\n            THROW 50700, N''Yêu cầu chuyển cấp không tồn tại.'', 1;\n\n        IF @CurrentAdmin IS NULL OR @CurrentAdmin <> @AdminID\n            THROW 50703, N''Bạn không phải là quản trị viên đang tiếp nhận yêu cầu này.'', 1;\n\n        IF @CurrentTrangThai <> N''Đang xử lý''\n            THROW 50704, N''Yêu cầu chuyển cấp không ở trạng thái đang xử lý.'', 1;\n\n        -- Cập nhật kết quả và hoàn tất yêu cầu\n        UPDATE dbo.YEUCAU_CHUYENCAP\n        SET\n            KetQuaXuLy = @KetQuaXuLy,\n            TrangThai = @TrangThaiMoi,\n            ThoiGianHoanTat = dbo.fn_BayGio()\n        WHERE YeuCauID = @YeuCauID;\n\n        -- Ghi nhật ký xử lý khiếu nại\n        INSERT INTO dbo.XULY_KHIEUNAI (\n            KhieuNaiID,\n            NguoiXuLyID,\n            NoiDungXuLy,\n            NgayXuLy,\n            TrangThaiSauXuLy\n        )\n        VALUES (\n            @KhieuNaiID,\n            @AdminID,\n            N''Quản trị viên hoàn tất yêu cầu chuyển cấp ('' + @TrangThaiMoi + N''): '' + @KetQuaXuLy,\n            dbo.fn_BayGio(),\n            (SELECT TrangThai FROM dbo.KHIEUNAI WHERE KhieuNaiID = @KhieuNaiID)\n        );\n\n        -- Ghi tin nhắn nội bộ thông báo kết luận cho CSKH\n        INSERT INTO dbo.TINNHAN_KHIEUNAI (\n            KhieuNaiID,\n            NguoiGuiID,\n            NoiDung,\n            LoaiTinNhan,\n            ThoiGianGui\n        )\n        VALUES (\n            @KhieuNaiID,\n            @AdminID,\n            N''[ADMIN KẾT LUẬN YÊU CẦU CHUYỂN CẤP - '' + @TrangThaiMoi + N'']: '' + @KetQuaXuLy,\n            N''Nội bộ'',\n            dbo.fn_BayGio()\n        );\n\n        COMMIT TRANSACTION;\n\n        SELECT\n            yc.YeuCauID,\n            yc.KhieuNaiID,\n            yc.NguoiYeuCauID,\n            nd_yc.HoTen AS TenNguoiYeuCau,\n            yc.LyDo,\n            yc.MucDoUuTien,\n            yc.AdminPhuTrachID,\n            nd_adm.HoTen AS TenAdminPhuTrach,\n            yc.TrangThai,\n            yc.ThoiGianGui,\n            yc.ThoiGianTiepNhan,\n            yc.KetQuaXuLy,\n            yc.ThoiGianHoanTat\n        FROM dbo.YEUCAU_CHUYENCAP yc\n        INNER JOIN dbo.NGUOIDUNG nd_yc ON nd_yc.NguoiDungID = yc.NguoiYeuCauID\n        LEFT JOIN dbo.NGUOIDUNG nd_adm ON nd_adm.NguoiDungID = yc.AdminPhuTrachID\n        WHERE yc.YeuCauID = @YeuCauID;\n    END TRY\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0\n            ROLLBACK TRANSACTION;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Genre_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Genre_List\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT\n        TheLoaiID,\n        TenTheLoai\n    FROM\n        dbo.THELOAI\n    ORDER BY\n        TenTheLoai;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Dashboard","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/manager/manager_procedures.sql:713 (dbo.sp_Manager_Dashboard)\nCREATE   PROCEDURE dbo.sp_Manager_Dashboard\n    (@NguoiDungID INT, @RapID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''XEM_BAO_CAO_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Kiểm tra phạm vi rạp còn được phân công.\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;\n        THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền truy cập rạp này.'', 1;\n    END\n    -- Chỉ số tổng hợp rạp\n    SELECT\n        r.RapID,\n        r.TenRap,\n        r.ThanhPho,\n        (\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.PHONGCHIEU pc\n            WHERE\n                pc.RapID = @RapID\n                AND pc.TrangThai = N''Hoạt động''\n        ) AS TongPhongChieu,\n        (\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.GHE g\n                INNER JOIN dbo.PHONGCHIEU pc ON g.PhongID = pc.PhongID\n            WHERE\n                pc.RapID = @RapID\n                AND g.TrangThai = N''Hoạt động''\n        ) AS TongGhe,\n        (\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.SUATCHIEU sc\n                INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\n            WHERE\n                pc.RapID = @RapID\n                AND dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau) = dbo.fn_HomNay()\n                AND sc.TrangThai <> N''Đã hủy''\n        ) AS SuatChieuHomNay,\n        (\n            SELECT\n                COUNT(DISTINCT ddv.DonDatVeID)\n            FROM\n                dbo.DONDATVE ddv\n                INNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\n                INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\n            WHERE\n                pc.RapID = @RapID\n                AND EXISTS (\n                    SELECT\n                        1\n                    FROM\n                        dbo.THANHTOAN tt\n                    WHERE\n                        tt.DonDatVeID = ddv.DonDatVeID\n                        AND tt.TrangThai = N''Thành công''\n                    GROUP BY\n                        tt.DonDatVeID\n                    HAVING\n                        dbo.fn_NgayKinhDoanh(MAX(ISNULL(tt.NgayThanhToan, tt.NgayTao))) = dbo.fn_HomNay()\n                )\n        ) AS DonDatVeHomNay\n    FROM\n        dbo.RAPCHIEUPHIM r\n    WHERE\n        r.RapID = @RapID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_ListAssignedCinemas","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/manager/manager_procedures.sql:19 (dbo.sp_Manager_ListAssignedCinemas)\nCREATE   PROCEDURE dbo.sp_Manager_ListAssignedCinemas\n    (@NguoiDungID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    SELECT\n        pcr.PhanCongID,\n        pcr.RapID,\n        r.TenRap,\n        r.DiaChi,\n        r.ThanhPho,\n        r.SoDienThoai,\n        pcr.NgayBatDau,\n        pcr.NgayKetThuc,\n        pcr.TrangThai AS TrangThaiPhanCong\n    FROM\n        dbo.PHANCONG_RAP pcr\n        INNER JOIN dbo.RAPCHIEUPHIM r ON pcr.RapID = r.RapID\n    WHERE\n        pcr.NguoiDungID = @NguoiDungID\n        AND pcr.TrangThai = N''Hiệu lực''\n        AND dbo.fn_HomNay() >= pcr.NgayBatDau\n        AND (\n            pcr.NgayKetThuc IS NULL\n            OR dbo.fn_HomNay() <= pcr.NgayKetThuc\n        );\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Pricing_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Pricing_Create\n    (\n    @NguoiDungID INT,\n    @RapID INT,\n    @LoaiGhe NVARCHAR(50),\n    @LoaiNgay NVARCHAR(50),\n    @DinhDang NVARCHAR(50),\n    @PhuThu DECIMAL(18, 2),\n    @NgayBatDau DATE,\n    @NgayKetThuc DATE = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_BANG_GIA'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Kiểm tra phạm vi rạp còn được phân công.\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;\n        THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n    END\n    INSERT INTO\n        dbo.BANGGIA(\n            RapID,\n            LoaiGhe,\n            LoaiNgay,\n            DinhDang,\n            PhuThu,\n            NgayBatDau,\n            NgayKetThuc,\n            TrangThai\n        )\n    VALUES\n        (\n            @RapID,\n            @LoaiGhe,\n            @LoaiNgay,\n            @DinhDang,\n            @PhuThu,\n            @NgayBatDau,\n            @NgayKetThuc,\n            N''Áp dụng''\n        );\n    SELECT\n        GiaID,\n        RapID,\n        LoaiGhe,\n        LoaiNgay,\n        DinhDang,\n        PhuThu,\n        NgayBatDau,\n        NgayKetThuc,\n        TrangThai\n    FROM\n        dbo.BANGGIA\n    WHERE\n        GiaID = SCOPE_IDENTITY();\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Pricing_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Pricing_List\n    (@NguoiDungID INT, @RapID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_BANG_GIA'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Kiểm tra phạm vi rạp còn được phân công.\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;\n        THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n    END\n    SELECT\n        GiaID,\n        RapID,\n        LoaiGhe,\n        LoaiNgay,\n        DinhDang,\n        PhuThu,\n        NgayBatDau,\n        NgayKetThuc,\n        TrangThai\n    FROM\n        dbo.BANGGIA\n    WHERE\n        RapID = @RapID\n    ORDER BY\n        NgayBatDau DESC,\n        LoaiGhe,\n        LoaiNgay;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Pricing_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Pricing_Update\n    (\n    @NguoiDungID INT,\n    @GiaID INT,\n    @PhuThu DECIMAL(18, 2),\n    @TrangThai NVARCHAR(50),\n    @LoaiGhe NVARCHAR(50) = NULL,\n    @LoaiNgay NVARCHAR(50) = NULL,\n    @DinhDang NVARCHAR(50) = NULL,\n    @NgayBatDau DATE = NULL,\n    @NgayKetThuc DATE = NULL,\n    @CapNhatDieuKien BIT = 0\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_BANG_GIA'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION ManagerPricingUpdate;\n        DECLARE @RapID INT;\n        SELECT\n            @RapID = RapID\n        FROM\n            dbo.BANGGIA\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            GiaID = @GiaID;\n        IF @RapID IS NULL\n            THROW 50116, N''Bảng giá không tồn tại.'', 1;\n        -- Kiểm tra phạm vi rạp còn được phân công.\n        IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n            THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n        IF @CapNhatDieuKien = 1\n            AND (\n            @LoaiGhe IS NULL\n            OR @LoaiNgay IS NULL\n            OR @DinhDang IS NULL\n            OR @NgayBatDau IS NULL\n            OR (\n                @NgayKetThuc IS NOT NULL\n                AND @NgayKetThuc < @NgayBatDau\n            )\n        )\n            THROW 50209, N''Điều kiện hoặc khoảng ngày bảng giá không hợp lệ.'', 1;\n        -- Keep RapID immutable, existing trigger/CHECK semantics, and order snapshots.\n        UPDATE dbo.BANGGIA\n        SET\n            PhuThu = @PhuThu,\n            TrangThai = @TrangThai,\n            LoaiGhe = CASE\n                WHEN @CapNhatDieuKien = 1 THEN @LoaiGhe\n                ELSE LoaiGhe\n            END,\n            LoaiNgay = CASE\n                WHEN @CapNhatDieuKien = 1 THEN @LoaiNgay\n                ELSE LoaiNgay\n            END,\n            DinhDang = CASE\n                WHEN @CapNhatDieuKien = 1 THEN @DinhDang\n                ELSE DinhDang\n            END,\n            NgayBatDau = CASE\n                WHEN @CapNhatDieuKien = 1 THEN @NgayBatDau\n                ELSE NgayBatDau\n            END,\n            NgayKetThuc = CASE\n                WHEN @CapNhatDieuKien = 1 THEN @NgayKetThuc\n                ELSE NgayKetThuc\n            END\n        WHERE\n            GiaID = @GiaID;\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION;\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION ManagerPricingUpdate;\n        END;\n        THROW;\n    END CATCH;\n    SELECT\n        GiaID,\n        RapID,\n        LoaiGhe,\n        LoaiNgay,\n        DinhDang,\n        PhuThu,\n        NgayBatDau,\n        NgayKetThuc,\n        TrangThai\n    FROM\n        dbo.BANGGIA\n    WHERE\n        GiaID = @GiaID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Revenue","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/manager/manager_procedures.sql:752 (dbo.sp_Manager_Revenue)\nCREATE   PROCEDURE dbo.sp_Manager_Revenue\n    (\n    @NguoiDungID INT,\n    @RapID INT,\n    @TuNgay DATE = NULL,\n    @DenNgay DATE = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''XEM_BAO_CAO_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Kiểm tra phạm vi rạp còn được phân công.\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;\n        THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền truy cập báo cáo rạp này.'', 1;\n    END\n    IF @TuNgay IS NULL\n        SET\n            @TuNgay = DATEADD(DAY, - 30, dbo.fn_HomNay());\n    IF @DenNgay IS NULL\n        SET\n            @DenNgay = dbo.fn_HomNay();\n    -- Doanh thu theo ngày thanh toán: chỉ tính THANHTOAN có TrangThai = ''Thành công''\n    ;\n    WITH\n        DonDaThu AS (\n            SELECT\n                ddv.DonDatVeID,\n                ddv.TongTienVe,\n                ddv.TongTienDoAn,\n                ddv.TienGiamGia,\n                ddv.DiemSuDung,\n                ddv.TrangThai AS TrangThaiDon,\n                CASE WHEN ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia < 0 THEN 0 ELSE ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia END AS TienDaThu,\n                dbo.fn_NgayKinhDoanh(MAX(ISNULL(tt.NgayThanhToan, tt.NgayTao))) AS NgayThu,\n                (\n                    SELECT\n                        COUNT(*)\n                    FROM\n                        dbo.CHITIETVE cv\n                    WHERE\n                        cv.DonDatVeID = ddv.DonDatVeID\n                        AND cv.TrangThai <> N''Đã hủy''\n                ) AS SoVe\n            FROM\n                dbo.DONDATVE ddv\n                INNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\n                INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\n                INNER JOIN dbo.THANHTOAN tt ON tt.DonDatVeID = ddv.DonDatVeID\n                AND tt.TrangThai = N''Thành công''\n            WHERE\n                pc.RapID = @RapID\n            GROUP BY\n                ddv.DonDatVeID,\n                ddv.TongTienVe,\n                ddv.TongTienDoAn,\n                ddv.TienGiamGia,\n                ddv.DiemSuDung,\n                ddv.TrangThai\n        )\n    SELECT\n        NgayThu AS Ngay,\n        COUNT(*) AS SoDon,\n        SUM(SoVe) AS SoVeBan,\n        SUM(TongTienVe) AS DoanhThuVe,\n        SUM(TongTienDoAn) AS DoanhThuDoAn,\n        SUM(TienGiamGia) AS TienGiamGia,\n        SUM(TienDaThu) AS DoanhThuThucTe,\n        SUM(CAST(DiemSuDung AS DECIMAL(18, 2)) * 1000) AS GiaTriThanhToanBangDiem,\n        SUM(CASE WHEN TrangThaiDon = N''Đã hủy'' THEN TienDaThu ELSE 0 END) AS TienThuocDonHuy\n    FROM\n        DonDaThu\n    WHERE\n        NgayThu BETWEEN @TuNgay AND @DenNgay\n    GROUP BY\n        NgayThu\n    ORDER BY\n        NgayThu DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Room_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Room_Create\n    (\n    @NguoiDungID INT,\n    @RapID INT,\n    @TenPhong NVARCHAR(100),\n    @LoaiPhong NVARCHAR(50) = N''2D''\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Kiểm tra phạm vi rạp còn được phân công.\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;\n        THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không được phân công quản lý rạp này.'', 1;\n    END\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.PHONGCHIEU\n        WHERE\n            RapID = @RapID\n            AND TenPhong = @TenPhong\n    )\n    BEGIN\n        ;\n        THROW 50051, N''Tên phòng chiếu đã tồn tại trong rạp này.'', 1;\n    END\n    INSERT INTO\n        dbo.PHONGCHIEU(RapID, TenPhong, LoaiPhong, TrangThai)\n    VALUES\n        (@RapID, @TenPhong, @LoaiPhong, N''Hoạt động'');\n    SELECT\n        PhongID,\n        RapID,\n        TenPhong,\n        LoaiPhong,\n        TrangThai\n    FROM\n        dbo.PHONGCHIEU\n    WHERE\n        PhongID = SCOPE_IDENTITY();\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Room_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Room_Delete\n    (@NguoiDungID INT, @PhongID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SET XACT_ABORT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @RapID INT,\n        @Deactivated BIT = 0;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        -- Mở transaction để các bước ghi được xử lý cùng nhau.\n        BEGIN TRANSACTION;\n        -- Lock order: room, then showtime range. Current reads also apply under RCSI.\n        SELECT\n            @RapID = RapID\n        FROM\n            dbo.PHONGCHIEU\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            PhongID = @PhongID;\n        IF @RapID IS NULL\n            THROW 50052, N''Phòng không tồn tại.'', 1;\n        -- Kiểm tra phạm vi rạp còn được phân công.\n        IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n            THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không được phân công quản lý rạp này.'', 1;\n        -- All statuses count as history; protect the empty range until commit.\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.SUATCHIEU\n            WITH\n                (UPDLOCK, HOLDLOCK)\n            WHERE\n                PhongID = @PhongID\n        )\n        BEGIN\n            -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n            UPDATE dbo.PHONGCHIEU\n            SET\n                TrangThai = N''Ngưng hoạt động''\n            WHERE\n                PhongID = @PhongID;\n            SET\n                @Deactivated = 1;\n        END\n        ELSE\n        BEGIN\n            -- Xóa các bản ghi thỏa điều kiện đã xác định.\n            DELETE FROM dbo.GHE\n            WHERE\n                PhongID = @PhongID;\n            -- Xóa các bản ghi thỏa điều kiện đã xác định.\n            DELETE FROM dbo.PHONGCHIEU\n            WHERE\n                PhongID = @PhongID;\n        END;\n        -- Chốt các thay đổi của transaction.\n        COMMIT TRANSACTION;\n        SELECT\n            @PhongID AS PhongID,\n            CAST(1 - @Deactivated AS BIT) AS Deleted,\n            @Deactivated AS Deactivated,\n            CASE\n                WHEN @Deactivated = 1 THEN N''Ngưng hoạt động''\n            END AS TrangThai,\n            CASE\n                WHEN @Deactivated = 1 THEN N''Phòng có lịch sử suất chiếu đã chuyển sang Ngưng hoạt động.''\n                ELSE N''Xóa phòng chiếu thành công.''\n            END AS [Message];\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        DECLARE @ErrorNumber INT = ERROR_NUMBER();\n        IF XACT_STATE() <> 0\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        IF @ErrorNumber IN (547, 1205, 1222)\n            THROW 50217, N''Xung đột khi xóa phòng. Dữ liệu đã được hoàn tác; vui lòng tải lại và thử lại.'', 1;\n        ;\n        THROW;\n    END CATCH;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Room_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Room_List\n    (@NguoiDungID INT, @RapID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Kiểm tra scope phân công\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;\n        THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không được phân công quản lý rạp này.'', 1;\n    END\n    SELECT\n        pc.PhongID,\n        pc.RapID,\n        r.TenRap,\n        pc.TenPhong,\n        pc.LoaiPhong,\n        pc.TrangThai,\n        (\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.GHE g\n            WHERE\n                g.PhongID = pc.PhongID\n        ) AS TongSoGhe\n    FROM\n        dbo.PHONGCHIEU pc\n        INNER JOIN dbo.RAPCHIEUPHIM r ON pc.RapID = r.RapID\n    WHERE\n        pc.RapID = @RapID\n    ORDER BY\n        pc.TenPhong;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Room_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Room_Update\n    (\n    @NguoiDungID INT,\n    @PhongID INT,\n    @TenPhong NVARCHAR(100),\n    @LoaiPhong NVARCHAR(50),\n    @TrangThai NVARCHAR(50)\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @RapID INT;\n    SELECT\n        @RapID = RapID\n    FROM\n        dbo.PHONGCHIEU\n    WHERE\n        PhongID = @PhongID;\n    IF @RapID IS NULL\n    BEGIN\n        ;\n        THROW 50052, N''Phòng chiếu không tồn tại.'', 1;\n    END\n    -- Kiểm tra phạm vi rạp còn được phân công.\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;\n        THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không được phân công quản lý rạp chứa phòng này.'', 1;\n    END\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.PHONGCHIEU\n        WHERE\n            RapID = @RapID\n            AND TenPhong = @TenPhong\n            AND PhongID <> @PhongID\n    )\n    BEGIN\n        ;\n        THROW 50051, N''Tên phòng chiếu đã trùng với phòng khác trong cùng rạp.'', 1;\n    END\n    -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n    UPDATE dbo.PHONGCHIEU\n    SET\n        TenPhong = @TenPhong,\n        LoaiPhong = @LoaiPhong,\n        TrangThai = @TrangThai\n    WHERE\n        PhongID = @PhongID;\n    SELECT\n        PhongID,\n        RapID,\n        TenPhong,\n        LoaiPhong,\n        TrangThai\n    FROM\n        dbo.PHONGCHIEU\n    WHERE\n        PhongID = @PhongID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Seat_BatchCreate","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Seat_BatchCreate\n    (\n    @NguoiDungID INT,\n    @PhongID INT,\n    @NumRows INT = 8,\n    -- Số hàng ghế (A, B, C...)\n    @SeatsPerRow INT = 12,\n    -- Số ghế mỗi hàng (1..12)\n    @VipRows INT = 3\n    -- Số hàng VIP ở giữa\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        -- Mở transaction để các bước ghi được xử lý cùng nhau.\n        BEGIN TRANSACTION;\n        DECLARE @RapID INT;\n        SELECT\n            @RapID = RapID\n        FROM\n            dbo.PHONGCHIEU\n        WHERE\n            PhongID = @PhongID;\n        -- Kiểm tra phạm vi rạp còn được phân công.\n        IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n        BEGIN\n            ;\n            THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n        END\n        -- Xóa sơ đồ ghế cũ nếu phòng chưa có vé\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.CHITIETVE cv\n                INNER JOIN dbo.GHE g ON cv.GheID = g.GheID\n            WHERE\n                g.PhongID = @PhongID\n        )\n        BEGIN\n            ;\n            THROW 50055, N''Không thể tạo lại toàn bộ sơ đồ ghế vì phòng này đã có dữ liệu vé.'', 1;\n        END\n        -- Xóa các bản ghi thỏa điều kiện đã xác định.\n        DELETE FROM dbo.GHE\n        WHERE\n            PhongID = @PhongID;\n        DECLARE @r INT = 1;\n        DECLARE @c INT = 1;\n        DECLARE @HangChar CHAR(1);\n        DECLARE @LoaiGhe NVARCHAR(50);\n        WHILE @r <= @NumRows\n        BEGIN\n            SET\n                @HangChar = CHAR(64 + @r);\n            -- 65 = ''A''\n            SET\n                @c = 1;\n            -- Xác định loại ghế: hàng giữa là VIP, hàng cuối có thể là Sweetbox\n            IF @r = @NumRows\n                SET\n                    @LoaiGhe = N''Sweetbox'';\n            ELSE\n                IF @r > (@NumRows - @VipRows - 1)\n                    AND @r < @NumRows\n                    SET\n                        @LoaiGhe = N''VIP'';\n            ELSE\n                SET\n                    @LoaiGhe = N''Thường'';\n            WHILE @c <= @SeatsPerRow\n            BEGIN\n                INSERT INTO\n                    dbo.GHE(PhongID, HangGhe, SoGhe, LoaiGhe, TrangThai)\n                VALUES\n                    (@PhongID, @HangChar, @c, @LoaiGhe, N''Hoạt động'');\n                SET\n                    @c = @c + 1;\n            END\n            SET\n                @r = @r + 1;\n        END\n        -- Chốt các thay đổi của transaction.\n        COMMIT TRANSACTION;\n        SELECT\n            COUNT(*) AS TongSoGheTao,\n            @PhongID AS PhongID\n        FROM\n            dbo.GHE\n        WHERE\n            PhongID = @PhongID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Seat_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Seat_Create\n    (\n    @NguoiDungID INT,\n    @PhongID INT,\n    @HangGhe VARCHAR(10),\n    @SoGhe INT,\n    @LoaiGhe NVARCHAR(50) = N''Thường''\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @RapID INT;\n    SELECT\n        @RapID = RapID\n    FROM\n        dbo.PHONGCHIEU\n    WHERE\n        PhongID = @PhongID;\n    -- Kiểm tra phạm vi rạp còn được phân công.\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;\n        THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n    END\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.GHE\n        WHERE\n            PhongID = @PhongID\n            AND HangGhe = @HangGhe\n            AND SoGhe = @SoGhe\n    )\n    BEGIN\n        ;\n        THROW 50054, N''Vị trí ghế này đã tồn tại trong phòng chiếu.'', 1;\n    END\n    INSERT INTO\n        dbo.GHE(PhongID, HangGhe, SoGhe, LoaiGhe, TrangThai)\n    VALUES\n        (@PhongID, @HangGhe, @SoGhe, @LoaiGhe, N''Hoạt động'');\n    SELECT\n        GheID,\n        PhongID,\n        HangGhe,\n        SoGhe,\n        LoaiGhe,\n        TrangThai\n    FROM\n        dbo.GHE\n    WHERE\n        GheID = SCOPE_IDENTITY();\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Seat_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Seat_Delete\n    (@NguoiDungID INT, @GheID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @RapID INT;\n    SELECT\n        @RapID = pc.RapID\n    FROM\n        dbo.GHE g\n        INNER JOIN dbo.PHONGCHIEU pc ON g.PhongID = pc.PhongID\n    WHERE\n        g.GheID = @GheID;\n    IF @RapID IS NULL\n    BEGIN\n        ;\n        THROW 50109, N''Ghế không tồn tại.'', 1;\n    END\n    -- Kiểm tra phạm vi rạp còn được phân công.\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;\n        THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n    END\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.CHITIETVE\n        WHERE\n            GheID = @GheID\n    )\n    BEGIN\n        ;\n        THROW 50110, N''Ghế đã có vé bán ra. Hãy chuyển trạng thái sang Hỏng/Bảo trì thay vì xóa.'', 1;\n    END\n    -- Xóa các bản ghi thỏa điều kiện đã xác định.\n    DELETE FROM dbo.GHE\n    WHERE\n        GheID = @GheID;\n    SELECT\n        N''Đã xóa ghế.'' AS [Message];\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Seat_ListByRoom","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Seat_ListByRoom\n    (@NguoiDungID INT, @PhongID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @RapID INT;\n    SELECT\n        @RapID = RapID\n    FROM\n        dbo.PHONGCHIEU\n    WHERE\n        PhongID = @PhongID;\n    -- Kiểm tra phạm vi rạp còn được phân công.\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n    BEGIN\n        ;\n        THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không được phân công quản lý rạp chứa phòng này.'', 1;\n    END\n    SELECT\n        GheID,\n        PhongID,\n        HangGhe,\n        SoGhe,\n        (HangGhe + CAST(SoGhe AS VARCHAR(10))) AS TenGhe,\n        LoaiGhe,\n        TrangThai\n    FROM\n        dbo.GHE\n    WHERE\n        PhongID = @PhongID\n    ORDER BY\n        HangGhe,\n        SoGhe;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Seat_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Seat_Update\n    @NguoiDungID INT,\n    @GheID INT,\n    @LoaiGhe NVARCHAR(50),\n    @TrangThai NVARCHAR(50)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SET XACT_ABORT ON;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION ManagerSeatUpdate;\n        DECLARE @RapID INT,\n            @OldType NVARCHAR(50);\n        SELECT\n            @RapID = pc.RapID,\n            @OldType = g.LoaiGhe\n        FROM\n            dbo.GHE g\n        WITH\n            (UPDLOCK, HOLDLOCK)\n            INNER JOIN dbo.PHONGCHIEU pc ON pc.PhongID = g.PhongID\n        WHERE\n            g.GheID = @GheID;\n        IF @RapID IS NULL\n            THROW 50109, N''Ghế không tồn tại.'', 1;\n        -- Kiểm tra phạm vi rạp còn được phân công.\n        IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n            THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n        -- Booking retains GHE update locks through ticket insertion/commit. Read\n        -- history after that lock, including cancelled/used tickets, before any write.\n        IF EXISTS (\n            SELECT\n                @LoaiGhe\n            EXCEPT\n            SELECT\n                @OldType\n        )\n            AND EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.CHITIETVE\n            WHERE\n                GheID = @GheID\n        )\n            THROW 50207, N''Ghế có lịch sử vé; không thể thay đổi loại ghế.'', 1;\n        IF dbo.fn_GheCoVeHieuLucSuatTuongLai(@GheID) = 1\n            THROW 50207, N''Ghế có vé hiệu lực ở suất chiếu tương lai.'', 1;\n        -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n        UPDATE dbo.GHE\n        SET\n            LoaiGhe = @LoaiGhe,\n            TrangThai = @TrangThai\n        WHERE\n            GheID = @GheID;\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        SELECT\n            GheID,\n            PhongID,\n            HangGhe,\n            SoGhe,\n            LoaiGhe,\n            TrangThai\n        FROM\n            dbo.GHE\n        WHERE\n            GheID = @GheID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION ManagerSeatUpdate;\n        END;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Showtime_Cancel","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Manager_Showtime_Cancel\n    @NguoiDungID INT,\n    @SuatChieuID INT,\n    @LyDo NVARCHAR(255) = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    EXEC dbo.sp_Showtime_CancelCascade @SuatChieuID = @SuatChieuID,\n        @NguoiDungID = @NguoiDungID,\n        @LyDo = @LyDo;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Showtime_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/manager/manager_procedures.sql:396 (dbo.sp_Manager_Showtime_Create)\nCREATE   PROCEDURE dbo.sp_Manager_Showtime_Create\n    (\n    @NguoiDungID INT,\n    @PhimID INT,\n    @PhongID INT,\n    @ThoiGianBatDau DATETIME2,\n    @ThoiGianKetThuc DATETIME2,\n    @DinhDang NVARCHAR(50) = N''2D'',\n    @GiaVeCoBan DECIMAL(18, 2)\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SET XACT_ABORT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION ManagerShowtimeCreate;\n        DECLARE @RapID INT,\n            @NewSuatChieuID INT;\n        SELECT\n            @RapID = RapID\n        FROM\n            dbo.PHONGCHIEU\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            PhongID = @PhongID;\n        IF @RapID IS NULL\n            THROW 50056, N''Phòng chiếu không tồn tại.'', 1;\n        -- Kiểm tra phạm vi rạp còn được phân công.\n        IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n            THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không được phân công quản lý rạp chiếu này.'', 1;\n        IF @ThoiGianKetThuc <= @ThoiGianBatDau\n            THROW 50057, N''Thời gian kết thúc phải sau thời gian bắt đầu.'', 1;\n        EXEC dbo.sp_Showtime_ValidateTimes @PhimID = @PhimID,\n            @ThoiGianBatDau = @ThoiGianBatDau,\n            @ThoiGianKetThuc = @ThoiGianKetThuc,\n            @PhongID = @PhongID;\n        INSERT\n            dbo.SUATCHIEU(\n                PhimID,\n                PhongID,\n                ThoiGianBatDau,\n                ThoiGianKetThuc,\n                DinhDang,\n                GiaVeCoBan,\n                TrangThai\n            )\n        VALUES\n            (\n                @PhimID,\n                @PhongID,\n                @ThoiGianBatDau,\n                @ThoiGianKetThuc,\n                @DinhDang,\n                @GiaVeCoBan,\n                N''Mở bán''\n            );\n        SET\n            @NewSuatChieuID = SCOPE_IDENTITY();\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        EXEC dbo.sp_Showtime_GetDetail @SuatChieuID = @NewSuatChieuID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION ManagerShowtimeCreate;\n        END;\n        -- A rethrow must not doom a still-committable caller after savepoint rollback.\n        SET XACT_ABORT OFF;\n        ;\n        THROW;\n    END CATCH;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Showtime_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Phase 7: manager-scoped showtime listing. No raw backend query is permitted.\nCREATE   PROCEDURE dbo.sp_Manager_Showtime_List\n    (\n    @NguoiDungID INT,\n    @RapID INT,\n    @TuNgay DATE = NULL,\n    @DenNgay DATE = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Kiểm tra phạm vi rạp còn được phân công.\n    IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n        THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền truy cập rạp này.'', 1;\n    SELECT\n        sc.SuatChieuID,\n        sc.PhimID,\n        p.TenPhim,\n        sc.PhongID,\n        pc.TenPhong,\n        pc.RapID,\n        r.TenRap,\n        sc.ThoiGianBatDau,\n        sc.ThoiGianKetThuc,\n        sc.DinhDang,\n        sc.GiaVeCoBan,\n        sc.TrangThai\n    FROM\n        dbo.SUATCHIEU sc\n        INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\n        INNER JOIN dbo.RAPCHIEUPHIM r ON pc.RapID = r.RapID\n        INNER JOIN dbo.PHIM p ON sc.PhimID = p.PhimID\n    WHERE\n        pc.RapID = @RapID\n        AND (\n            @TuNgay IS NULL\n            OR dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau) >= @TuNgay\n        )\n        AND (\n            @DenNgay IS NULL\n            OR dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau) <= @DenNgay\n        )\n    ORDER BY\n        sc.ThoiGianBatDau DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Manager_Showtime_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/014_showtime_lifecycle.sql:143 (dbo.sp_Manager_Showtime_Update)\nCREATE   PROCEDURE dbo.sp_Manager_Showtime_Update\n    @NguoiDungID INT,\n    @SuatChieuID INT,\n    @PhimID INT,\n    @ThoiGianBatDau DATETIME2,\n    @ThoiGianKetThuc DATETIME2,\n    @DinhDang NVARCHAR(50),\n    @GiaVeCoBan DECIMAL(18, 2),\n    @TrangThai NVARCHAR(50)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SET XACT_ABORT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''QUAN_LY_RAP'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION ManagerShowtimeUpdate;\n        DECLARE @RapID INT,\n            @OldPhim INT,\n            @OldStart DATETIME2,\n            @OldEnd DATETIME2,\n            @OldRoom INT,\n            @OldFormat NVARCHAR(50),\n            @OldStatus NVARCHAR(50),\n            @OldPrice DECIMAL(18, 2);\n        -- Discovery only (RCSI read); no child update lock before the room mutex.\n        SELECT\n            @OldRoom = PhongID\n        FROM\n            dbo.SUATCHIEU\n        WHERE\n            SuatChieuID = @SuatChieuID;\n        SELECT\n            @RapID = RapID\n        FROM\n            dbo.PHONGCHIEU\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            PhongID = @OldRoom;\n        IF @RapID IS NULL\n            THROW 50058, N''Suất chiếu không tồn tại.'', 1;\n        SELECT\n            @OldPhim = PhimID,\n            @OldStart = ThoiGianBatDau,\n            @OldEnd = ThoiGianKetThuc,\n            @OldFormat = DinhDang,\n            @OldStatus = TrangThai,\n            @OldPrice = GiaVeCoBan\n        FROM\n            dbo.SUATCHIEU\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            SuatChieuID = @SuatChieuID\n            AND PhongID = @OldRoom;\n        IF @OldPhim IS NULL\n            THROW 50058, N''Suất chiếu không tồn tại.'', 1;\n        -- Kiểm tra phạm vi rạp còn được phân công.\n        IF dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n            THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n        IF @TrangThai = N''Đã hủy''\n            THROW 50123, N''Dùng route hủy suất chiếu riêng.'', 1;\n        -- R3.2: any persisted order is historical usage, including cancelled/expired.\n        -- Booking holds this same room -> show lock before creating orders. The\n        -- history read happens after waiting; no child lock order is introduced.\n        -- EXCEPT compares actual values with NULL-safe semantics. Room has no edit parameter.\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.DONDATVE\n            WHERE\n                SuatChieuID = @SuatChieuID\n        )\n            AND EXISTS (\n            SELECT\n                @PhimID,\n                @ThoiGianBatDau,\n                @ThoiGianKetThuc,\n                @DinhDang,\n                @GiaVeCoBan\n            EXCEPT\n            SELECT\n                @OldPhim,\n                @OldStart,\n                @OldEnd,\n                @OldFormat,\n                @OldPrice\n        )\n            THROW 50120, N''Suất chiếu có lịch sử đơn; không thể đổi phim, phòng, giờ, định dạng hoặc giá vé cơ bản.'', 1;\n        IF @ThoiGianKetThuc <= @ThoiGianBatDau\n            THROW 50057, N''Thời gian suất chiếu không hợp lệ.'', 1;\n        EXEC dbo.sp_Showtime_ValidateTimes @PhimID = @PhimID,\n            @ThoiGianBatDau = @ThoiGianBatDau,\n            @ThoiGianKetThuc = @ThoiGianKetThuc,\n            @PhongID = @OldRoom,\n            @SuatChieuID = @SuatChieuID,\n            @TrangThai = @TrangThai;\n        -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n        UPDATE dbo.SUATCHIEU\n        SET\n            PhimID = @PhimID,\n            ThoiGianBatDau = @ThoiGianBatDau,\n            ThoiGianKetThuc = @ThoiGianKetThuc,\n            DinhDang = @DinhDang,\n            GiaVeCoBan = @GiaVeCoBan,\n            TrangThai = @TrangThai\n        WHERE\n            SuatChieuID = @SuatChieuID;\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        -- Writer returns the persisted row even after closing sales. Public reads\n        -- continue to apply the R2.1 IsBookable filter in sp_Showtime_GetDetail.\n        SELECT\n            SuatChieuID,\n            PhimID,\n            TenPhim,\n            PosterURL,\n            ThoiLuong,\n            DoTuoi,\n            RapID,\n            TenRap,\n            DiaChiRap,\n            ThanhPho,\n            PhongID,\n            TenPhong,\n            LoaiPhong,\n            ThoiGianBatDau,\n            ThoiGianKetThuc,\n            NgayChieu,\n            GioBatDau,\n            GioKetThuc,\n            DinhDang,\n            GiaVeCoBan,\n            TrangThaiSuatChieu,\n            TongSoGhe,\n            SoGheDaDat,\n            (TongSoGhe - SoGheDaDat) AS SoGheConLai\n        FROM\n            dbo.vw_LichChieuChiTiet\n        WHERE\n            SuatChieuID = @SuatChieuID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION ManagerShowtimeUpdate;\n        END\n        SET XACT_ABORT OFF;\n        ;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Movie_GetDetail","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Movie_GetDetail\n    (@PhimID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- Recordset 1: Thông tin cơ bản phim\n    SELECT\n        p.PhimID,\n        p.TenPhim,\n        p.ThoiLuong,\n        p.NgayKhoiChieu,\n        p.NgayKetThuc,\n        p.NgonNgu,\n        p.PhuDe,\n        p.DoTuoi,\n        p.DaoDien,\n        p.MoTa,\n        p.PosterURL,\n        p.TrailerURL,\n        p.TrangThai,\n        tp.DiemDanhGiaTrungBinh,\n        tp.SoLuotDanhGia\n    FROM\n        dbo.PHIM p\n        LEFT JOIN dbo.vw_ThongKePhim tp ON p.PhimID = tp.PhimID\n    WHERE\n        p.PhimID = @PhimID;\n    -- Recordset 2: Thể loại\n    SELECT\n        t.TheLoaiID,\n        t.TenTheLoai\n    FROM\n        dbo.PHIM_THELOAI pt\n        INNER JOIN dbo.THELOAI t ON pt.TheLoaiID = t.TheLoaiID\n    WHERE\n        pt.PhimID = @PhimID;\n    -- Recordset 3: Diễn viên\n    SELECT\n        dv.DienVienID,\n        dv.HoTen,\n        dv.QuocTich,\n        pd.VaiDien\n    FROM\n        dbo.PHIM_DIENVIEN pd\n        INNER JOIN dbo.DIENVIEN dv ON pd.DienVienID = dv.DienVienID\n    WHERE\n        pd.PhimID = @PhimID;\n    -- Recordset 4: Đánh giá gần đây\n    SELECT\n        TOP 10 dg.DanhGiaID,\n        nd.HoTen AS NguoiDanhGia,\n        dg.SoSao,\n        dg.NoiDung,\n        dg.NgayDanhGia\n    FROM\n        dbo.DANHGIAPHIM dg\n        INNER JOIN dbo.NGUOIDUNG nd ON dg.NguoiDungID = nd.NguoiDungID\n    WHERE\n        dg.PhimID = @PhimID\n    ORDER BY\n        dg.NgayDanhGia DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Movie_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Movie_List\n    (\n    @TrangThai NVARCHAR(50) = NULL,\n    @TheLoaiID INT = NULL,\n    @SearchTerm NVARCHAR(100) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT DISTINCT\n        p.PhimID,\n        p.TenPhim,\n        p.ThoiLuong,\n        p.NgayKhoiChieu,\n        p.NgayKetThuc,\n        p.NgonNgu,\n        p.PhuDe,\n        p.DoTuoi,\n        p.DaoDien,\n        p.PosterURL,\n        p.TrailerURL,\n        p.TrangThai,\n        tp.DiemDanhGiaTrungBinh,\n        tp.SoLuotDanhGia,\n        STUFF(\n            (\n                SELECT\n                    '', '' + t.TenTheLoai\n                FROM\n                    dbo.PHIM_THELOAI pt\n                    INNER JOIN dbo.THELOAI t ON pt.TheLoaiID = t.TheLoaiID\n                WHERE\n                    pt.PhimID = p.PhimID\n                FOR XML\n                    PATH(''''),\n                TYPE\n            ).value(''.'', ''NVARCHAR(MAX)''),\n            1,\n            2,\n            ''''\n        ) AS DanhSachTheLoai\n    FROM\n        dbo.PHIM p\n        LEFT JOIN dbo.vw_ThongKePhim tp ON p.PhimID = tp.PhimID\n        LEFT JOIN dbo.PHIM_THELOAI pt2 ON p.PhimID = pt2.PhimID\n    WHERE\n        (\n            @TrangThai IS NULL\n            OR p.TrangThai = @TrangThai\n        )\n        AND (\n            @TheLoaiID IS NULL\n            OR pt2.TheLoaiID = @TheLoaiID\n        )\n        AND (\n            @SearchTerm IS NULL\n            OR p.TenPhim LIKE ''%'' + @SearchTerm + ''%''\n            OR p.DaoDien LIKE ''%'' + @SearchTerm + ''%''\n        )\n    ORDER BY\n        p.NgayKhoiChieu DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Order_Cancel","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Order_Cancel\n    (@NguoiDungID INT, @DonDatVeID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        -- Mở transaction để các bước ghi được xử lý cùng nhau.\n        BEGIN TRANSACTION;\n        DECLARE @TrangThai NVARCHAR(50);\n        DECLARE @KhuyenMaiID INT;\n        DECLARE @DiemSuDung INT;\n        SELECT\n            @TrangThai = TrangThai,\n            @KhuyenMaiID = KhuyenMaiID,\n            @DiemSuDung = DiemSuDung\n        FROM\n            dbo.DONDATVE\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            DonDatVeID = @DonDatVeID\n            AND NguoiDungID = @NguoiDungID;\n        IF @TrangThai IS NULL\n        BEGIN\n            ;\n            THROW 50034, N''Đơn đặt vé không tồn tại hoặc bạn không có quyền thao tác.'', 1;\n        END\n        IF @TrangThai <> N''Chờ thanh toán''\n        BEGIN\n            ;\n            THROW 50035, N''Chỉ có thể hủy đơn khi đang ở trạng thái Chờ thanh toán.'', 1;\n        END\n        -- Cập nhật đơn thành Đã hủy\n        UPDATE dbo.DONDATVE\n        SET\n            TrangThai = N''Đã hủy''\n        WHERE\n            DonDatVeID = @DonDatVeID;\n        -- Cập nhật vé thành Đã hủy để giải phóng ghế\n        UPDATE dbo.CHITIETVE\n        SET\n            TrangThai = N''Đã hủy''\n        WHERE\n            DonDatVeID = @DonDatVeID;\n        -- Trả lại điểm đã giữ cho đơn chưa thanh toán (không phải hoàn tiền).\n        IF ISNULL(@DiemSuDung, 0) > 0\n            UPDATE dbo.HOSOKHACHHANG\n            SET\n                DiemTichLuy = DiemTichLuy + @DiemSuDung\n            WHERE\n                NguoiDungID = @NguoiDungID;\n        -- Hoàn lại lượt dùng mã khuyến mãi nếu có\n        IF @KhuyenMaiID IS NOT NULL\n        BEGIN\n            -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n            UPDATE dbo.KHUYENMAI\n            SET\n                SoLuongDaDung = CASE\n                    WHEN SoLuongDaDung > 0 THEN SoLuongDaDung - 1\n                    ELSE 0\n                END\n            WHERE\n                KhuyenMaiID = @KhuyenMaiID;\n        END\n        -- Chốt các thay đổi của transaction.\n        COMMIT TRANSACTION;\n        SELECT\n            N''Hủy đơn đặt vé thành công.'' AS [Message];\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Order_ExpirePending","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/system/system_procedures.sql:38 (dbo.sp_Order_ExpirePending)\nCREATE   PROCEDURE dbo.sp_Order_ExpirePending\n    (\n    @SuatChieuID INT = NULL,\n    @TraVeKetQua BIT = 1\n    -- 0 khi gọi lồng trong thủ tục khác (không trả recordset)\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    DECLARE @TuMoTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    DECLARE @Het\n    TABLE (DonDatVeID INT PRIMARY KEY, KhuyenMaiID INT NULL);\n    DECLARE @SoDon INT = 0;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @TuMoTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION;\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION sp_Order_ExpirePending;\n        UPDATE d\n        SET\n            d.TrangThai = N''Hết hạn'' OUTPUT inserted.DonDatVeID,\n            inserted.KhuyenMaiID\n        INTO\n            @Het(DonDatVeID, KhuyenMaiID)\n        FROM\n            dbo.DONDATVE d\n        WHERE\n            d.TrangThai = N''Chờ thanh toán''\n            AND (\n                d.HanGiuCho IS NULL\n                OR d.HanGiuCho <= dbo.fn_BayGio()\n            )\n            AND (\n                @SuatChieuID IS NULL\n                OR d.SuatChieuID = @SuatChieuID\n            );\n        SET\n            @SoDon = @@ROWCOUNT;\n        IF @SoDon > 0\n        BEGIN\n            UPDATE cv\n            SET\n                cv.TrangThai = N''Đã hủy''\n            FROM\n                dbo.CHITIETVE cv\n                INNER JOIN @Het h ON h.DonDatVeID = cv.DonDatVeID\n            WHERE\n                cv.TrangThai <> N''Đã hủy'';\n            -- Điểm đã giữ cho đơn chưa thanh toán được trả lại đúng số điểm đã trừ (không phải hoàn tiền).\n            UPDATE hk\n            SET\n                hk.DiemTichLuy = hk.DiemTichLuy + x.Diem\n            FROM\n                dbo.HOSOKHACHHANG hk\n                INNER JOIN (\n                    SELECT\n                        d.NguoiDungID,\n                        SUM(d.DiemSuDung) AS Diem\n                    FROM\n                        dbo.DONDATVE d\n                        INNER JOIN @Het h ON h.DonDatVeID = d.DonDatVeID\n                    WHERE\n                        d.DiemSuDung > 0\n                    GROUP BY\n                        d.NguoiDungID\n                ) x ON x.NguoiDungID = hk.NguoiDungID;\n            UPDATE km\n            SET\n                km.SoLuongDaDung = CASE\n                    WHEN km.SoLuongDaDung >= x.SoLan THEN km.SoLuongDaDung - x.SoLan\n                    ELSE 0\n                END\n            FROM\n                dbo.KHUYENMAI km\n                INNER JOIN (\n                    SELECT\n                        KhuyenMaiID,\n                        COUNT(*) AS SoLan\n                    FROM\n                        @Het\n                    WHERE\n                        KhuyenMaiID IS NOT NULL\n                    GROUP BY\n                        KhuyenMaiID\n                ) x ON x.KhuyenMaiID = km.KhuyenMaiID;\n        END\n        IF @TuMoTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @TuMoTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION;\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION sp_Order_ExpirePending;\n        END;\n        THROW;\n    END CATCH\n    IF @TraVeKetQua = 1\n        SELECT\n            @SoDon AS SoDonHetHan;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Order_GetDetailByCustomer","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Order_GetDetailByCustomer\n    @NguoiDungID INT,\n    @DonDatVeID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''KHACH_HANG'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.DONDATVE\n        WHERE\n            DonDatVeID = @DonDatVeID\n            AND NguoiDungID = @NguoiDungID\n    )\n        THROW 50033, N''Đơn đặt vé không tồn tại hoặc bạn không có quyền xem đơn này.'', 1;\n    SELECT\n        v.[DonDatVeID],\n        v.[NguoiDungID],\n        v.[HoTenKhachHang],\n        v.[Email],\n        v.[SoDienThoai],\n        v.[SuatChieuID],\n        v.[PhimID],\n        v.[TenPhim],\n        v.[PosterURL],\n        v.[DoTuoi],\n        v.[ThoiLuong],\n        v.[RapID],\n        v.[TenRap],\n        v.[DiaChiRap],\n        v.[PhongID],\n        v.[TenPhong],\n        v.[LoaiPhong],\n        v.[ThoiGianBatDau],\n        v.[ThoiGianKetThuc],\n        v.[DinhDang],\n        v.[NgayDat],\n        v.[TongTienVe],\n        v.[TongTienDoAn],\n        v.[TienGiamGia],\n        v.[TongTienThanhToan],\n        v.[DiemSuDung],\n        v.[TrangThaiDon],\n        v.[HanGiuCho],\n        v.[MaKhuyenMai],\n        v.[MoTaKhuyenMai],\n        v.[DanhSachGhe],\n        v.[DanhSachMaVe],\n        d.LyDoHuy,\n        d.ThongBaoHuy,\n        b.DiemBoiThuong,\n        b.NgayBoiThuong\n    FROM\n        dbo.vw_ChiTietDonDatVe v\n        INNER JOIN dbo.DONDATVE d ON d.DonDatVeID = v.DonDatVeID\n        LEFT JOIN dbo.BOITHUONG_HUYSUAT b ON b.DonDatVeID = d.DonDatVeID\n    WHERE\n        v.DonDatVeID = @DonDatVeID;\n    SELECT\n        cv.VeID,\n        cv.MaVe,\n        g.GheID,\n        g.HangGhe,\n        g.SoGhe,\n        (g.HangGhe + CAST(g.SoGhe AS VARCHAR(10))) AS TenGhe,\n        g.LoaiGhe,\n        cv.GiaVe,\n        cv.TrangThai AS TrangThaiVe\n    FROM\n        dbo.CHITIETVE cv\n        INNER JOIN dbo.GHE g ON g.GheID = cv.GheID\n    WHERE\n        cv.DonDatVeID = @DonDatVeID;\n    SELECT\n        cda.ChiTietDoAnID,\n        sp.SanPhamID,\n        sp.TenSanPham,\n        sp.LoaiSanPham,\n        cda.SoLuong,\n        cda.DonGia,\n        cda.SoLuong * cda.DonGia AS ThanhTien\n    FROM\n        dbo.CHITIETDOAN cda\n        INNER JOIN dbo.SANPHAM sp ON sp.SanPhamID = cda.SanPhamID\n    WHERE\n        cda.DonDatVeID = @DonDatVeID;\n    -- STRICT 3NF: Tái dựng SoTien từ d.TongTienVe + d.TongTienDoAn - d.TienGiamGia\n    SELECT\n        tt.ThanhToanID,\n        tt.PhuongThuc,\n        CASE WHEN d.TongTienVe + d.TongTienDoAn - d.TienGiamGia < 0 THEN 0 ELSE d.TongTienVe + d.TongTienDoAn - d.TienGiamGia END AS SoTien,\n        tt.NgayTao,\n        tt.NgayThanhToan,\n        tt.MaGiaoDich,\n        tt.TrangThai,\n        tt.GhiChu\n    FROM\n        dbo.THANHTOAN tt\n        INNER JOIN dbo.DONDATVE d ON d.DonDatVeID = tt.DonDatVeID\n    WHERE\n        tt.DonDatVeID = @DonDatVeID\n    ORDER BY\n        tt.ThanhToanID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Order_ListByCustomer","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Order_ListByCustomer\n    @NguoiDungID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''KHACH_HANG'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    SELECT\n        v.[DonDatVeID],\n        v.[NguoiDungID],\n        v.[HoTenKhachHang],\n        v.[Email],\n        v.[SoDienThoai],\n        v.[SuatChieuID],\n        v.[PhimID],\n        v.[TenPhim],\n        v.[PosterURL],\n        v.[RapID],\n        v.[TenRap],\n        v.[TenPhong],\n        v.[ThoiGianBatDau],\n        v.[ThoiGianKetThuc],\n        v.[DinhDang],\n        v.[NgayDat],\n        v.[TongTienVe],\n        v.[TongTienDoAn],\n        v.[TienGiamGia],\n        v.[TongTienThanhToan],\n        v.[DiemSuDung],\n        v.[TrangThaiDon],\n        v.[HanGiuCho],\n        v.[MaKhuyenMai],\n        v.[SoLuongVe],\n        v.[TrangThaiThanhToanMoiNhat],\n        d.LyDoHuy,\n        d.ThongBaoHuy\n    FROM\n        dbo.vw_LichSuDatVe v\n        INNER JOIN dbo.DONDATVE d ON d.DonDatVeID = v.DonDatVeID\n    WHERE\n        v.NguoiDungID = @NguoiDungID\n    ORDER BY\n        v.NgayDat DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Payment_CreateAttempt","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/014_showtime_lifecycle.sql:257 (dbo.sp_Payment_CreateAttempt)\nCREATE   PROCEDURE dbo.sp_Payment_CreateAttempt\n    @NguoiDungID INT,\n    @DonDatVeID INT,\n    @PhuongThuc NVARCHAR(50),\n    @ThanhToanID INT OUTPUT,\n    @MaGiaoDich VARCHAR(100) OUTPUT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''KHACH_HANG'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''THANH_TOAN'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION PaymentCreateAttempt;\n        DECLARE @UserID INT,\n            @SuatID INT,\n            @RoomID INT,\n            @ShowStatus NVARCHAR(50),\n            @Starts DATETIME2,\n            @OrderStatus NVARCHAR(50),\n            @Hold DATETIME2,\n            @Amount DECIMAL(18, 2),\n            @Now DATETIME2;\n        SELECT\n            @UserID = NguoiDungID,\n            @SuatID = SuatChieuID\n        FROM\n            dbo.DONDATVE\n        WHERE\n            DonDatVeID = @DonDatVeID;\n        IF @UserID IS NULL\n            THROW 50030, N''Đơn đặt vé không tồn tại.'', 1;\n        IF @UserID <> @NguoiDungID\n            THROW 50033, N''Đơn đặt vé không tồn tại.'', 1;\n        DECLARE @LockedUser INT;\n        SELECT\n            @LockedUser = NguoiDungID\n        FROM\n            dbo.NGUOIDUNG\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            NguoiDungID = @UserID;\n        SELECT\n            @RoomID = PhongID,\n            @ShowStatus = TrangThai,\n            @Starts = ThoiGianBatDau\n        FROM\n            dbo.SUATCHIEU\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            SuatChieuID = @SuatID;\n        SELECT\n            @OrderStatus = TrangThai,\n            @Hold = HanGiuCho,\n            @Amount = CASE WHEN TongTienVe + TongTienDoAn - TienGiamGia < 0 THEN 0 ELSE TongTienVe + TongTienDoAn - TienGiamGia END\n        FROM\n            dbo.DONDATVE\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            DonDatVeID = @DonDatVeID;\n        SET\n            @Now = dbo.fn_BayGio();\n        -- Re-read after waiting for all lifecycle locks.\n        IF @OrderStatus = N''Hết hạn''\n            OR (\n            @OrderStatus = N''Chờ thanh toán''\n            AND (\n                @Hold IS NULL\n                OR @Hold <= @Now\n            )\n        )\n        BEGIN\n            EXEC dbo.sp_Order_ExpirePending @SuatChieuID = @SuatID,\n                @TraVeKetQua = 0;\n            IF @OwnTran = 1\n                -- Chốt các thay đổi của transaction.\n                COMMIT TRANSACTION;\n            THROW 50111, N''Đơn đã hết thời gian giữ ghế. Vui lòng đặt vé lại.'', 1;\n        END;\n        IF @OrderStatus <> N''Chờ thanh toán''\n            THROW 50031, N''Đơn hàng không ở trạng thái Chờ thanh toán.'', 1;\n        IF @RoomID IS NULL\n            OR @ShowStatus <> N''Mở bán''\n            OR @Starts <= @Now\n            THROW 50121, N''Suất chiếu không còn hợp lệ để thanh toán.'', 1;\n        -- Chỉ đơn đã được trả đủ bằng điểm (tiền phải trả = 0) mới dùng phương thức DIEM; đơn còn tiền phải trả thì không.\n        IF @PhuongThuc = N''DIEM''\n            AND @Amount > 0\n            THROW 50430, N''Thanh toán bằng điểm chỉ áp dụng cho đơn không còn tiền phải trả.'', 1;\n        IF @PhuongThuc <> N''DIEM''\n            AND @Amount <= 0\n            THROW 50431, N''Đơn đã được trả đủ bằng điểm; hãy xác nhận thanh toán bằng điểm.'', 1;\n        SET\n            @MaGiaoDich = CONCAT(\n                ''TXN-'',\n                FORMAT(@Now, ''yyyyMMddHHmmss''),\n                ''-'',\n                CAST(@DonDatVeID AS VARCHAR(10)),\n                ''-'',\n                LEFT(REPLACE(CONVERT(VARCHAR(36), NEWID()), ''-'', ''''), 6)\n            );\n        -- STRICT 3NF: Loại bỏ cột SoTien khỏi lệnh INSERT dbo.THANHTOAN\n        INSERT\n            dbo.THANHTOAN(DonDatVeID, PhuongThuc, NgayTao, MaGiaoDich, TrangThai)\n        VALUES\n            (@DonDatVeID, @PhuongThuc, @Now, @MaGiaoDich, N''Đang xử lý'');\n        SET\n            @ThanhToanID = SCOPE_IDENTITY();\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        -- STRICT 3NF: Tái dựng SoTien từ DONDATVE d để bảo toàn 100% API contract\n        SELECT\n            tt.ThanhToanID,\n            tt.DonDatVeID,\n            tt.PhuongThuc,\n            CASE WHEN d.TongTienVe + d.TongTienDoAn - d.TienGiamGia < 0 THEN 0 ELSE d.TongTienVe + d.TongTienDoAn - d.TienGiamGia END AS SoTien,\n            tt.NgayTao,\n            tt.MaGiaoDich,\n            tt.TrangThai,\n            d.HanGiuCho\n        FROM\n            dbo.THANHTOAN tt\n            INNER JOIN dbo.DONDATVE d ON d.DonDatVeID = tt.DonDatVeID\n        WHERE\n            tt.ThanhToanID = @ThanhToanID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION PaymentCreateAttempt;\n        END;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Payment_UpdateResult","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/014_showtime_lifecycle.sql:293 (dbo.sp_Payment_UpdateResult)\nCREATE   PROCEDURE dbo.sp_Payment_UpdateResult\n    @NguoiDungID INT,\n    @ThanhToanID INT,\n    @TrangThaiThanhToan NVARCHAR(50),\n    @MaGiaoDichNgoai VARCHAR(100) = NULL,\n    @GhiChu NVARCHAR(255) = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''KHACH_HANG'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''THANH_TOAN'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @TrangThaiThanhToan NOT IN (N''Thành công'', N''Thất bại'')\n            THROW 50114, N''Kết quả thanh toán phải là Thành công hoặc Thất bại.'', 1;\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION PaymentUpdateResult;\n        DECLARE @UserID INT,\n            @SuatID INT,\n            @LockedUser INT,\n            @ShowStatus NVARCHAR(50),\n            @Starts DATETIME2,\n            @DonID INT,\n            @Amount DECIMAL(18, 2),\n            @CurrentPayment NVARCHAR(50),\n            @OrderStatus NVARCHAR(50),\n            @Hold DATETIME2,\n            @Now DATETIME2;\n        SELECT\n            @UserID = d.NguoiDungID,\n            @SuatID = d.SuatChieuID\n        FROM\n            dbo.THANHTOAN t\n            INNER JOIN dbo.DONDATVE d ON d.DonDatVeID = t.DonDatVeID\n        WHERE\n            t.ThanhToanID = @ThanhToanID;\n        IF @UserID IS NULL\n            THROW 50032, N''Giao dịch thanh toán không tồn tại.'', 1;\n        IF @UserID <> @NguoiDungID\n            THROW 50033, N''Đơn đặt vé không tồn tại.'', 1;\n        SELECT\n            @LockedUser = NguoiDungID\n        FROM\n            dbo.NGUOIDUNG\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            NguoiDungID = @UserID;\n        SELECT\n            @ShowStatus = TrangThai,\n            @Starts = ThoiGianBatDau\n        FROM\n            dbo.SUATCHIEU\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            SuatChieuID = @SuatID;\n        -- STRICT 3NF: Tái dựng @Amount từ d.TongTienVe + d.TongTienDoAn - d.TienGiamGia thay vì t.SoTien\n        SELECT\n            @DonID = t.DonDatVeID,\n            @Amount = CASE WHEN d.TongTienVe + d.TongTienDoAn - d.TienGiamGia < 0 THEN 0 ELSE d.TongTienVe + d.TongTienDoAn - d.TienGiamGia END,\n            @CurrentPayment = t.TrangThai,\n            @OrderStatus = d.TrangThai,\n            @Hold = d.HanGiuCho\n        FROM\n            dbo.THANHTOAN t\n        WITH\n            (UPDLOCK, HOLDLOCK)\n            INNER JOIN dbo.DONDATVE d\n        WITH\n            (UPDLOCK, HOLDLOCK) ON d.DonDatVeID = t.DonDatVeID\n        WHERE\n            t.ThanhToanID = @ThanhToanID;\n        IF @CurrentPayment = @TrangThaiThanhToan\n        BEGIN\n            IF @OwnTran = 1\n                -- Chốt các thay đổi của transaction.\n                COMMIT TRANSACTION;\n            SELECT\n                d.DonDatVeID,\n                d.TrangThai AS TrangThaiDon,\n                t.ThanhToanID,\n                t.MaGiaoDich,\n                t.TrangThai AS TrangThaiThanhToan,\n                t.NgayThanhToan\n            FROM\n                dbo.DONDATVE d\n                JOIN dbo.THANHTOAN t ON t.DonDatVeID = d.DonDatVeID\n            WHERE\n                t.ThanhToanID = @ThanhToanID;\n            RETURN;\n        END\n        IF @CurrentPayment <> N''Đang xử lý''\n            THROW 50115, N''Giao dịch đã có kết quả cuối cùng, không thể đổi.'', 1;\n        SET\n            @Now = dbo.fn_BayGio();\n        -- A lock wait must never extend the hold deadline.\n        IF @OrderStatus = N''Hết hạn''\n            OR (\n            @OrderStatus = N''Chờ thanh toán''\n            AND (\n                @Hold IS NULL\n                OR @Hold <= @Now\n            )\n        )\n        BEGIN\n            EXEC dbo.sp_Order_ExpirePending @SuatChieuID = @SuatID,\n                @TraVeKetQua = 0;\n            IF @OwnTran = 1\n                -- Chốt các thay đổi của transaction.\n                COMMIT TRANSACTION;\n            THROW 50111, N''Đơn đã hết thời gian giữ ghế. Vui lòng đặt vé lại.'', 1;\n        END;\n        IF @TrangThaiThanhToan = N''Thành công''\n        BEGIN\n            IF @OrderStatus <> N''Chờ thanh toán''\n                THROW 50113, N''Đơn hàng không còn ở trạng thái có thể thanh toán.'', 1;\n            IF @ShowStatus <> N''Mở bán''\n                OR @Starts <= @Now\n                THROW 50121, N''Suất chiếu không còn hợp lệ để thanh toán.'', 1;\n            -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n            UPDATE dbo.THANHTOAN\n            SET\n                TrangThai = N''Thành công'',\n                NgayThanhToan = @Now,\n                MaGiaoDich = ISNULL(@MaGiaoDichNgoai, MaGiaoDich),\n                GhiChu = @GhiChu\n            WHERE\n                ThanhToanID = @ThanhToanID;\n            -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n            UPDATE dbo.DONDATVE\n            SET\n                TrangThai = N''Đã thanh toán'',\n                HanGiuCho = NULL\n            WHERE\n                DonDatVeID = @DonID;\n            DECLARE @Points INT = CAST(@Amount / 1000 AS INT);\n            IF @Points > 0\n                -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n                UPDATE dbo.HOSOKHACHHANG\n                SET\n                    DiemTichLuy = DiemTichLuy + @Points\n                WHERE\n                    NguoiDungID = @UserID;\n        END\n        ELSE\n        BEGIN\n            -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n            UPDATE dbo.THANHTOAN\n            SET\n                TrangThai = N''Thất bại'',\n                NgayThanhToan = NULL,\n                MaGiaoDich = ISNULL(@MaGiaoDichNgoai, MaGiaoDich),\n                GhiChu = @GhiChu\n            WHERE\n                ThanhToanID = @ThanhToanID;\n        END\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        SELECT\n            d.DonDatVeID,\n            d.TrangThai AS TrangThaiDon,\n            d.HanGiuCho,\n            t.ThanhToanID,\n            t.MaGiaoDich,\n            t.TrangThai AS TrangThaiThanhToan,\n            t.NgayThanhToan\n        FROM\n            dbo.DONDATVE d\n            JOIN dbo.THANHTOAN t ON t.DonDatVeID = d.DonDatVeID\n        WHERE\n            t.ThanhToanID = @ThanhToanID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION PaymentUpdateResult;\n        END;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Product_ListActive","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Product_ListActive\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT\n        SanPhamID,\n        TenSanPham,\n        LoaiSanPham,\n        Gia,\n        MoTa,\n        HinhAnh,\n        TrangThai\n    FROM\n        dbo.SANPHAM\n    WHERE\n        TrangThai = N''Đang bán''\n    ORDER BY\n        LoaiSanPham,\n        Gia;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Promotion_Validate","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/012_booking_limits_and_pricing.sql:151 (dbo.sp_Promotion_Validate)\nCREATE   PROCEDURE dbo.sp_Promotion_Validate\n    (\n    @NguoiDungID INT,\n    @MaCode VARCHAR(50),\n    @TongTienDon DECIMAL(18, 2),\n    @KhuyenMaiID INT OUTPUT,\n    @LoaiGiamGia NVARCHAR(20) OUTPUT,\n    @GiaTriGiam DECIMAL(18, 2) OUTPUT,\n    @TienGiam DECIMAL(18, 2) OUTPUT,\n    @IsValid BIT OUTPUT,\n    @Message NVARCHAR(255) OUTPUT\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- PREVIEW ONLY for HTTP callers: no writes, quota reservation or retained locks.\n    -- Booking calls this after taking its own promotion UPDLOCK/HOLDLOCK, so the\n    -- same validation/formula becomes authoritative inside the booking transaction.\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''KHACH_HANG'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''DAT_VE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SET\n        @IsValid = 0;\n    SET\n        @TienGiam = 0;\n    SET\n        @KhuyenMaiID = NULL;\n    SET\n        @LoaiGiamGia = NULL;\n    SET\n        @GiaTriGiam = NULL;\n    SET\n        @Message = NULL;\n    DECLARE @DonHangToiThieu DECIMAL(18, 2);\n    DECLARE @GiamToiDa DECIMAL(18, 2);\n    DECLARE @NgayBatDau DATETIME2;\n    DECLARE @NgayKetThuc DATETIME2;\n    DECLARE @SoLuong INT;\n    DECLARE @SoLuongDaDung INT;\n    DECLARE @TrangThai NVARCHAR(50);\n    SELECT\n        @KhuyenMaiID = KhuyenMaiID,\n        @LoaiGiamGia = LoaiGiamGia,\n        @GiaTriGiam = GiaTriGiam,\n        @DonHangToiThieu = DonHangToiThieu,\n        @GiamToiDa = GiamToiDa,\n        @NgayBatDau = NgayBatDau,\n        @NgayKetThuc = NgayKetThuc,\n        @SoLuong = SoLuong,\n        @SoLuongDaDung = SoLuongDaDung,\n        @TrangThai = TrangThai\n    FROM\n        dbo.KHUYENMAI\n    WHERE\n        MaCode = @MaCode;\n    IF @KhuyenMaiID IS NULL\n    BEGIN\n        SET\n            @Message = N''Mã khuyến mãi không tồn tại.'';\n        RETURN;\n    END\n    IF @TrangThai <> N''Hoạt động''\n    BEGIN\n        SET\n            @Message = N''Mã khuyến mãi không còn hoạt động.'';\n        RETURN;\n    END\n    -- Capture DB time AFTER the read (and any lock wait), at the stored precision.\n    DECLARE @Now DATETIME2(7) = dbo.fn_BayGio();\n    IF @Now < @NgayBatDau\n        OR @Now > @NgayKetThuc\n    BEGIN\n        SET\n            @Message = N''Mã khuyến mãi chưa tới ngày áp dụng hoặc đã hết hạn.'';\n        RETURN;\n    END\n    -- Re-check existing CHECK semantics too; no new type, scope or formula.\n    IF @LoaiGiamGia NOT IN (N''Phần trăm'', N''PERCENT'', N''Số tiền'', N''FIXED'')\n        OR @GiaTriGiam <= 0\n        OR (\n        @LoaiGiamGia IN (N''Phần trăm'', N''PERCENT'')\n        AND @GiaTriGiam > 99\n    )\n        OR @DonHangToiThieu < 0\n        OR @GiamToiDa < 0\n        OR @SoLuong < 0\n        OR @SoLuongDaDung < 0\n        OR @NgayKetThuc < @NgayBatDau\n    BEGIN\n        SET\n            @Message = N''Điều kiện khuyến mãi không hợp lệ.'';\n        RETURN;\n    END\n    IF @SoLuongDaDung >= @SoLuong\n    BEGIN\n        SET\n            @Message = N''Mã khuyến mãi đã hết lượt sử dụng.'';\n        RETURN;\n    END\n    IF @TongTienDon < @DonHangToiThieu\n    BEGIN\n        SET\n            @Message = N''Đơn hàng chưa đạt giá trị tối thiểu '' + FORMAT(@DonHangToiThieu, ''N0'') + '' đ để áp dụng mã này.'';\n        RETURN;\n    END\n    -- Tính tiền giảm\n    IF @LoaiGiamGia IN (N''Phần trăm'', N''PERCENT'')\n    BEGIN\n        SET\n            @TienGiam = (@TongTienDon * @GiaTriGiam) / 100.0;\n        IF @GiamToiDa IS NOT NULL\n            AND @TienGiam > @GiamToiDa\n            SET\n                @TienGiam = @GiamToiDa;\n    END\n    ELSE\n    BEGIN\n        SET\n            @TienGiam = @GiaTriGiam;\n    END\n    -- Mọi loại khuyến mãi: mức giảm tối đa 99% tổng tạm tính (cắt bớt, không làm tròn lên) để tổng đơn luôn > 0\n    DECLARE @TranGiam DECIMAL(18, 2) = ROUND(@TongTienDon * dbo.fn_GioiHanGiamGiaPhanTram() / 100.0, 2, 1);\n    IF @TienGiam > @TranGiam\n        SET\n            @TienGiam = @TranGiam;\n    SET\n        @IsValid = 1;\n    SET\n        @Message = N''Áp dụng mã khuyến mãi thành công.'';\n    SELECT\n        @IsValid AS IsValid,\n        @KhuyenMaiID AS KhuyenMaiID,\n        @MaCode AS MaCode,\n        @LoaiGiamGia AS LoaiGiamGia,\n        @GiaTriGiam AS GiaTriGiam,\n        @TienGiam AS TienGiam,\n        @Message AS [Message];\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_PhanCongQuanLyRap","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_PhanCongQuanLyRap\n    (\n    @ActorID INT,\n    @NguoiDungID INT,\n    @RapID INT,\n    @NgayBatDau DATE,\n    @NgayKetThuc DATE = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    EXEC dbo.sp_Admin_Assignment_Create @ActorID = @ActorID,\n        @NguoiDungID = @NguoiDungID,\n        @RapID = @RapID,\n        @NgayBatDau = @NgayBatDau,\n        @NgayKetThuc = @NgayKetThuc;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_RBAC_GetPermissionsByUser","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_RBAC_GetPermissionsByUser\n    (@NguoiDungID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT DISTINCT\n        q.QuyenID,\n        q.MaQuyen,\n        q.TenQuyen,\n        q.MoTa\n    FROM\n        dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO_QUYEN vq ON nd.VaiTroID = vq.VaiTroID\n        INNER JOIN dbo.QUYEN q ON vq.QuyenID = q.QuyenID\n    WHERE\n        nd.NguoiDungID = @NguoiDungID\n        AND nd.TrangThai = N''Hoạt động'';\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Review_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/customer/customer_procedures.sql:1214 (dbo.sp_Review_Create)\nCREATE   PROCEDURE dbo.sp_Review_Create\n    (\n    @NguoiDungID INT,\n    @PhimID INT,\n    @SoSao INT,\n    @NoiDung NVARCHAR(1000) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''KHACH_HANG'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''DANH_GIA'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Kiểm tra đã đánh giá chưa\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.DANHGIAPHIM\n        WHERE\n            PhimID = @PhimID\n            AND NguoiDungID = @NguoiDungID\n    )\n    BEGIN\n        ;\n        THROW 50040, N''Bạn đã đánh giá phim này rồi.'', 1;\n    END\n    -- Chèn bản ghi đánh giá (Trigger TRG_DanhGia_KiemTraDaXemPhim sẽ tự kiểm tra đã xem phim chưa)\n    INSERT INTO\n        dbo.DANHGIAPHIM(PhimID, NguoiDungID, SoSao, NoiDung, NgayDanhGia)\n    VALUES\n        (@PhimID, @NguoiDungID, @SoSao, @NoiDung, dbo.fn_BayGio());\n    SELECT\n        DanhGiaID,\n        PhimID,\n        NguoiDungID,\n        SoSao,\n        NoiDung,\n        NgayDanhGia\n    FROM\n        dbo.DANHGIAPHIM\n    WHERE\n        DanhGiaID = SCOPE_IDENTITY();\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Review_ListByMovie","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Review_ListByMovie\n    (@PhimID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT\n        dg.DanhGiaID,\n        dg.PhimID,\n        dg.NguoiDungID,\n        nd.HoTen AS NguoiDanhGia,\n        dg.SoSao,\n        dg.NoiDung,\n        dg.NgayDanhGia\n    FROM\n        dbo.DANHGIAPHIM dg\n        INNER JOIN dbo.NGUOIDUNG nd ON dg.NguoiDungID = nd.NguoiDungID\n    WHERE\n        dg.PhimID = @PhimID\n    ORDER BY\n        dg.NgayDanhGia DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Seat_ListByShowtime","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Seat_ListByShowtime\n    (@SuatChieuID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.SUATCHIEU\n        WHERE\n            SuatChieuID = @SuatChieuID\n    )\n        THROW 50021, N''Suất chiếu không tồn tại.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.vw_LichChieuChiTiet\n        WHERE\n            SuatChieuID = @SuatChieuID\n            AND IsBookable = 1\n    )\n        THROW 50022, N''Suất chiếu không còn đủ điều kiện đặt vé.'', 1;\n    SELECT\n        GheID,\n        PhongID,\n        HangGhe,\n        SoGhe,\n        TenGhe,\n        LoaiGhe,\n        GiaVe,\n        TrangThaiGhe\n    FROM\n        dbo.fn_DanhSachGheSuatChieu(@SuatChieuID)\n    ORDER BY\n        HangGhe,\n        SoGhe;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Showtime_CancelCascade","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/014_showtime_lifecycle.sql:36 (dbo.sp_Showtime_CancelCascade)\nCREATE   PROCEDURE dbo.sp_Showtime_CancelCascade\n    @SuatChieuID INT,\n    @NguoiDungID INT,\n    @LyDo NVARCHAR(255) = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SET XACT_ABORT ON;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    DECLARE @Status NVARCHAR(50),\n        @StartsAt DATETIME2,\n        @RapID INT,\n        @PhongID INT,\n        @Now DATETIME2;\n    DECLARE @Dummy INT,\n        @Cancelled INT = 0;\n    DECLARE @Orders\n    TABLE (\n        DonDatVeID INT PRIMARY KEY,\n        NguoiDungID INT,\n        KhuyenMaiID INT NULL,\n        TrangThai NVARCHAR(50)\n    );\n    DECLARE @Credits\n    TABLE (DonDatVeID INT, DiemBoiThuong INT);\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION ShowtimeCancelCascade;\n        -- Discovery only; canonical writers never move a showtime to another room.\n        SELECT\n            @PhongID = PhongID\n        FROM\n            dbo.SUATCHIEU\n        WHERE\n            SuatChieuID = @SuatChieuID;\n        -- Customer-first locking matches sp_Booking_Create and payment procedures.\n        -- The serializable scan also prevents a new customer row appearing mid-cancel.\n        SELECT\n            @Dummy = MAX(NguoiDungID)\n        FROM\n            dbo.NGUOIDUNG\n        WITH\n            (UPDLOCK, HOLDLOCK);\n        -- R3B: current account, actor eligibility, then every required permission.\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.NGUOIDUNG\n            WHERE\n                NguoiDungID = @NguoiDungID\n                AND TrangThai = N''Hoạt động''\n        )\n            THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.NGUOIDUNG nd\n                INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n            WHERE\n                nd.NguoiDungID = @NguoiDungID\n                AND vt.MaVaiTro IN (''ADMIN'', ''QUAN_LY_RAP'')\n        )\n            THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n        -- Kiểm tra quyền chức năng trước khi thao tác.\n        IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_SUAT_CHIEU'') = 0\n            THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n        -- Keep existing customer coordination; schedule resources always lock parent first.\n        SELECT\n            @RapID = RapID\n        FROM\n            dbo.PHONGCHIEU\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            PhongID = @PhongID;\n        IF @RapID IS NULL\n            THROW 50116, N''Suất chiếu không tồn tại.'', 1;\n        SELECT\n            @Status = TrangThai,\n            @StartsAt = ThoiGianBatDau\n        FROM\n            dbo.SUATCHIEU\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            SuatChieuID = @SuatChieuID\n            AND PhongID = @PhongID;\n        IF @Status IS NULL\n            THROW 50116, N''Suất chiếu không tồn tại.'', 1;\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.NGUOIDUNG nd\n                JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n            WHERE\n                nd.NguoiDungID = @NguoiDungID\n                AND vt.MaVaiTro = ''QUAN_LY_RAP''\n        )\n            AND dbo.fn_KiemTraQuanLyRapScope(@NguoiDungID, @RapID) = 0\n            THROW 50050, N''Lỗi phạm vi [BR08]: Bạn không có quyền thao tác trên rạp này.'', 1;\n        SET\n            @Now = dbo.fn_BayGio();\n        IF @Status = N''Đã hủy''\n        BEGIN\n            IF @OwnTran = 1\n                -- Chốt các thay đổi của transaction.\n                COMMIT TRANSACTION;\n            SELECT\n                N''Suất chiếu đã được hủy.'' AS [Message],\n                0 AS SoDonDaHuy;\n            RETURN;\n        END;\n        IF @Status = N''Hoàn thành''\n            OR @StartsAt <= @Now\n            THROW 50119, N''Không thể hủy suất chiếu đã bắt đầu hoặc đã bị hủy.'', 1;\n        -- The customer/showtime locks serialize booking, payment and concurrent cancellation.\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.DONDATVE\n            WITH\n                (UPDLOCK, HOLDLOCK)\n            WHERE\n                SuatChieuID = @SuatChieuID\n                AND TrangThai = N''Chờ thanh toán''\n                AND HanGiuCho > @Now\n        )\n            THROW 50118, N''Không thể hủy suất chiếu vì còn đơn giữ ghế/chờ thanh toán còn hiệu lực.'', 1;\n        EXEC dbo.sp_Order_ExpirePending @SuatChieuID = @SuatChieuID,\n            @TraVeKetQua = 0;\n        INSERT\n            @Orders(DonDatVeID, NguoiDungID, KhuyenMaiID, TrangThai)\n        SELECT\n            d.DonDatVeID,\n            d.NguoiDungID,\n            d.KhuyenMaiID,\n            d.TrangThai\n        FROM\n            dbo.DONDATVE d\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            d.SuatChieuID = @SuatChieuID\n            AND d.TrangThai = N''Đã thanh toán'';\n        -- Release only promo uses still counted (unexpired holds and paid orders).\n        UPDATE km\n        SET\n            SoLuongDaDung = CASE\n                WHEN km.SoLuongDaDung >= x.SoLan THEN km.SoLuongDaDung - x.SoLan\n                ELSE 0\n            END\n        FROM\n            dbo.KHUYENMAI km\n            INNER JOIN (\n                SELECT\n                    KhuyenMaiID,\n                    COUNT(*) AS SoLan\n                FROM\n                    @Orders\n                WHERE\n                    KhuyenMaiID IS NOT NULL\n                    AND TrangThai IN (N''Chờ thanh toán'', N''Đã thanh toán'')\n                GROUP BY\n                    KhuyenMaiID\n            ) x ON x.KhuyenMaiID = km.KhuyenMaiID;\n        -- No payment writes and no reversal of previously earned loyalty points.\n        -- Only the actual event points are persisted. Order snapshots stay in DONDATVE.\n        DECLARE @DonID INT,\n            @TongTienVe DECIMAL(18, 2),\n            @TongTienDoAn DECIMAL(18, 2),\n            @TienGiamGia DECIMAL(18, 2),\n            @DiemSuDung INT,\n            @TienGiamKhuyenMai DECIMAL(18, 2),\n            @TongTruocGiam DECIMAL(19, 2),\n            @GiamChoVe DECIMAL(38, 6),\n            @TienVeThucTra DECIMAL(38, 6),\n            @DiemBoiThuong INT;\n        DECLARE CompensationOrders CURSOR LOCAL FAST_FORWARD FOR\n        SELECT\n            d.DonDatVeID,\n            d.TongTienVe,\n            d.TongTienDoAn,\n            d.TienGiamGia,\n            d.DiemSuDung\n        FROM\n            dbo.DONDATVE d\n            INNER JOIN @Orders o ON o.DonDatVeID = d.DonDatVeID\n        WHERE\n            EXISTS (\n                SELECT\n                    1\n                FROM\n                    dbo.THANHTOAN t\n                WHERE\n                    t.DonDatVeID = d.DonDatVeID\n                    AND t.TrangThai = N''Thành công''\n            )\n            AND NOT EXISTS (\n                SELECT\n                    1\n                FROM\n                    dbo.BOITHUONG_HUYSUAT b\n                WITH\n                    (UPDLOCK, HOLDLOCK)\n                WHERE\n                    b.DonDatVeID = d.DonDatVeID\n            );\n        OPEN CompensationOrders;\n        FETCH NEXT\n        FROM\n            CompensationOrders\n        INTO\n            @DonID,\n            @TongTienVe,\n            @TongTienDoAn,\n            @TienGiamGia,\n            @DiemSuDung;\n        WHILE @@FETCH_STATUS = 0\n        BEGIN\n            SET\n                @TongTruocGiam = @TongTienVe + @TongTienDoAn;\n            -- TienGiamGia is now the total discount. Compensation keeps the\n            -- pre-existing rule: only the promotion portion affects ticket compensation.\n            SET\n                @TienGiamKhuyenMai = CASE\n                    WHEN @TienGiamGia - ISNULL(@DiemSuDung, 0) * 1000 < 0 THEN 0\n                    ELSE @TienGiamGia - ISNULL(@DiemSuDung, 0) * 1000\n                END;\n            SET\n                @GiamChoVe = ISNULL(@TienGiamKhuyenMai * @TongTienVe / NULLIF(@TongTruocGiam, 0), 0);\n            SET\n                @TienVeThucTra = CASE\n                    WHEN @TongTruocGiam = 0\n                    OR @GiamChoVe >= @TongTienVe THEN 0\n                    ELSE @TongTienVe - @GiamChoVe\n                END;\n            -- Preserve R2''s exact final FLOOR, including sub-point division boundaries.\n            -- The helper works from DECIMAL cents, so intermediate display precision cannot round points up.\n            SELECT\n                @DiemBoiThuong = CONVERT(INT, c.DiemCong)\n            FROM\n                dbo.fn_TinhBoiThuongVe(@TongTienVe, @TongTienDoAn, @TienGiamKhuyenMai) c;\n            INSERT\n                dbo.BOITHUONG_HUYSUAT(DonDatVeID, DiemBoiThuong, NgayBoiThuong, GhiChu) OUTPUT inserted.DonDatVeID,\n                inserted.DiemBoiThuong\n            INTO\n                @Credits\n            VALUES\n                (\n                    @DonID,\n                    @DiemBoiThuong,\n                    @Now,\n                    CASE\n                        WHEN @NguoiDungID IS NULL THEN NULL\n                        ELSE CONCAT(N''Người thực hiện ID: '', @NguoiDungID)\n                    END\n                );\n            FETCH NEXT\n            FROM\n                CompensationOrders\n            INTO\n                @DonID,\n                @TongTienVe,\n                @TongTienDoAn,\n            @TienGiamGia,\n            @DiemSuDung;\n        END;\n        CLOSE CompensationOrders;\n        DEALLOCATE CompensationOrders;\n        INSERT\n            dbo.HOSOKHACHHANG(NguoiDungID, DiemTichLuy)\n        SELECT DISTINCT\n            o.NguoiDungID,\n            0\n        FROM\n            @Credits c\n            INNER JOIN @Orders o ON o.DonDatVeID = c.DonDatVeID\n        WHERE\n            NOT EXISTS (\n                SELECT\n                    1\n                FROM\n                    dbo.HOSOKHACHHANG h\n                WITH\n                    (UPDLOCK, HOLDLOCK)\n                WHERE\n                    h.NguoiDungID = o.NguoiDungID\n            );\n        UPDATE h\n        SET\n            DiemTichLuy = h.DiemTichLuy + c.Points\n        FROM\n            dbo.HOSOKHACHHANG h\n            INNER JOIN (\n                SELECT\n                    o.NguoiDungID,\n                    SUM(CONVERT(BIGINT, c.DiemBoiThuong)) AS Points\n                FROM\n                    @Credits c\n                    INNER JOIN @Orders o ON o.DonDatVeID = c.DonDatVeID\n                GROUP BY\n                    o.NguoiDungID\n            ) c ON c.NguoiDungID = h.NguoiDungID;\n        UPDATE cv\n        SET\n            TrangThai = N''Đã hủy''\n        FROM\n            dbo.CHITIETVE cv\n            INNER JOIN @Orders o ON o.DonDatVeID = cv.DonDatVeID\n        WHERE\n            cv.TrangThai <> N''Đã hủy'';\n        UPDATE d\n        SET\n            TrangThai = N''Đã hủy'',\n            HanGiuCho = NULL,\n            LyDoHuy = @LyDo,\n            ThongBaoHuy = N''Suất chiếu đã bị hủy. Điểm bồi thường phần vé đã được cộng vào tài khoản (1.000 VNĐ = 1 điểm).''\n        FROM\n            dbo.DONDATVE d\n            INNER JOIN @Orders o ON o.DonDatVeID = d.DonDatVeID;\n        SET\n            @Cancelled = @@ROWCOUNT;\n        -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n        UPDATE dbo.SUATCHIEU\n        SET\n            TrangThai = N''Đã hủy''\n        WHERE\n            SuatChieuID = @SuatChieuID;\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        SELECT\n            CASE\n                WHEN @NguoiDungID IS NULL THEN N''Đã hủy suất chiếu.''\n                ELSE N''Hủy suất chiếu thành công.''\n            END AS [Message],\n            @Cancelled AS SoDonDaHuy;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF CURSOR_STATUS(''local'', ''CompensationOrders'') >= 0\n        CLOSE CompensationOrders;\n        IF CURSOR_STATUS(''local'', ''CompensationOrders'') >= - 1\n        DEALLOCATE CompensationOrders;\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION;\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION ShowtimeCancelCascade;\n        END\n        SET XACT_ABORT OFF;\n        ;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Showtime_GetDetail","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Showtime_GetDetail\n    (@SuatChieuID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT\n        SuatChieuID,\n        PhimID,\n        TenPhim,\n        PosterURL,\n        ThoiLuong,\n        DoTuoi,\n        RapID,\n        TenRap,\n        DiaChiRap,\n        ThanhPho,\n        PhongID,\n        TenPhong,\n        LoaiPhong,\n        ThoiGianBatDau,\n        ThoiGianKetThuc,\n        NgayChieu,\n        GioBatDau,\n        GioKetThuc,\n        DinhDang,\n        GiaVeCoBan,\n        TrangThaiSuatChieu,\n        TongSoGhe,\n        SoGheDaDat,\n        (TongSoGhe - SoGheDaDat) AS SoGheConLai\n    FROM\n        dbo.vw_LichChieuChiTiet\n    WHERE\n        SuatChieuID = @SuatChieuID\n        AND IsBookable = 1;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Showtime_ListByMovie","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: procedures/customer/customer_procedures.sql:164 (dbo.sp_Showtime_ListByMovie)\nCREATE   PROCEDURE dbo.sp_Showtime_ListByMovie\n    (@PhimID INT, @RapID INT = NULL, @NgayChieu DATE = NULL)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT\n        SuatChieuID,\n        PhimID,\n        TenPhim,\n        PosterURL,\n        ThoiLuong,\n        DoTuoi,\n        RapID,\n        TenRap,\n        DiaChiRap,\n        ThanhPho,\n        PhongID,\n        TenPhong,\n        LoaiPhong,\n        ThoiGianBatDau,\n        ThoiGianKetThuc,\n        NgayChieu,\n        GioBatDau,\n        GioKetThuc,\n        DinhDang,\n        GiaVeCoBan,\n        TrangThaiSuatChieu,\n        TongSoGhe,\n        SoGheDaDat,\n        (TongSoGhe - SoGheDaDat) AS SoGheConLai\n    FROM\n        dbo.vw_LichChieuChiTiet\n    WHERE\n        PhimID = @PhimID\n        AND (\n            @RapID IS NULL\n            OR RapID = @RapID\n        )\n        AND (\n            @NgayChieu IS NULL\n            OR NgayChieu = @NgayChieu\n        )\n        AND IsBookable = 1\n    ORDER BY\n        ThoiGianBatDau ASC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Showtime_ValidateTimes","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Showtime_ValidateTimes\n    @PhimID INT,\n    @ThoiGianBatDau DATETIME2,\n    @ThoiGianKetThuc DATETIME2,\n    @PhongID INT = NULL,\n    @SuatChieuID INT = NULL,\n    @TrangThai NVARCHAR(50) = N''Mở bán''\nAS\nBEGIN\n    SET NOCOUNT ON;\n    DECLARE @ThoiLuong INT = (\n        SELECT\n            ThoiLuong\n        FROM\n            dbo.PHIM\n        WHERE\n            PhimID = @PhimID\n    );\n    DECLARE @Span DECIMAL(20, 7) = DATEDIFF_BIG(SECOND, @ThoiGianBatDau, @ThoiGianKetThuc) + (\n        CONVERT(DECIMAL(20, 7), DATEPART(NANOSECOND, @ThoiGianKetThuc)) - DATEPART(NANOSECOND, @ThoiGianBatDau)\n    ) / 1000000000;\n    -- Unknown movie retains the existing FK/resource handling; no unrelated validation change.\n    IF @ThoiGianBatDau IS NULL\n        OR @ThoiGianKetThuc IS NULL\n        OR @ThoiGianBatDau < dbo.fn_BayGio()\n        OR @ThoiGianKetThuc <= @ThoiGianBatDau\n        OR @Span > 28800\n        OR (\n        @ThoiLuong IS NOT NULL\n        AND (\n            @Span < CONVERT(BIGINT, @ThoiLuong) * 60\n            OR @Span > (CONVERT(BIGINT, @ThoiLuong) + 120) * 60\n        )\n    )\n        THROW 50216, N''Thời gian suất phải từ hiện tại, dài từ thời lượng phim đến thời lượng phim +120 phút và tối đa 8 giờ.'', 1;\n    -- Writers hold the room UPDLOCK/HOLDLOCK in their transaction before calling.\n    -- Current committed read, including when the caller uses RCSI; no broad empty-range locks.\n    IF @PhongID IS NOT NULL\n        AND @TrangThai <> N''Đã hủy''\n        AND EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.SUATCHIEU\n        WITH\n            (READCOMMITTEDLOCK)\n        WHERE\n            PhongID = @PhongID\n            AND (\n                @SuatChieuID IS NULL\n                OR SuatChieuID <> @SuatChieuID\n            )\n            AND TrangThai <> N''Đã hủy''\n            AND ThoiGianBatDau < @ThoiGianKetThuc\n            AND ThoiGianKetThuc > @ThoiGianBatDau\n    )\n        THROW 50001, N''Lỗi ràng buộc [BR01]: Phòng chiếu đã có suất chiếu khác trong khoảng thời gian này.'', 1;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_StaffBooking_Authorize","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_StaffBooking_Authorize\n    @ActorID int,\n    @PortalRole varchar(50),\n    @RapID int = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WITH\n            (HOLDLOCK)\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản nhân viên không còn hoạt động.'', 1;\n    IF @PortalRole IS NULL\n        OR @PortalRole NOT IN (''ADMIN'', ''QUAN_LY_RAP'')\n        OR NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG n\n            JOIN dbo.VAITRO r ON r.VaiTroID = n.VaiTroID\n        WHERE\n            n.NguoiDungID = @ActorID\n            AND r.MaVaiTro = @PortalRole\n    )\n        THROW 50301, N''Vai trò không được phép quản lý đặt vé tại portal này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''DAT_VE'') = 0\n        THROW 50302, N''Không có quyền quản lý đặt vé.'', 1;\n    IF @PortalRole = ''QUAN_LY_RAP''\n        AND @RapID IS NOT NULL\n    BEGIN\n        -- Assignment writers take TABLOCKX: retain scope through the caller''s transaction.\n        DECLARE @Assignments bigint;\n        SELECT\n            @Assignments = COUNT_BIG(*)\n        FROM\n            dbo.PHANCONG_RAP\n        WITH\n            (HOLDLOCK)\n        WHERE\n            NguoiDungID = @ActorID\n            AND RapID = @RapID;\n        -- Kiểm tra phạm vi rạp còn được phân công.\n        IF dbo.fn_KiemTraQuanLyRapScope(@ActorID, @RapID) = 0\n            THROW 50303, N''Rạp không thuộc phân công còn hiệu lực của Manager.'', 1;\n    END;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_StaffBooking_Cancel","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_StaffBooking_Cancel\n    @ActorID int,\n    @PortalRole varchar(50),\n    @DonDatVeID int\nAS\nBEGIN\n    SET NOCOUNT ON;\n    DECLARE @Own bit = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @Own = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION StaffBookingCancel;\n        EXEC dbo.sp_StaffBooking_Authorize @ActorID,\n            @PortalRole;\n        DECLARE @Customer int,\n            @Show int,\n            @Rap int,\n            @Status nvarchar(50),\n            @Promotion int,\n            @Points int,\n            @Locked int;\n        SELECT\n            @Customer = d.NguoiDungID,\n            @Show = d.SuatChieuID,\n            @Rap = p.RapID\n        FROM\n            dbo.DONDATVE d\n            JOIN dbo.SUATCHIEU s ON s.SuatChieuID = d.SuatChieuID\n            JOIN dbo.PHONGCHIEU p ON p.PhongID = s.PhongID\n        WHERE\n            d.DonDatVeID = @DonDatVeID;\n        IF @Customer IS NULL\n            THROW 50033, N''Đơn đặt vé không tồn tại.'', 1;\n        EXEC dbo.sp_StaffBooking_Authorize @ActorID,\n            @PortalRole,\n            @Rap;\n        -- Match payment lock order: customer -> show -> order -> payment/tickets -> promotion.\n        SELECT\n            @Locked = NguoiDungID\n        FROM\n            dbo.NGUOIDUNG\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            NguoiDungID = @Customer;\n        SELECT\n            @Locked = SuatChieuID\n        FROM\n            dbo.SUATCHIEU\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            SuatChieuID = @Show;\n        SELECT\n            @Status = TrangThai,\n            @Promotion = KhuyenMaiID,\n            @Points = DiemSuDung\n        FROM\n            dbo.DONDATVE\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            DonDatVeID = @DonDatVeID\n            AND NguoiDungID = @Customer\n            AND SuatChieuID = @Show;\n        IF @Status IS NULL\n            OR @Status <> N''Chờ thanh toán''\n            OR EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.CHITIETVE\n            WHERE\n                DonDatVeID = @DonDatVeID\n                AND TrangThai = N''Đã sử dụng''\n        )\n            THROW 50512, N''Chỉ hủy toàn bộ đơn Chờ thanh toán, không có vé đã sử dụng.'', 1;\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.THANHTOAN\n            WITH\n                (UPDLOCK, HOLDLOCK)\n            WHERE\n                DonDatVeID = @DonDatVeID\n                AND TrangThai IN (N''Đang xử lý'', N''Thành công'', N''Đã hoàn tiền'')\n        )\n            THROW 50514, N''Đơn có giao dịch đang xử lý/đã thanh toán; không thể hủy.'', 1;\n        EXEC dbo.sp_StaffBooking_Authorize @ActorID,\n            @PortalRole,\n            @Rap;\n        -- Same logical cancellation as existing sp_Order_Cancel; no physical deletion/refund.\n        UPDATE dbo.DONDATVE\n        SET\n            TrangThai = N''Đã hủy''\n        WHERE\n            DonDatVeID = @DonDatVeID;\n        -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n        UPDATE dbo.CHITIETVE\n        SET\n            TrangThai = N''Đã hủy''\n        WHERE\n            DonDatVeID = @DonDatVeID\n            AND TrangThai <> N''Đã hủy'';\n        -- Điểm đã giữ cho đơn chưa thanh toán được trả lại cho khách (không phải hoàn tiền).\n        IF ISNULL(@Points, 0) > 0\n            UPDATE dbo.HOSOKHACHHANG\n            SET\n                DiemTichLuy = DiemTichLuy + @Points\n            WHERE\n                NguoiDungID = @Customer;\n        IF @Promotion IS NOT NULL\n            -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n            UPDATE dbo.KHUYENMAI\n            SET\n                SoLuongDaDung = CASE\n                    WHEN SoLuongDaDung > 0 THEN SoLuongDaDung - 1\n                    ELSE 0\n                END\n            WHERE\n                KhuyenMaiID = @Promotion;\n        EXEC dbo.sp_StaffBooking_Detail @ActorID,\n            @PortalRole,\n            @DonDatVeID;\n        IF @Own = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @Own = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION StaffBookingCancel;\n        END;\n        THROW;\n    END CATCH;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_StaffBooking_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_StaffBooking_Create\n    @ActorID int,\n    @PortalRole varchar(50),\n    @CustomerID int,\n    @SuatChieuID int,\n    @DanhSachGheId varchar(max),\n    @NewDonDatVeID int OUTPUT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    DECLARE @Own bit = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @Own = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION StaffBookingCreate;\n        DECLARE @Rap int,\n            @Room int;\n        EXEC dbo.sp_StaffBooking_LockShow @ActorID,\n            @PortalRole,\n            @CustomerID,\n            @SuatChieuID,\n            @Rap OUTPUT,\n            @Room OUTPUT;\n        IF @DanhSachGheId IS NULL\n            OR EXISTS (\n            SELECT\n                1\n            FROM\n                STRING_SPLIT(@DanhSachGheId, '','')\n            WHERE\n                TRY_CONVERT(int, value) IS NULL\n                OR TRY_CONVERT(int, value) <= 0\n                OR value LIKE ''%[^0-9]%''\n        )\n            OR (\n            SELECT\n                COUNT(*)\n            FROM\n                STRING_SPLIT(@DanhSachGheId, '','')\n        ) <> (\n            SELECT\n                COUNT(DISTINCT value)\n            FROM\n                STRING_SPLIT(@DanhSachGheId, '','')\n        )\n            THROW 50511, N''Danh sách ghế không hợp lệ hoặc bị lặp.'', 1;\n        -- Delegate unchanged Customer rules, limits, locks, pricing and hold creation.\n        EXEC dbo.sp_Booking_Create @NguoiDungID = @CustomerID,\n            @SuatChieuID = @SuatChieuID,\n            @DanhSachGheId = @DanhSachGheId,\n            @MaKhuyenMai = NULL,\n            @DanhSachDoAnJson = NULL,\n            @NewDonDatVeID = @NewDonDatVeID OUTPUT;\n        EXEC dbo.sp_StaffBooking_Authorize @ActorID,\n            @PortalRole,\n            @Rap;\n        IF @Own = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @Own = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION StaffBookingCreate;\n        END;\n        THROW;\n    END CATCH;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_StaffBooking_Customers","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_StaffBooking_Customers\n    @ActorID int,\n    @PortalRole varchar(50),\n    @Search nvarchar(100)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    EXEC dbo.sp_StaffBooking_Authorize @ActorID,\n        @PortalRole;\n    SET\n        @Search = LTRIM(RTRIM(@Search));\n    IF @Search IS NULL\n        OR LEN(@Search) < 2\n        THROW 50511, N''Nhập ít nhất hai ký tự để tìm khách hàng.'', 1;\n    -- CHARINDEX treats %, _ and [ as literal search input.\n    SELECT\n        TOP(50) n.NguoiDungID,\n        n.HoTen,\n        n.Email,\n        n.SoDienThoai,\n        COUNT(*) OVER() AS TotalMatches\n    FROM\n        dbo.NGUOIDUNG n\n        JOIN dbo.VAITRO r ON r.VaiTroID = n.VaiTroID\n    WHERE\n        r.MaVaiTro = ''KHACH_HANG''\n        AND n.TrangThai = N''Hoạt động''\n        AND (\n            CHARINDEX(@Search, n.HoTen) > 0\n            OR CHARINDEX(@Search, n.Email) > 0\n            OR CHARINDEX(@Search, ISNULL(n.SoDienThoai, '''')) > 0\n        )\n    ORDER BY\n        n.HoTen,\n        n.NguoiDungID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_StaffBooking_Detail","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_StaffBooking_Detail\n    @ActorID int,\n    @PortalRole varchar(50),\n    @DonDatVeID int\nAS\nBEGIN\n    SET NOCOUNT ON;\n    DECLARE @Own bit = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @Own = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION StaffBookingDetail;\n        EXEC dbo.sp_StaffBooking_Authorize @ActorID,\n            @PortalRole;\n        DECLARE @Rap int;\n        SELECT\n            @Rap = p.RapID\n        FROM\n            dbo.DONDATVE d\n            JOIN dbo.SUATCHIEU s ON s.SuatChieuID = d.SuatChieuID\n            JOIN dbo.PHONGCHIEU p ON p.PhongID = s.PhongID\n        WHERE\n            d.DonDatVeID = @DonDatVeID;\n        IF @Rap IS NULL\n            THROW 50033, N''Đơn đặt vé không tồn tại.'', 1;\n        EXEC dbo.sp_StaffBooking_Authorize @ActorID,\n            @PortalRole,\n            @Rap;\n        SELECT\n            v.[DonDatVeID],\n            v.[NguoiDungID],\n            v.[HoTenKhachHang],\n            v.[Email],\n            v.[SoDienThoai],\n            v.[SuatChieuID],\n            v.[PhimID],\n            v.[TenPhim],\n            v.[PosterURL],\n            v.[DoTuoi],\n            v.[ThoiLuong],\n            v.[RapID],\n            v.[TenRap],\n            v.[DiaChiRap],\n            v.[PhongID],\n            v.[TenPhong],\n            v.[LoaiPhong],\n            v.[ThoiGianBatDau],\n            v.[ThoiGianKetThuc],\n            v.[DinhDang],\n            v.[NgayDat],\n            v.[TongTienVe],\n            v.[TongTienDoAn],\n            v.[TienGiamGia],\n            v.[TongTienThanhToan],\n            d.DiemSuDung,\n            v.[TrangThaiDon],\n            v.[HanGiuCho],\n            v.[MaKhuyenMai],\n            v.[MoTaKhuyenMai],\n            v.[DanhSachGhe],\n            v.[DanhSachMaVe],\n            d.LyDoHuy,\n            d.ThongBaoHuy,\n            CONVERT(\n                bit,\n                CASE\n                    WHEN d.TrangThai = N''Chờ thanh toán''\n                    AND d.HanGiuCho > dbo.fn_BayGio()\n                    AND d.KhuyenMaiID IS NULL\n                    AND d.DiemSuDung = 0\n                    AND NOT EXISTS (\n                        SELECT\n                            1\n                        FROM\n                            dbo.CHITIETDOAN\n                        WHERE\n                            DonDatVeID = d.DonDatVeID\n                    )\n                    AND NOT EXISTS (\n                        SELECT\n                            1\n                        FROM\n                            dbo.THANHTOAN\n                        WHERE\n                            DonDatVeID = d.DonDatVeID\n                    )\n                    AND NOT EXISTS (\n                        SELECT\n                            1\n                        FROM\n                            dbo.CHITIETVE\n                        WHERE\n                            DonDatVeID = d.DonDatVeID\n                            AND TrangThai = N''Đã sử dụng''\n                    )\n                    AND EXISTS (\n                        SELECT\n                            1\n                        FROM\n                            dbo.NGUOIDUNG n\n                            JOIN dbo.VAITRO r ON r.VaiTroID = n.VaiTroID\n                        WHERE\n                            n.NguoiDungID = d.NguoiDungID\n                            AND n.TrangThai = N''Hoạt động''\n                            AND r.MaVaiTro = ''KHACH_HANG''\n                    )\n                    AND EXISTS (\n                        SELECT\n                            1\n                        FROM\n                            dbo.vw_LichChieuChiTiet\n                        WHERE\n                            SuatChieuID = d.SuatChieuID\n                            AND IsBookable = 1\n                    ) THEN 1\n                    ELSE 0\n                END\n            ) AS CanEdit,\n            CONVERT(\n                bit,\n                CASE\n                    WHEN d.TrangThai = N''Chờ thanh toán''\n                    AND NOT EXISTS (\n                        SELECT\n                            1\n                        FROM\n                            dbo.THANHTOAN\n                        WHERE\n                            DonDatVeID = d.DonDatVeID\n                            AND TrangThai IN (N''Đang xử lý'', N''Thành công'', N''Đã hoàn tiền'')\n                    )\n                    AND NOT EXISTS (\n                        SELECT\n                            1\n                        FROM\n                            dbo.CHITIETVE\n                        WHERE\n                            DonDatVeID = d.DonDatVeID\n                            AND TrangThai = N''Đã sử dụng''\n                    ) THEN 1\n                    ELSE 0\n                END\n            ) AS CanCancel,\n            (\n                SELECT\n                    COUNT(*)\n                FROM\n                    dbo.CHITIETVE\n                WHERE\n                    DonDatVeID = d.DonDatVeID\n                    AND TrangThai <> N''Đã hủy''\n            ) AS SoLuongVe,\n            b.DiemBoiThuong,\n            b.NgayBoiThuong\n        FROM\n            dbo.vw_ChiTietDonDatVe v\n            JOIN dbo.DONDATVE d ON d.DonDatVeID = v.DonDatVeID\n            LEFT JOIN dbo.BOITHUONG_HUYSUAT b ON b.DonDatVeID = d.DonDatVeID\n        WHERE\n            v.DonDatVeID = @DonDatVeID;\n        SELECT\n            cv.VeID,\n            cv.MaVe,\n            g.GheID,\n            g.HangGhe,\n            g.SoGhe,\n            g.HangGhe + CAST(g.SoGhe AS VARCHAR(10)) AS TenGhe,\n            g.LoaiGhe,\n            cv.GiaVe,\n            cv.TrangThai AS TrangThaiVe\n        FROM\n            dbo.CHITIETVE cv\n            INNER JOIN dbo.GHE g ON g.GheID = cv.GheID\n        WHERE\n            cv.DonDatVeID = @DonDatVeID;\n        SELECT\n            cda.ChiTietDoAnID,\n            sp.SanPhamID,\n            sp.TenSanPham,\n            sp.LoaiSanPham,\n            cda.SoLuong,\n            cda.DonGia,\n            cda.SoLuong * cda.DonGia AS ThanhTien\n        FROM\n            dbo.CHITIETDOAN cda\n            INNER JOIN dbo.SANPHAM sp ON sp.SanPhamID = cda.SanPhamID\n        WHERE\n            cda.DonDatVeID = @DonDatVeID;\n        -- STRICT 3NF: Tái dựng SoTien từ d.TongTienVe + d.TongTienDoAn - d.TienGiamGia\n        SELECT\n            tt.ThanhToanID,\n            tt.PhuongThuc,\n            CASE WHEN d.TongTienVe + d.TongTienDoAn - d.TienGiamGia < 0 THEN 0 ELSE d.TongTienVe + d.TongTienDoAn - d.TienGiamGia END AS SoTien,\n            tt.NgayTao,\n            tt.NgayThanhToan,\n            tt.MaGiaoDich,\n            tt.TrangThai,\n            tt.GhiChu\n        FROM\n            dbo.THANHTOAN tt\n            INNER JOIN dbo.DONDATVE d ON d.DonDatVeID = tt.DonDatVeID\n        WHERE\n            tt.DonDatVeID = @DonDatVeID\n        ORDER BY\n            tt.ThanhToanID;\n        IF @Own = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @Own = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION StaffBookingDetail;\n        END;\n        THROW;\n    END CATCH;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_StaffBooking_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_StaffBooking_List\n    @ActorID int,\n    @PortalRole varchar(50),\n    @Search nvarchar(100) = NULL,\n    @Status nvarchar(50) = NULL,\n    @RapID int = NULL,\n    @Page int = 1,\n    @PageSize int = 20\nAS\nBEGIN\n    SET NOCOUNT ON;\n    EXEC dbo.sp_StaffBooking_Authorize @ActorID,\n        @PortalRole,\n        @RapID;\n    IF @Page < 1\n        OR @Page > 100000\n        OR @PageSize < 1\n        OR @PageSize > 100\n        OR @Page IS NULL\n        OR @PageSize IS NULL\n        THROW 50511, N''Tham số phân trang không hợp lệ.'', 1;\n    SELECT\n        v.DonDatVeID,\n        v.NguoiDungID,\n        v.HoTenKhachHang,\n        v.Email,\n        v.SoDienThoai,\n        v.SuatChieuID,\n        v.TenPhim,\n        v.RapID,\n        v.TenRap,\n        v.TenPhong,\n        v.ThoiGianBatDau,\n        v.NgayDat,\n        v.TongTienThanhToan,\n        v.TrangThaiDon,\n        v.HanGiuCho,\n        v.SoLuongVe,\n        v.TrangThaiThanhToanMoiNhat,\n        (\n            SELECT\n                STRING_AGG(CONCAT(g.HangGhe, g.SoGhe), '', '')\n            FROM\n                dbo.CHITIETVE t\n                JOIN dbo.GHE g ON g.GheID = t.GheID\n            WHERE\n                t.DonDatVeID = v.DonDatVeID\n                AND t.TrangThai <> N''Đã hủy''\n        ) AS DanhSachGhe\n    INTO\n        #Filtered\n    FROM\n        dbo.vw_LichSuDatVe v\n    WHERE\n        (\n            @RapID IS NULL\n            OR v.RapID = @RapID\n        )\n        AND (\n            @Status IS NULL\n            OR v.TrangThaiDon = @Status\n        )\n        AND (\n            @PortalRole = ''ADMIN''\n            OR dbo.fn_KiemTraQuanLyRapScope(@ActorID, v.RapID) = 1\n        )\n        AND (\n            @Search IS NULL\n            OR @Search = ''''\n            OR CHARINDEX(@Search, v.HoTenKhachHang) > 0\n            OR CHARINDEX(@Search, v.Email) > 0\n            OR CHARINDEX(@Search, ISNULL(v.SoDienThoai, '''')) > 0\n            OR CHARINDEX(@Search, v.TenPhim) > 0\n            OR CONVERT(varchar(20), v.DonDatVeID) = @Search\n            OR EXISTS (\n                SELECT\n                    1\n                FROM\n                    dbo.CHITIETVE t\n                WHERE\n                    t.DonDatVeID = v.DonDatVeID\n                    AND CHARINDEX(@Search, t.MaVe) > 0\n            )\n        );\n    SELECT\n        DonDatVeID,\n        NguoiDungID,\n        HoTenKhachHang,\n        Email,\n        SoDienThoai,\n        SuatChieuID,\n        TenPhim,\n        RapID,\n        TenRap,\n        TenPhong,\n        ThoiGianBatDau,\n        NgayDat,\n        TongTienThanhToan,\n        TrangThaiDon,\n        HanGiuCho,\n        SoLuongVe,\n        TrangThaiThanhToanMoiNhat,\n        DanhSachGhe\n    FROM\n        #Filtered\n    ORDER BY\n        NgayDat DESC,\n        DonDatVeID DESC\n    OFFSET\n        (@Page - 1) * @PageSize ROWS\n    FETCH NEXT\n        @PageSize ROWS ONLY;\n    SELECT\n        COUNT(*) AS Total,\n        @Page AS Page,\n        @PageSize AS PageSize\n    FROM\n        #Filtered;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_StaffBooking_LockShow","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Internal transaction helper; identical parent lock order to Customer booking.\nCREATE   PROCEDURE dbo.sp_StaffBooking_LockShow\n    @ActorID int,\n    @PortalRole varchar(50),\n    @CustomerID int,\n    @SuatChieuID int,\n    @RapID int OUTPUT,\n    @PhongID int OUTPUT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    IF @@TRANCOUNT = 0\n        THROW 50516, N''Thao tác đặt vé yêu cầu transaction.'', 1;\n    EXEC dbo.sp_StaffBooking_Authorize @ActorID,\n        @PortalRole;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG n\n        WITH\n            (UPDLOCK, HOLDLOCK)\n            JOIN dbo.VAITRO r ON r.VaiTroID = n.VaiTroID\n        WHERE\n            n.NguoiDungID = @CustomerID\n            AND n.TrangThai = N''Hoạt động''\n            AND r.MaVaiTro = ''KHACH_HANG''\n    )\n        THROW 50510, N''Khách hàng phải tồn tại, đang hoạt động và có vai trò Customer.'', 1;\n    DECLARE @MovieID int,\n        @Locked int;\n    SET\n        @PhongID = NULL;\n    SET\n        @RapID = NULL;\n    SELECT\n        @PhongID = s.PhongID,\n        @MovieID = s.PhimID,\n        @RapID = p.RapID\n    FROM\n        dbo.SUATCHIEU s\n        JOIN dbo.PHONGCHIEU p ON p.PhongID = s.PhongID\n    WHERE\n        s.SuatChieuID = @SuatChieuID;\n    IF @PhongID IS NULL\n        THROW 50021, N''Suất chiếu không tồn tại.'', 1;\n    EXEC dbo.sp_StaffBooking_Authorize @ActorID,\n        @PortalRole,\n        @RapID;\n    SELECT\n        @Locked = PhimID\n    FROM\n        dbo.PHIM\n    WITH\n        (HOLDLOCK)\n    WHERE\n        PhimID = @MovieID;\n    SELECT\n        @Locked = RapID\n    FROM\n        dbo.RAPCHIEUPHIM\n    WITH\n        (HOLDLOCK)\n    WHERE\n        RapID = @RapID;\n    SET\n        @Locked = NULL;\n    SELECT\n        @Locked = PhongID\n    FROM\n        dbo.PHONGCHIEU\n    WITH\n        (UPDLOCK, HOLDLOCK)\n    WHERE\n        PhongID = @PhongID\n        AND RapID = @RapID;\n    IF @Locked IS NULL\n        THROW 50022, N''Phòng chiếu đã thay đổi. Vui lòng tải lại.'', 1;\n    SET\n        @Locked = NULL;\n    SELECT\n        @Locked = SuatChieuID\n    FROM\n        dbo.SUATCHIEU\n    WITH\n        (UPDLOCK, HOLDLOCK)\n    WHERE\n        SuatChieuID = @SuatChieuID\n        AND PhongID = @PhongID\n        AND PhimID = @MovieID;\n    IF @Locked IS NULL\n        OR NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.vw_LichChieuChiTiet\n        WHERE\n            SuatChieuID = @SuatChieuID\n            AND IsBookable = 1\n    )\n        THROW 50022, N''Suất chiếu không còn đủ điều kiện đặt vé.'', 1;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_StaffBooking_Options","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_StaffBooking_Options\n    @ActorID int,\n    @PortalRole varchar(50),\n    @RapID int = NULL,\n    @SuatChieuID int = NULL,\n    @DonDatVeID int = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    EXEC dbo.sp_StaffBooking_Authorize @ActorID,\n        @PortalRole,\n        @RapID;\n    IF @SuatChieuID IS NOT NULL\n    BEGIN\n        DECLARE @ShowRap int;\n        SELECT\n            @ShowRap = p.RapID\n        FROM\n            dbo.SUATCHIEU s\n            JOIN dbo.PHONGCHIEU p ON p.PhongID = s.PhongID\n        WHERE\n            s.SuatChieuID = @SuatChieuID;\n        IF @ShowRap IS NULL\n            THROW 50021, N''Suất chiếu không tồn tại.'', 1;\n        EXEC dbo.sp_StaffBooking_Authorize @ActorID,\n            @PortalRole,\n            @ShowRap;\n        IF @RapID IS NOT NULL\n            AND @RapID <> @ShowRap\n            THROW 50511, N''Suất chiếu không thuộc rạp đã chọn.'', 1;\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.vw_LichChieuChiTiet\n            WHERE\n                SuatChieuID = @SuatChieuID\n                AND IsBookable = 1\n        )\n            THROW 50022, N''Suất chiếu không còn mở bán.'', 1;\n    END;\n    IF @DonDatVeID IS NOT NULL\n        AND NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.DONDATVE\n        WHERE\n            DonDatVeID = @DonDatVeID\n            AND SuatChieuID = @SuatChieuID\n    )\n        THROW 50033, N''Đơn đặt vé không tồn tại trong suất chiếu đã chọn.'', 1;\n    SELECT\n        RapID,\n        TenRap,\n        ThanhPho\n    FROM\n        dbo.RAPCHIEUPHIM\n    WHERE\n        @PortalRole = ''ADMIN''\n        OR dbo.fn_KiemTraQuanLyRapScope(@ActorID, RapID) = 1\n    ORDER BY\n        TenRap,\n        RapID;\n    SELECT\n        TOP(200) SuatChieuID,\n        RapID,\n        TenRap,\n        PhongID,\n        TenPhong,\n        PhimID,\n        TenPhim,\n        ThoiGianBatDau,\n        DinhDang,\n        GiaVeCoBan,\n        COUNT(*) OVER() AS TotalMatches\n    FROM\n        dbo.vw_LichChieuChiTiet\n    WHERE\n        IsBookable = 1\n        AND (\n            @RapID IS NULL\n            OR RapID = @RapID\n        )\n        AND (\n            @PortalRole = ''ADMIN''\n            OR dbo.fn_KiemTraQuanLyRapScope(@ActorID, RapID) = 1\n        )\n    ORDER BY\n        ThoiGianBatDau,\n        SuatChieuID;\n    SELECT\n        f.GheID,\n        f.PhongID,\n        f.HangGhe,\n        f.SoGhe,\n        f.TenGhe,\n        f.LoaiGhe,\n        COALESCE(t.GiaVe, f.GiaVe) AS GiaVe,\n        CASE\n            WHEN t.VeID IS NOT NULL THEN N''Trống''\n            ELSE f.TrangThaiGhe\n        END AS TrangThaiGhe\n    FROM\n        dbo.fn_DanhSachGheSuatChieu(@SuatChieuID) f\n        OUTER APPLY(\n            SELECT\n                TOP(1) VeID,\n                GiaVe\n            FROM\n                dbo.CHITIETVE\n            WHERE\n                DonDatVeID = @DonDatVeID\n                AND GheID = f.GheID\n                AND TrangThai = N''Đã đặt''\n            ORDER BY\n                VeID DESC\n        ) t\n    WHERE\n        @SuatChieuID IS NOT NULL\n    ORDER BY\n        f.HangGhe,\n        f.SoGhe;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_StaffBooking_UpdateSeats","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_StaffBooking_UpdateSeats\n    @ActorID int,\n    @PortalRole varchar(50),\n    @DonDatVeID int,\n    @DanhSachGheId varchar(max),\n    @ExpectedVeIdList varchar(max)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    DECLARE @Own bit = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @Own = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION StaffBookingUpdate;\n        EXEC dbo.sp_StaffBooking_Authorize @ActorID,\n            @PortalRole;\n        DECLARE @Customer int,\n            @Show int,\n            @Room int,\n            @Rap int,\n            @Hold datetime2,\n            @Status nvarchar(50),\n            @Promotion int;\n        SELECT\n            @Customer = NguoiDungID,\n            @Show = SuatChieuID\n        FROM\n            dbo.DONDATVE\n        WHERE\n            DonDatVeID = @DonDatVeID;\n        IF @Customer IS NULL\n            THROW 50033, N''Đơn đặt vé không tồn tại.'', 1;\n        EXEC dbo.sp_StaffBooking_LockShow @ActorID,\n            @PortalRole,\n            @Customer,\n            @Show,\n            @Rap OUTPUT,\n            @Room OUTPUT;\n        SELECT\n            @Status = TrangThai,\n            @Hold = HanGiuCho,\n            @Promotion = KhuyenMaiID\n        FROM\n            dbo.DONDATVE\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            DonDatVeID = @DonDatVeID\n            AND NguoiDungID = @Customer\n            AND SuatChieuID = @Show;\n        IF @Status IS NULL\n            OR @Status <> N''Chờ thanh toán''\n            OR @Promotion IS NOT NULL\n            OR EXISTS (\n                SELECT\n                    1\n                FROM\n                    dbo.DONDATVE\n                WHERE\n                    DonDatVeID = @DonDatVeID\n                    AND DiemSuDung > 0\n            )\n            OR EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.CHITIETDOAN\n            WHERE\n                DonDatVeID = @DonDatVeID\n        )\n            OR EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.CHITIETVE\n            WHERE\n                DonDatVeID = @DonDatVeID\n                AND TrangThai = N''Đã sử dụng''\n        )\n            THROW 50512, N''Chỉ sửa ghế của đơn chưa thanh toán, không khuyến mãi/đồ ăn/vé đã sử dụng.'', 1;\n        IF @Hold IS NULL\n            OR @Hold <= dbo.fn_BayGio()\n            THROW 50513, N''Đơn đã hết thời gian giữ ghế.'', 1;\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.THANHTOAN\n            WITH\n                (UPDLOCK, HOLDLOCK)\n            WHERE\n                DonDatVeID = @DonDatVeID\n        )\n            THROW 50514, N''Đơn đã có lần thử thanh toán; không thể sửa ghế.'', 1;\n        IF @DanhSachGheId IS NULL\n            OR @ExpectedVeIdList IS NULL\n            OR EXISTS (\n            SELECT\n                1\n            FROM\n                STRING_SPLIT(@DanhSachGheId, '','')\n            WHERE\n                TRY_CONVERT(int, value) IS NULL\n                OR TRY_CONVERT(int, value) <= 0\n                OR value LIKE ''%[^0-9]%''\n        )\n            OR EXISTS (\n            SELECT\n                1\n            FROM\n                STRING_SPLIT(@ExpectedVeIdList, '','')\n            WHERE\n                TRY_CONVERT(int, value) IS NULL\n                OR TRY_CONVERT(int, value) <= 0\n                OR value LIKE ''%[^0-9]%''\n        )\n            THROW 50511, N''Danh sách ghế/vé không hợp lệ.'', 1;\n        DECLARE @Seats\n        TABLE (id int PRIMARY KEY);\n        DECLARE @Expected\n        TABLE (id int PRIMARY KEY);\n        IF(\n            SELECT\n                COUNT(*)\n            FROM\n                STRING_SPLIT(@DanhSachGheId, '','')\n        ) <> (\n            SELECT\n                COUNT(DISTINCT value)\n            FROM\n                STRING_SPLIT(@DanhSachGheId, '','')\n        )\n            OR (\n            SELECT\n                COUNT(*)\n            FROM\n                STRING_SPLIT(@ExpectedVeIdList, '','')\n        ) <> (\n            SELECT\n                COUNT(DISTINCT value)\n            FROM\n                STRING_SPLIT(@ExpectedVeIdList, '','')\n        )\n            THROW 50511, N''Danh sách ghế/vé bị lặp.'', 1;\n        INSERT\n            @Seats\n        SELECT\n            CONVERT(int, value)\n        FROM\n            STRING_SPLIT(@DanhSachGheId, '','');\n        INSERT\n            @Expected\n        SELECT\n            CONVERT(int, value)\n        FROM\n            STRING_SPLIT(@ExpectedVeIdList, '','');\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                @Seats\n        )\n            OR (\n            SELECT\n                COUNT(*)\n            FROM\n                @Seats\n        ) > dbo.fn_GioiHanGheMoiDon()\n            THROW 50026, N''Chọn từ 1 đến 10 ghế.'', 1;\n        IF EXISTS (\n            SELECT\n                id\n            FROM\n                @Expected\n            EXCEPT\n            SELECT\n                VeID\n            FROM\n                dbo.CHITIETVE\n            WHERE\n                DonDatVeID = @DonDatVeID\n                AND TrangThai = N''Đã đặt''\n        )\n            OR EXISTS (\n            SELECT\n                VeID\n            FROM\n                dbo.CHITIETVE\n            WHERE\n                DonDatVeID = @DonDatVeID\n                AND TrangThai = N''Đã đặt''\n            EXCEPT\n            SELECT\n                id\n            FROM\n                @Expected\n        )\n            THROW 50515, N''Đơn đã được chỉnh sửa. Tải lại chi tiết trước khi lưu.'', 1;\n        DECLARE @Count int;\n        SELECT\n            @Count = COUNT(*)\n        FROM\n            dbo.GHE g\n        WITH\n            (UPDLOCK, HOLDLOCK)\n            JOIN @Seats s ON s.id = g.GheID\n        WHERE\n            g.PhongID = @Room\n            AND g.TrangThai = N''Hoạt động'';\n        IF @Count <> (\n            SELECT\n                COUNT(*)\n            FROM\n                @Seats\n        )\n            THROW 50024, N''Ghế không thuộc phòng hoặc không hoạt động.'', 1;\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.CHITIETVE t\n            WITH\n                (UPDLOCK, HOLDLOCK)\n                JOIN dbo.DONDATVE d ON d.DonDatVeID = t.DonDatVeID\n                JOIN @Seats s ON s.id = t.GheID\n            WHERE\n                d.SuatChieuID = @Show\n                AND d.DonDatVeID <> @DonDatVeID\n                AND t.TrangThai <> N''Đã hủy''\n                AND dbo.fn_DonDangGiuGhe(d.TrangThai, d.HanGiuCho, dbo.fn_BayGio()) = 1\n        )\n            THROW 50025, N''Ghế vừa được giữ/bán trong đơn khác.'', 1;\n        EXEC dbo.sp_StaffBooking_Authorize @ActorID,\n            @PortalRole,\n            @Rap;\n        IF @Hold <= dbo.fn_BayGio()\n            THROW 50513, N''Đơn đã hết thời gian giữ ghế.'', 1;\n        -- Keep IDs/codes/prices of retained tickets. Never delete historical rows.\n        UPDATE dbo.CHITIETVE\n        SET\n            TrangThai = N''Đã hủy''\n        WHERE\n            DonDatVeID = @DonDatVeID\n            AND TrangThai = N''Đã đặt''\n            AND GheID NOT IN (\n                SELECT\n                    id\n                FROM\n                    @Seats\n            );\n        INSERT\n            dbo.CHITIETVE(DonDatVeID, GheID, GiaVe, MaVe, TrangThai)\n        SELECT\n            @DonDatVeID,\n            s.id,\n            dbo.fn_TinhGiaVe(@Show, s.id),\n            CONCAT(''TK-'', CONVERT(varchar(36), NEWID())),\n            N''Đã đặt''\n        FROM\n            @Seats s\n        WHERE\n            NOT EXISTS (\n                SELECT\n                    1\n                FROM\n                    dbo.CHITIETVE\n                WHERE\n                    DonDatVeID = @DonDatVeID\n                    AND GheID = s.id\n                    AND TrangThai = N''Đã đặt''\n            );\n        -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n        UPDATE dbo.DONDATVE\n        SET\n            TongTienVe = dbo.fn_TinhTongTienVe(@DonDatVeID)\n        WHERE\n            DonDatVeID = @DonDatVeID;\n        EXEC dbo.sp_StaffBooking_Detail @ActorID,\n            @PortalRole,\n            @DonDatVeID;\n        IF @Own = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @Own = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION StaffBookingUpdate;\n        END;\n        THROW;\n    END CATCH;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Support_Complaint_AddProcessing","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/006_support_procedure_authorization.sql:57 (dbo.sp_Support_Complaint_AddProcessing)\nCREATE   PROCEDURE dbo.sp_Support_Complaint_AddProcessing\n    (\n    @NguoiDungID INT,\n    @KhieuNaiID INT,\n    @NoiDungXuLy NVARCHAR(MAX),\n    @TrangThaiSauXuLy NVARCHAR(50)\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''CSKH'', ''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''XULY_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        -- Mở transaction để các bước ghi được xử lý cùng nhau.\n        BEGIN TRANSACTION;\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.KHIEUNAI\n            WHERE\n                KhieuNaiID = @KhieuNaiID\n        )\n            THROW 50061, N''Khiếu nại không tồn tại.'', 1;\n        INSERT INTO\n            dbo.XULY_KHIEUNAI(KhieuNaiID, NguoiXuLyID, NoiDungXuLy, NgayXuLy, TrangThaiSauXuLy)\n        VALUES\n            (\n                @KhieuNaiID,\n                @NguoiDungID,\n                @NoiDungXuLy,\n                dbo.fn_BayGio(),\n                @TrangThaiSauXuLy\n            );\n        -- Chốt các thay đổi của transaction.\n        COMMIT TRANSACTION;\n        SELECT\n            XuLyID,\n            KhieuNaiID,\n            NguoiXuLyID,\n            NoiDungXuLy,\n            NgayXuLy,\n            TrangThaiSauXuLy\n        FROM\n            dbo.XULY_KHIEUNAI\n        WHERE\n            XuLyID = SCOPE_IDENTITY();\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Support_Complaint_GetDetail","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Phase 8 DBR-04: apply the same authorization and not-found guards that are\n-- present in the canonical support procedures. Migration 005 was already\n-- deployed before these guards were packaged, so this is deliberately separate.\nCREATE   PROCEDURE dbo.sp_Support_Complaint_GetDetail\n    (@NguoiDungID INT, @KhieuNaiID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''CSKH'', ''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.KHIEUNAI\n        WHERE\n            KhieuNaiID = @KhieuNaiID\n    )\n        THROW 50061, N''Khiếu nại không tồn tại.'', 1;\n    SELECT\n        kn.KhieuNaiID,\n        kn.NguoiDungID AS NguoiGuiID,\n        nd.HoTen AS HoTenNguoiGui,\n        nd.Email AS EmailNguoiGui,\n        nd.SoDienThoai AS SoDienThoaiNguoiGui,\n        kn.DonDatVeID,\n        kn.LoaiKhieuNai,\n        kn.TieuDe,\n        kn.NoiDung,\n        kn.MucDoUuTien,\n        kn.NgayTao,\n        kn.TrangThai AS TrangThaiKhieuNai,\n        kn.NhanVienPhuTrachID,\n        nv.HoTen AS TenNhanVienPhuTrach,\n        nv.Email AS EmailNhanVienPhuTrach\n    FROM\n        dbo.KHIEUNAI kn\n        INNER JOIN dbo.NGUOIDUNG nd ON kn.NguoiDungID = nd.NguoiDungID\n        LEFT JOIN dbo.NGUOIDUNG nv ON kn.NhanVienPhuTrachID = nv.NguoiDungID\n    WHERE\n        kn.KhieuNaiID = @KhieuNaiID;\n    SELECT\n        xl.XuLyID,\n        xl.NguoiXuLyID,\n        nd_xl.HoTen AS NguoiXuLy,\n        xl.NoiDungXuLy,\n        xl.NgayXuLy,\n        xl.TrangThaiSauXuLy\n    FROM\n        dbo.XULY_KHIEUNAI xl\n        INNER JOIN dbo.NGUOIDUNG nd_xl ON xl.NguoiXuLyID = nd_xl.NguoiDungID\n    WHERE\n        xl.KhieuNaiID = @KhieuNaiID\n    ORDER BY\n        xl.NgayXuLy ASC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Support_Complaint_GetOrderReference","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Support_Complaint_GetOrderReference\n    (@NguoiDungID INT, @KhieuNaiID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''CSKH'', ''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''TRA_CUU_DON'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.KHIEUNAI\n        WHERE\n            KhieuNaiID = @KhieuNaiID\n    )\n        THROW 50061, N''Khiếu nại không tồn tại.'', 1;\n    DECLARE @DonDatVeID INT;\n    SELECT\n        @DonDatVeID = DonDatVeID\n    FROM\n        dbo.KHIEUNAI\n    WHERE\n        KhieuNaiID = @KhieuNaiID;\n    IF @DonDatVeID IS NULL\n    BEGIN\n        SELECT\n            N''Khiếu nại này không gắn với đơn đặt vé tham chiếu cụ thể nào.'' AS [Message];\n        RETURN;\n    END;\n    -- Resolve the order only from this complaint; there is no caller-supplied order ID.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.DONDATVE\n        WHERE\n            DonDatVeID = @DonDatVeID\n    )\n        THROW 50030, N''Đơn tham chiếu không tồn tại.'', 1;\n    SELECT\n        v.*,\n        d.LyDoHuy,\n        d.ThongBaoHuy,\n        b.DiemBoiThuong,\n        b.NgayBoiThuong\n    FROM\n        dbo.vw_ChiTietDonDatVe v\n        INNER JOIN dbo.DONDATVE d ON d.DonDatVeID = v.DonDatVeID\n        LEFT JOIN dbo.BOITHUONG_HUYSUAT b ON b.DonDatVeID = v.DonDatVeID\n    WHERE\n        v.DonDatVeID = @DonDatVeID;\n    -- Preserve cancelled tickets and every payment attempt in the read contract.\n    SELECT\n        cv.VeID,\n        cv.MaVe,\n        g.GheID,\n        g.HangGhe,\n        g.SoGhe,\n        g.HangGhe + CAST(g.SoGhe AS VARCHAR(10)) AS TenGhe,\n        g.LoaiGhe,\n        cv.GiaVe,\n        cv.TrangThai AS TrangThaiVe\n    FROM\n        dbo.CHITIETVE cv\n        INNER JOIN dbo.GHE g ON g.GheID = cv.GheID\n    WHERE\n        cv.DonDatVeID = @DonDatVeID\n    ORDER BY\n        cv.VeID;\n    SELECT\n        cda.ChiTietDoAnID,\n        sp.SanPhamID,\n        sp.TenSanPham,\n        sp.LoaiSanPham,\n        cda.SoLuong,\n        cda.DonGia,\n        cda.SoLuong * cda.DonGia AS ThanhTien\n    FROM\n        dbo.CHITIETDOAN cda\n        INNER JOIN dbo.SANPHAM sp ON sp.SanPhamID = cda.SanPhamID\n    WHERE\n        cda.DonDatVeID = @DonDatVeID\n    ORDER BY\n        cda.ChiTietDoAnID;\n    -- STRICT 3NF: Tái dựng SoTien từ d.TongTienVe + d.TongTienDoAn - d.TienGiamGia\n    SELECT\n        tt.ThanhToanID,\n        tt.PhuongThuc,\n        CASE WHEN d.TongTienVe + d.TongTienDoAn - d.TienGiamGia < 0 THEN 0 ELSE d.TongTienVe + d.TongTienDoAn - d.TienGiamGia END AS SoTien,\n        tt.NgayTao,\n        tt.NgayThanhToan,\n        tt.MaGiaoDich,\n        tt.TrangThai,\n        tt.GhiChu\n    FROM\n        dbo.THANHTOAN tt\n        INNER JOIN dbo.DONDATVE d ON d.DonDatVeID = tt.DonDatVeID\n    WHERE\n        tt.DonDatVeID = @DonDatVeID\n    ORDER BY\n        tt.ThanhToanID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Support_Complaint_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Support_Complaint_List\n    (\n    @NguoiDungID INT,\n    @TrangThai NVARCHAR(50) = NULL,\n    @LoaiKhieuNai NVARCHAR(100) = NULL,\n    @SearchTerm NVARCHAR(100) = NULL,\n    @MucDoUuTien NVARCHAR(50) = NULL,\n    @PhuTrach NVARCHAR(50) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''CSKH'', ''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF @MucDoUuTien IS NOT NULL\n        AND @MucDoUuTien NOT IN (N''Thấp'', N''Trung bình'', N''Cao'', N''Khẩn cấp'')\n        THROW 50405, N''Mức ưu tiên không hợp lệ.'', 1;\n    SELECT\n        KhieuNaiID,\n        NguoiGuiID,\n        HoTenNguoiGui,\n        EmailNguoiGui,\n        SoDienThoaiNguoiGui,\n        DonDatVeID,\n        LoaiKhieuNai,\n        TieuDe,\n        NoiDung,\n        MucDoUuTien,\n        NgayTao,\n        TrangThaiKhieuNai,\n        NhanVienPhuTrachID,\n        TenNhanVienPhuTrach,\n        EmailNhanVienPhuTrach,\n        SoLanXuLy,\n        NgayXuLyCuoi,\n        NguoiXuLyCuoi,\n        NoiDungXuLyCuoi\n    FROM\n        dbo.vw_DanhSachKhieuNai\n    WHERE\n        (\n            @TrangThai IS NULL\n            OR TrangThaiKhieuNai = @TrangThai\n        )\n        AND (\n            @LoaiKhieuNai IS NULL\n            OR LoaiKhieuNai = @LoaiKhieuNai\n        )\n        AND (\n            @MucDoUuTien IS NULL\n            OR MucDoUuTien = @MucDoUuTien\n        )\n        AND (\n            @PhuTrach IS NULL\n            OR (@PhuTrach = N''ME'' AND NhanVienPhuTrachID = @NguoiDungID)\n            OR (@PhuTrach = N''UNASSIGNED'' AND NhanVienPhuTrachID IS NULL)\n        )\n        AND (\n            @SearchTerm IS NULL\n            OR TieuDe LIKE ''%'' + @SearchTerm + ''%''\n            OR HoTenNguoiGui LIKE ''%'' + @SearchTerm + ''%''\n            OR EmailNguoiGui LIKE ''%'' + @SearchTerm + ''%''\n        )\n    ORDER BY\n        CASE MucDoUuTien\n            WHEN N''Khẩn cấp'' THEN 1\n            WHEN N''Cao'' THEN 2\n            WHEN N''Trung bình'' THEN 3\n            ELSE 4\n        END ASC,\n        NgayTao DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Support_Complaint_UpdateStatus","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/005_support_status_history_atomicity.sql:3 (dbo.sp_Support_Complaint_UpdateStatus)\nCREATE   PROCEDURE dbo.sp_Support_Complaint_UpdateStatus\n    (@NguoiDungID INT, @KhieuNaiID INT, @TrangThaiMoi NVARCHAR(50))\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @NguoiDungID\n            AND vt.MaVaiTro IN (''CSKH'', ''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''QL_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''XULY_KHIEUNAI'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        -- Mở transaction để các bước ghi được xử lý cùng nhau.\n        BEGIN TRANSACTION;\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.KHIEUNAI\n            WHERE\n                KhieuNaiID = @KhieuNaiID\n        )\n            THROW 50061, N''Khiếu nại không tồn tại.'', 1;\n        INSERT INTO\n            dbo.XULY_KHIEUNAI(KhieuNaiID, NguoiXuLyID, NoiDungXuLy, NgayXuLy, TrangThaiSauXuLy)\n        VALUES\n            (\n                @KhieuNaiID,\n                @NguoiDungID,\n                N''Cập nhật trạng thái khiếu nại.'',\n                dbo.fn_BayGio(),\n                @TrangThaiMoi\n            );\n        -- Chốt các thay đổi của transaction.\n        COMMIT TRANSACTION;\n        SELECT\n            KhieuNaiID,\n            TrangThai\n        FROM\n            dbo.KHIEUNAI\n        WHERE\n            KhieuNaiID = @KhieuNaiID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_Support_Customer_GetPoints","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_Support_Customer_GetPoints\n    (\n    @NguoiDungID INT,\n    @TargetKhachHangID INT\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n\n    -- Kiểm tra tài khoản người gọi\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG\n        WHERE NguoiDungID = @NguoiDungID AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n\n    -- Kiểm tra vai trò CSKH hoặc ADMIN\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE nd.NguoiDungID = @NguoiDungID AND vt.MaVaiTro IN (''CSKH'', ''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n\n    -- Kiểm tra quyền TRA_CUU_DON\n    IF dbo.fn_KiemTraQuyenNguoiDung(@NguoiDungID, ''TRA_CUU_DON'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n\n    -- Kiểm tra khách hàng mục tiêu\n    IF NOT EXISTS (\n        SELECT 1 FROM dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE nd.NguoiDungID = @TargetKhachHangID AND vt.MaVaiTro = ''KHACH_HANG''\n    )\n        THROW 50030, N''Khách hàng không tồn tại.'', 1;\n\n    -- Recordset 1: Thông tin khách hàng & điểm hiện tại\n    SELECT\n        nd.NguoiDungID AS KhachHangID,\n        nd.HoTen,\n        nd.Email,\n        nd.SoDienThoai,\n        ISNULL(hs.DiemTichLuy, 0) AS DiemHienTai,\n        ISNULL((\n            SELECT SUM(d.DiemSuDung)\n            FROM dbo.DONDATVE d\n            WHERE d.NguoiDungID = @TargetKhachHangID\n              AND d.TrangThai IN (N''Đã thanh toán'', N''Hoàn thành'')\n        ), 0) AS TongDiemDaSuDung,\n        ISNULL((\n            SELECT SUM(b.DiemBoiThuong)\n            FROM dbo.BOITHUONG_HUYSUAT b\n            INNER JOIN dbo.DONDATVE d ON d.DonDatVeID = b.DonDatVeID\n            WHERE d.NguoiDungID = @TargetKhachHangID\n        ), 0) AS TongDiemBoiThuong\n    FROM dbo.NGUOIDUNG nd\n    LEFT JOIN dbo.HOSOKHACHHANG hs ON hs.NguoiDungID = nd.NguoiDungID\n    WHERE nd.NguoiDungID = @TargetKhachHangID;\n\n    -- Recordset 2: Lịch sử đơn có biến động điểm (sử dụng điểm hoặc nhận bồi thường)\n    SELECT\n        d.DonDatVeID,\n        d.NgayDat,\n        d.TrangThai,\n        d.TongTienVe,\n        d.TongTienDoAn,\n        d.TienGiamGia,\n        d.DiemSuDung,\n        b.DiemBoiThuong,\n        b.NgayBoiThuong,\n        b.GhiChu AS GhiChuBoiThuong\n    FROM dbo.DONDATVE d\n    LEFT JOIN dbo.BOITHUONG_HUYSUAT b ON b.DonDatVeID = d.DonDatVeID\n    WHERE d.NguoiDungID = @TargetKhachHangID\n      AND (d.DiemSuDung > 0 OR b.BoiThuongID IS NOT NULL)\n    ORDER BY d.NgayDat DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_System_HealthCheck","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_System_HealthCheck\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT\n        ''Healthy'' AS [Status],\n        dbo.fn_BayGio() AS [ServerTime],\n        DB_NAME() AS [DatabaseName],\n        @@VERSION AS [SQLVersion];\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_ThemSuatChieu","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_ThemSuatChieu\n    (\n    @NguoiDungID INT,\n    @PhimID INT,\n    @PhongID INT,\n    @ThoiGianBatDau DATETIME2,\n    @ThoiGianKetThuc DATETIME2,\n    @DinhDang NVARCHAR(50) = N''2D'',\n    @GiaVeCoBan DECIMAL(18, 2)\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    EXEC dbo.sp_Manager_Showtime_Create @NguoiDungID = @NguoiDungID,\n        @PhimID = @PhimID,\n        @PhongID = @PhongID,\n        @ThoiGianBatDau = @ThoiGianBatDau,\n        @ThoiGianKetThuc = @ThoiGianKetThuc,\n        @DinhDang = @DinhDang,\n        @GiaVeCoBan = @GiaVeCoBan;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_User_ChangePassword","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_User_ChangePassword\n    (@NguoiDungID INT, @NewPasswordHash VARCHAR(255))\nAS\nBEGIN\n    SET NOCOUNT ON;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @NguoiDungID\n            AND TrangThai = N''Hoạt động''\n    )\n    BEGIN\n        ;\n        THROW 50016, N''Tài khoản không tồn tại hoặc không hoạt động.'', 1;\n    END\n    -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n    UPDATE dbo.NGUOIDUNG\n    SET\n        MatKhau = @NewPasswordHash\n    WHERE\n        NguoiDungID = @NguoiDungID;\n    SELECT\n        N''Đổi mật khẩu thành công.'' AS [Message];\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_User_GetCurrent","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_User_GetCurrent\n    (@NguoiDungID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT\n        nd.NguoiDungID,\n        nd.HoTen,\n        nd.Email,\n        nd.SoDienThoai,\n        nd.NgayTao,\n        nd.TrangThai,\n        vt.MaVaiTro,\n        vt.TenVaiTro,\n        hk.NgaySinh,\n        hk.GioiTinh,\n        hk.DiemTichLuy\n    FROM\n        dbo.NGUOIDUNG nd\n        INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID\n        LEFT JOIN dbo.HOSOKHACHHANG hk ON nd.NguoiDungID = hk.NguoiDungID\n    WHERE\n        nd.NguoiDungID = @NguoiDungID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_User_GetPasswordHash","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_User_GetPasswordHash\n    (@NguoiDungID INT)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT\n        NguoiDungID,\n        MatKhau AS MatKhauHash\n    FROM\n        dbo.NGUOIDUNG\n    WHERE\n        NguoiDungID = @NguoiDungID\n        AND TrangThai = N''Hoạt động'';\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_User_UpdateProfile","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_User_UpdateProfile\n    (\n    @NguoiDungID INT,\n    @HoTen NVARCHAR(100),\n    @SoDienThoai VARCHAR(20) = NULL,\n    @NgaySinh DATE = NULL,\n    @GioiTinh NVARCHAR(10) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    IF @NgaySinh > dbo.fn_HomNay()\n        THROW 50400, N''Ngày sinh không được ở tương lai.'', 1;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION;\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION UserUpdateProfile;\n        DECLARE @MaVaiTro VARCHAR(50);\n        SELECT\n            @MaVaiTro = v.MaVaiTro\n        FROM\n            dbo.NGUOIDUNG n\n        WITH\n            (UPDLOCK, HOLDLOCK)\n            JOIN dbo.VAITRO v\n        WITH\n            (HOLDLOCK) ON v.VaiTroID = n.VaiTroID\n        WHERE\n            n.NguoiDungID = @NguoiDungID\n            AND n.TrangThai = N''Hoạt động'';\n        IF @MaVaiTro IS NULL\n            THROW 50300, N''Tài khoản không khả dụng.'', 1;\n        IF @MaVaiTro <> ''KHACH_HANG''\n            AND (\n            @NgaySinh IS NOT NULL\n            OR @GioiTinh IS NOT NULL\n        )\n            THROW 50301, N''Chỉ khách hàng được cập nhật ngày sinh và giới tính.'', 1;\n        -- Kiểm tra trùng số điện thoại với tài khoản khác\n        IF @SoDienThoai IS NOT NULL\n            AND EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.NGUOIDUNG\n            WHERE\n                SoDienThoai = @SoDienThoai\n                AND NguoiDungID <> @NguoiDungID\n        )\n        BEGIN\n            ;\n            THROW 50015, N''Số điện thoại đã thuộc về một tài khoản khác.'', 1;\n        END\n        -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n        UPDATE dbo.NGUOIDUNG\n        SET\n            HoTen = @HoTen,\n            SoDienThoai = @SoDienThoai\n        WHERE\n            NguoiDungID = @NguoiDungID;\n        IF @MaVaiTro = ''KHACH_HANG''\n        BEGIN\n            IF EXISTS (\n                SELECT\n                    1\n                FROM\n                    dbo.HOSOKHACHHANG\n                WITH\n                    (UPDLOCK, HOLDLOCK)\n                WHERE\n                    NguoiDungID = @NguoiDungID\n            )\n            BEGIN\n                -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n                UPDATE dbo.HOSOKHACHHANG\n                SET\n                    NgaySinh = @NgaySinh,\n                    GioiTinh = @GioiTinh\n                WHERE\n                    NguoiDungID = @NguoiDungID;\n            END\n            ELSE\n            BEGIN\n                INSERT INTO\n                    dbo.HOSOKHACHHANG(NguoiDungID, NgaySinh, GioiTinh, DiemTichLuy)\n                VALUES\n                    (@NguoiDungID, @NgaySinh, @GioiTinh, 0);\n            END\n        END\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        -- Trả về dữ liệu sau cập nhật\n        EXEC dbo.sp_User_GetCurrent @NguoiDungID = @NguoiDungID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION;\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION UserUpdateProfile;\n        END;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_XuLyKhieuNai","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_XuLyKhieuNai\n    (\n    @NguoiDungID INT,\n    @KhieuNaiID INT,\n    @NoiDungXuLy NVARCHAR(MAX),\n    @TrangThaiSauXuLy NVARCHAR(50)\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    EXEC dbo.sp_Support_Complaint_AddProcessing @NguoiDungID = @NguoiDungID,\n        @KhieuNaiID = @KhieuNaiID,\n        @NoiDungXuLy = @NoiDungXuLy,\n        @TrangThaiSauXuLy = @TrangThaiSauXuLy;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"sp_XuLyThanhToan","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.sp_XuLyThanhToan\n    (\n    @NguoiDungID INT,\n    @ThanhToanID INT,\n    @TrangThaiThanhToan NVARCHAR(50),\n    @MaGiaoDichNgoai VARCHAR(100) = NULL,\n    @GhiChu NVARCHAR(255) = NULL\n    )\nAS\nBEGIN\n    SET NOCOUNT ON;\n    EXEC dbo.sp_Payment_UpdateResult @NguoiDungID = @NguoiDungID,\n        @ThanhToanID = @ThanhToanID,\n        @TrangThaiThanhToan = @TrangThaiThanhToan,\n        @MaGiaoDichNgoai = @MaGiaoDichNgoai,\n        @GhiChu = @GhiChu;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Assignment_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Assignment_Update\n    @ActorID INT,\n    @PhanCongID INT,\n    @NguoiDungID INT,\n    @RapID INT,\n    @NgayBatDau DATE,\n    @NgayKetThuc DATE = NULL,\n    @TrangThai NVARCHAR(50)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''PHANCONG_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION AssignmentUpdate;\n        DECLARE @LockedRows BIGINT;\n        SELECT\n            @LockedRows = COUNT_BIG(*)\n        FROM\n            dbo.PHANCONG_RAP\n        WITH\n            (TABLOCKX, HOLDLOCK);\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.PHANCONG_RAP\n            WITH\n                (UPDLOCK, HOLDLOCK)\n            WHERE\n                PhanCongID = @PhanCongID\n        )\n            THROW 50212, N''Phân công không tồn tại.'', 1;\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.NGUOIDUNG nd\n            WITH\n                (HOLDLOCK)\n                INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n            WHERE\n                nd.NguoiDungID = @NguoiDungID\n                AND vt.MaVaiTro = ''QUAN_LY_RAP''\n        )\n            THROW 50071, N''Tài khoản được phân công phải có vai trò QUAN_LY_RAP.'', 1;\n        IF @NgayKetThuc IS NOT NULL\n            AND @NgayKetThuc < @NgayBatDau\n            THROW 50213, N''Khoảng thời gian phân công không hợp lệ.'', 1;\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.PHANCONG_RAP\n            WHERE\n                PhanCongID <> @PhanCongID\n                AND NguoiDungID = @NguoiDungID\n                AND RapID = @RapID\n                AND NgayBatDau = @NgayBatDau\n                AND (\n                    NgayKetThuc = @NgayKetThuc\n                    OR (\n                        NgayKetThuc IS NULL\n                        AND @NgayKetThuc IS NULL\n                    )\n                )\n                AND TrangThai = @TrangThai\n        )\n            THROW 50401, N''Phân công hoàn toàn giống nhau đã tồn tại.'', 1;\n        -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n        UPDATE dbo.PHANCONG_RAP\n        SET\n            NguoiDungID = @NguoiDungID,\n            RapID = @RapID,\n            NgayBatDau = @NgayBatDau,\n            NgayKetThuc = @NgayKetThuc,\n            TrangThai = @TrangThai\n        WHERE\n            PhanCongID = @PhanCongID;\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        SELECT\n            p.PhanCongID,\n            p.NguoiDungID,\n            nd.HoTen AS TenQuanLy,\n            nd.Email,\n            p.RapID,\n            r.TenRap,\n            p.NgayBatDau,\n            p.NgayKetThuc,\n            p.TrangThai\n        FROM\n            dbo.PHANCONG_RAP p\n            INNER JOIN dbo.NGUOIDUNG nd ON nd.NguoiDungID = p.NguoiDungID\n            INNER JOIN dbo.RAPCHIEUPHIM r ON r.RapID = p.RapID\n        WHERE\n            p.PhanCongID = @PhanCongID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION AssignmentUpdate;\n        END;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Cinema_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Cinema_List\n    @ActorID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SELECT\n        RapID,\n        TenRap,\n        DiaChi,\n        ThanhPho,\n        SoDienThoai,\n        MoTa,\n        NgayHoatDong,\n        TrangThai\n    FROM\n        dbo.RAPCHIEUPHIM\n    ORDER BY\n        ThanhPho,\n        TenRap;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_CinemaImage_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- BUG-003: the key-range lock used to be a bare SELECT, which sent an extra\n-- result set to the client ahead of the final image DTO. The backend reads the\n-- first result set, so create returned null and set-cover returned a lock row.\n-- The lock is now taken by assigning to a variable (it still scans, and so\n-- locks, every image row of the cinema); the DTO is the only result set.\n-- Transaction, lock and one-cover-per-cinema logic are otherwise unchanged.\nCREATE   PROCEDURE dbo.usp_Admin_CinemaImage_Create\n    @ActorID INT,\n    @RapID INT,\n    @URL NVARCHAR(500),\n    @MoTa NVARCHAR(255) = NULL,\n    @LaAnhDaiDien BIT = 0,\n    @ThuTuHienThi INT = 0,\n    @TrangThai NVARCHAR(50) = N''Hoạt động''\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF LEN(LTRIM(RTRIM(ISNULL(@URL, N'''')))) = 0\n        THROW 50220, N''URL ảnh không được để trống.'', 1;\n    IF @ThuTuHienThi < 0\n        THROW 50221, N''Thứ tự hiển thị phải lớn hơn hoặc bằng 0.'', 1;\n    DECLARE @OwnTransaction BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    DECLARE @LockedImageID INT;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTransaction = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION;\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION CinemaImageCreate;\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.RAPCHIEUPHIM\n            WITH\n                (UPDLOCK, HOLDLOCK)\n            WHERE\n                RapID = @RapID\n        )\n            THROW 50200, N''Rạp không tồn tại.'', 1;\n        SELECT\n            @LockedImageID = HinhAnhRapID\n        FROM\n            dbo.HINHANH_RAPCHIEUPHIM\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            RapID = @RapID;\n        IF @LaAnhDaiDien = 1\n            -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n            UPDATE dbo.HINHANH_RAPCHIEUPHIM\n            SET\n                LaAnhDaiDien = 0\n            WHERE\n                RapID = @RapID\n                AND LaAnhDaiDien = 1;\n        INSERT\n            dbo.HINHANH_RAPCHIEUPHIM(RapID, URL, MoTa, LaAnhDaiDien, ThuTuHienThi, TrangThai)\n        VALUES\n            (@RapID, @URL, @MoTa, @LaAnhDaiDien, @ThuTuHienThi, @TrangThai);\n        DECLARE @HinhAnhRapID INT = SCOPE_IDENTITY();\n        IF @OwnTransaction = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        SELECT\n            HinhAnhRapID,\n            RapID,\n            URL,\n            MoTa,\n            LaAnhDaiDien,\n            ThuTuHienThi,\n            TrangThai,\n            NgayTao\n        FROM\n            dbo.HINHANH_RAPCHIEUPHIM\n        WHERE\n            HinhAnhRapID = @HinhAnhRapID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() <> 0\n        BEGIN\n            IF @OwnTransaction = 1\n                OR XACT_STATE() = - 1\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION;\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION CinemaImageCreate;\n        END;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_CinemaImage_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_CinemaImage_Delete\n    @ActorID INT,\n    @RapID INT,\n    @HinhAnhRapID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Xóa các bản ghi thỏa điều kiện đã xác định.\n    DELETE dbo.HINHANH_RAPCHIEUPHIM\n    WHERE\n        HinhAnhRapID = @HinhAnhRapID\n        AND RapID = @RapID;\n    IF @@ROWCOUNT = 0\n        THROW 50230, N''Ảnh rạp không tồn tại trong phạm vi rạp.'', 1;\n    SELECT\n        N''Đã xóa ảnh rạp.'' AS [Message];\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_CinemaImage_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_CinemaImage_List\n    @ActorID INT,\n    @RapID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.RAPCHIEUPHIM\n        WHERE\n            RapID = @RapID\n    )\n        THROW 50200, N''Rạp không tồn tại.'', 1;\n    SELECT\n        HinhAnhRapID,\n        RapID,\n        URL,\n        MoTa,\n        LaAnhDaiDien,\n        ThuTuHienThi,\n        TrangThai,\n        NgayTao\n    FROM\n        dbo.HINHANH_RAPCHIEUPHIM\n    WHERE\n        RapID = @RapID\n    ORDER BY\n        ThuTuHienThi,\n        HinhAnhRapID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_CinemaImage_SetCover","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_CinemaImage_SetCover\n    @ActorID INT,\n    @RapID INT,\n    @HinhAnhRapID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @OwnTransaction BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    DECLARE @LockedImageID INT;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTransaction = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION;\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION CinemaImageSetCover;\n        -- Key-range locking serializes cover changes for one cinema.\n        SELECT\n            @LockedImageID = HinhAnhRapID\n        FROM\n            dbo.HINHANH_RAPCHIEUPHIM\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            RapID = @RapID;\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.HINHANH_RAPCHIEUPHIM\n            WITH\n                (UPDLOCK, HOLDLOCK)\n            WHERE\n                RapID = @RapID\n                AND HinhAnhRapID = @HinhAnhRapID\n        )\n            THROW 50230, N''Ảnh rạp không tồn tại trong phạm vi rạp.'', 1;\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.HINHANH_RAPCHIEUPHIM\n            WHERE\n                RapID = @RapID\n                AND HinhAnhRapID = @HinhAnhRapID\n                AND TrangThai <> N''Hoạt động''\n        )\n            THROW 50232, N''Chỉ ảnh đang hoạt động mới có thể là ảnh đại diện.'', 1;\n        -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n        UPDATE dbo.HINHANH_RAPCHIEUPHIM\n        SET\n            LaAnhDaiDien = 0\n        WHERE\n            RapID = @RapID\n            AND LaAnhDaiDien = 1;\n        -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n        UPDATE dbo.HINHANH_RAPCHIEUPHIM\n        SET\n            LaAnhDaiDien = 1\n        WHERE\n            RapID = @RapID\n            AND HinhAnhRapID = @HinhAnhRapID;\n        IF @OwnTransaction = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        SELECT\n            HinhAnhRapID,\n            RapID,\n            URL,\n            MoTa,\n            LaAnhDaiDien,\n            ThuTuHienThi,\n            TrangThai,\n            NgayTao\n        FROM\n            dbo.HINHANH_RAPCHIEUPHIM\n        WHERE\n            HinhAnhRapID = @HinhAnhRapID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() <> 0\n        BEGIN\n            IF @OwnTransaction = 1\n                OR XACT_STATE() = - 1\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION;\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION CinemaImageSetCover;\n        END;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_CinemaImage_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- usp_Admin_CinemaImage_Update (migration 009) ran without a transaction or the\n-- cinema-wide key-range lock that Create/SetCover take. Its row-level UPDATE locks\n-- were acquired in a different order than SetCover''s, so concurrent Update and\n-- SetCover on one cinema could deadlock (one request failed with HTTP 500).\n-- It now takes the same lock first, assigned to a variable so that no extra result\n-- set reaches the client. Validation order, error numbers/messages, the \"disabling\n-- an image clears its cover flag\" rule and the single DTO result set are unchanged.\nCREATE   PROCEDURE dbo.usp_Admin_CinemaImage_Update\n    @ActorID INT,\n    @RapID INT,\n    @HinhAnhRapID INT,\n    @URL NVARCHAR(500),\n    @MoTa NVARCHAR(255) = NULL,\n    @ThuTuHienThi INT = 0,\n    @TrangThai NVARCHAR(50) = N''Hoạt động''\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_RAP'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF LEN(LTRIM(RTRIM(ISNULL(@URL, N'''')))) = 0\n        THROW 50220, N''URL ảnh không được để trống.'', 1;\n    IF @ThuTuHienThi < 0\n        THROW 50221, N''Thứ tự hiển thị phải lớn hơn hoặc bằng 0.'', 1;\n    DECLARE @OwnTransaction BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    DECLARE @LockedImageID INT;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTransaction = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION;\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION CinemaImageUpdate;\n        -- Same key-range lock (and order) as Create/SetCover: serialises all image changes of one cinema.\n        SELECT\n            @LockedImageID = HinhAnhRapID\n        FROM\n            dbo.HINHANH_RAPCHIEUPHIM\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            RapID = @RapID;\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.HINHANH_RAPCHIEUPHIM\n            WITH\n                (UPDLOCK, HOLDLOCK)\n            WHERE\n                HinhAnhRapID = @HinhAnhRapID\n                AND RapID = @RapID\n        )\n            THROW 50230, N''Ảnh rạp không tồn tại trong phạm vi rạp.'', 1;\n        -- Disabling a cover clears it; no replacement is automatically selected.\n        UPDATE dbo.HINHANH_RAPCHIEUPHIM\n        SET\n            URL = @URL,\n            MoTa = @MoTa,\n            ThuTuHienThi = @ThuTuHienThi,\n            TrangThai = @TrangThai,\n            LaAnhDaiDien = CASE\n                WHEN @TrangThai = N''Hoạt động'' THEN LaAnhDaiDien\n                ELSE 0\n            END\n        WHERE\n            HinhAnhRapID = @HinhAnhRapID\n            AND RapID = @RapID;\n        IF @OwnTransaction = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        SELECT\n            HinhAnhRapID,\n            RapID,\n            URL,\n            MoTa,\n            LaAnhDaiDien,\n            ThuTuHienThi,\n            TrangThai,\n            NgayTao\n        FROM\n            dbo.HINHANH_RAPCHIEUPHIM\n        WHERE\n            HinhAnhRapID = @HinhAnhRapID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() <> 0\n        BEGIN\n            IF @OwnTransaction = 1\n                OR XACT_STATE() = - 1\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION;\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION CinemaImageUpdate;\n        END;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Movie_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Movie_List\n    @ActorID INT,\n    @TrangThai NVARCHAR(50) = NULL,\n    @TheLoaiID INT = NULL,\n    @SearchTerm NVARCHAR(100) = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_DANHMUC_PHIM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SELECT DISTINCT\n        p.PhimID,\n        p.TenPhim,\n        p.ThoiLuong,\n        p.NgayKhoiChieu,\n        p.NgayKetThuc,\n        p.NgonNgu,\n        p.PhuDe,\n        p.DoTuoi,\n        p.DaoDien,\n        p.MoTa,\n        p.PosterURL,\n        p.TrailerURL,\n        p.TrangThai,\n        STUFF(\n            (\n                SELECT\n                    '','' + CAST(pt.TheLoaiID AS VARCHAR(12))\n                FROM\n                    dbo.PHIM_THELOAI pt\n                WHERE\n                    pt.PhimID = p.PhimID\n                ORDER BY\n                    pt.TheLoaiID\n                FOR XML\n                    PATH(''''),\n                TYPE\n            ).value(''.'', ''NVARCHAR(MAX)''),\n            1,\n            1,\n            ''''\n        ) AS TheLoaiIdList,\n        (\n            SELECT\n                pd.DienVienID AS actorId,\n                pd.VaiDien AS [role]\n            FROM\n                dbo.PHIM_DIENVIEN pd\n            WHERE\n                pd.PhimID = p.PhimID\n            ORDER BY\n                pd.DienVienID\n            FOR JSON\n                PATH\n        ) AS DanhSachDienVienJson\n    FROM\n        dbo.PHIM p\n        LEFT JOIN dbo.PHIM_THELOAI ptFilter ON ptFilter.PhimID = p.PhimID\n    WHERE\n        (\n            @TrangThai IS NULL\n            OR p.TrangThai = @TrangThai\n        )\n        AND (\n            @TheLoaiID IS NULL\n            OR ptFilter.TheLoaiID = @TheLoaiID\n        )\n        AND (\n            @SearchTerm IS NULL\n            OR p.TenPhim LIKE ''%'' + @SearchTerm + ''%''\n            OR p.DaoDien LIKE ''%'' + @SearchTerm + ''%''\n        )\n    ORDER BY\n        p.NgayKhoiChieu DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Pricing_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Pricing_Create\n    @ActorID INT,\n    @RapID INT,\n    @LoaiGhe NVARCHAR(50),\n    @LoaiNgay NVARCHAR(50),\n    @DinhDang NVARCHAR(50),\n    @PhuThu DECIMAL(18, 2),\n    @NgayBatDau DATE,\n    @NgayKetThuc DATE = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_BANG_GIA'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.RAPCHIEUPHIM\n        WHERE\n            RapID = @RapID\n    )\n        THROW 50208, N''Rạp không tồn tại.'', 1;\n    IF @PhuThu < 0\n        OR (\n        @NgayKetThuc IS NOT NULL\n        AND @NgayKetThuc < @NgayBatDau\n    )\n        THROW 50209, N''Khoảng ngày hoặc phụ thu không hợp lệ.'', 1;\n    INSERT\n        dbo.BANGGIA(\n            RapID,\n            LoaiGhe,\n            LoaiNgay,\n            DinhDang,\n            PhuThu,\n            NgayBatDau,\n            NgayKetThuc,\n            TrangThai\n        )\n    VALUES\n        (\n            @RapID,\n            @LoaiGhe,\n            @LoaiNgay,\n            @DinhDang,\n            @PhuThu,\n            @NgayBatDau,\n            @NgayKetThuc,\n            N''Áp dụng''\n        );\n    SELECT\n        GiaID,\n        RapID,\n        LoaiGhe,\n        LoaiNgay,\n        DinhDang,\n        PhuThu,\n        NgayBatDau,\n        NgayKetThuc,\n        TrangThai\n    FROM\n        dbo.BANGGIA\n    WHERE\n        GiaID = SCOPE_IDENTITY();\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Pricing_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Pricing_List\n    @ActorID INT,\n    @RapID INT = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_BANG_GIA'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SELECT\n        bg.GiaID,\n        bg.RapID,\n        r.TenRap,\n        bg.LoaiGhe,\n        bg.LoaiNgay,\n        bg.DinhDang,\n        bg.PhuThu,\n        bg.NgayBatDau,\n        bg.NgayKetThuc,\n        bg.TrangThai\n    FROM\n        dbo.BANGGIA bg\n        INNER JOIN dbo.RAPCHIEUPHIM r ON r.RapID = bg.RapID\n    WHERE\n        @RapID IS NULL\n        OR bg.RapID = @RapID\n    ORDER BY\n        r.TenRap,\n        bg.NgayBatDau DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Pricing_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Pricing_Update\n    @ActorID INT,\n    @GiaID INT,\n    @PhuThu DECIMAL(18, 2),\n    @TrangThai NVARCHAR(50),\n    @LoaiGhe NVARCHAR(50) = NULL,\n    @LoaiNgay NVARCHAR(50) = NULL,\n    @DinhDang NVARCHAR(50) = NULL,\n    @NgayBatDau DATE = NULL,\n    @NgayKetThuc DATE = NULL,\n    @CapNhatDieuKien BIT = 0\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_BANG_GIA'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION AdminPricingUpdate;\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.BANGGIA\n            WITH\n                (UPDLOCK, HOLDLOCK)\n            WHERE\n                GiaID = @GiaID\n        )\n            THROW 50210, N''Bảng giá không tồn tại.'', 1;\n        IF @PhuThu < 0\n            THROW 50209, N''Phụ thu không hợp lệ.'', 1;\n        IF @CapNhatDieuKien = 1\n            AND (\n            @LoaiGhe IS NULL\n            OR @LoaiNgay IS NULL\n            OR @DinhDang IS NULL\n            OR @NgayBatDau IS NULL\n            OR (\n                @NgayKetThuc IS NOT NULL\n                AND @NgayKetThuc < @NgayBatDau\n            )\n        )\n            THROW 50209, N''Điều kiện hoặc khoảng ngày bảng giá không hợp lệ.'', 1;\n        -- Match Manager condition-edit semantics; old callers retain all conditions.\n        -- RapID and monetary snapshots remain immutable through this operation.\n        UPDATE dbo.BANGGIA\n        SET\n            PhuThu = @PhuThu,\n            TrangThai = @TrangThai,\n            LoaiGhe = CASE\n                WHEN @CapNhatDieuKien = 1 THEN @LoaiGhe\n                ELSE LoaiGhe\n            END,\n            LoaiNgay = CASE\n                WHEN @CapNhatDieuKien = 1 THEN @LoaiNgay\n                ELSE LoaiNgay\n            END,\n            DinhDang = CASE\n                WHEN @CapNhatDieuKien = 1 THEN @DinhDang\n                ELSE DinhDang\n            END,\n            NgayBatDau = CASE\n                WHEN @CapNhatDieuKien = 1 THEN @NgayBatDau\n                ELSE NgayBatDau\n            END,\n            NgayKetThuc = CASE\n                WHEN @CapNhatDieuKien = 1 THEN @NgayKetThuc\n                ELSE NgayKetThuc\n            END\n        WHERE\n            GiaID = @GiaID;\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION;\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION AdminPricingUpdate;\n        END;\n        THROW;\n    END CATCH;\n    SELECT\n        GiaID,\n        RapID,\n        LoaiGhe,\n        LoaiNgay,\n        DinhDang,\n        PhuThu,\n        NgayBatDau,\n        NgayKetThuc,\n        TrangThai\n    FROM\n        dbo.BANGGIA\n    WHERE\n        GiaID = @GiaID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Product_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Product_List\n    @ActorID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SANPHAM'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SELECT\n        SanPhamID,\n        TenSanPham,\n        LoaiSanPham,\n        Gia,\n        MoTa,\n        HinhAnh,\n        TrangThai\n    FROM\n        dbo.SANPHAM\n    ORDER BY\n        TenSanPham;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_RolePermission_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_RolePermission_List\n    @ActorID INT,\n    @VaiTroID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_QUYEN'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.VAITRO\n        WHERE\n            VaiTroID = @VaiTroID\n    )\n        THROW 50214, N''Vai trò không tồn tại.'', 1;\n    SELECT\n        vq.VaiTroID,\n        q.QuyenID,\n        q.MaQuyen,\n        q.TenQuyen\n    FROM\n        dbo.VAITRO_QUYEN vq\n        INNER JOIN dbo.QUYEN q ON q.QuyenID = vq.QuyenID\n    WHERE\n        vq.VaiTroID = @VaiTroID\n    ORDER BY\n        q.MaQuyen;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Room_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Room_Create\n    @ActorID INT,\n    @RapID INT,\n    @TenPhong NVARCHAR(100),\n    @LoaiPhong NVARCHAR(50) = N''2D''\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.RAPCHIEUPHIM\n        WHERE\n            RapID = @RapID\n    )\n        THROW 50200, N''Rạp không tồn tại.'', 1;\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.PHONGCHIEU\n        WHERE\n            RapID = @RapID\n            AND TenPhong = @TenPhong\n    )\n        THROW 50201, N''Tên phòng đã tồn tại trong rạp.'', 1;\n    INSERT\n        dbo.PHONGCHIEU(RapID, TenPhong, LoaiPhong, TrangThai)\n    VALUES\n        (@RapID, @TenPhong, @LoaiPhong, N''Hoạt động'');\n    SELECT\n        PhongID,\n        RapID,\n        TenPhong,\n        LoaiPhong,\n        TrangThai\n    FROM\n        dbo.PHONGCHIEU\n    WHERE\n        PhongID = SCOPE_IDENTITY();\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Room_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Room_Delete\n    @ActorID INT,\n    @PhongID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SET XACT_ABORT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @Deactivated BIT = 0;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        -- Mở transaction để các bước ghi được xử lý cùng nhau.\n        BEGIN TRANSACTION;\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.PHONGCHIEU\n            WITH\n                (UPDLOCK, HOLDLOCK)\n            WHERE\n                PhongID = @PhongID\n        )\n            THROW 50202, N''Phòng không tồn tại.'', 1;\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.SUATCHIEU\n            WITH\n                (UPDLOCK, HOLDLOCK)\n            WHERE\n                PhongID = @PhongID\n        )\n        BEGIN\n            -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n            UPDATE dbo.PHONGCHIEU\n            SET\n                TrangThai = N''Ngưng hoạt động''\n            WHERE\n                PhongID = @PhongID;\n            SET\n                @Deactivated = 1;\n        END\n        ELSE\n        BEGIN\n            -- Xóa các bản ghi thỏa điều kiện đã xác định.\n            DELETE dbo.GHE\n            WHERE\n                PhongID = @PhongID;\n            -- Xóa các bản ghi thỏa điều kiện đã xác định.\n            DELETE dbo.PHONGCHIEU\n            WHERE\n                PhongID = @PhongID;\n        END;\n        -- Chốt các thay đổi của transaction.\n        COMMIT TRANSACTION;\n        SELECT\n            @PhongID AS PhongID,\n            CAST(1 - @Deactivated AS BIT) AS Deleted,\n            @Deactivated AS Deactivated,\n            CASE\n                WHEN @Deactivated = 1 THEN N''Ngưng hoạt động''\n            END AS TrangThai,\n            CASE\n                WHEN @Deactivated = 1 THEN N''Phòng có lịch sử suất chiếu đã chuyển sang Ngưng hoạt động.''\n                ELSE N''Đã xóa phòng.''\n            END AS [Message];\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        DECLARE @ErrorNumber INT = ERROR_NUMBER();\n        IF XACT_STATE() <> 0\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        IF @ErrorNumber IN (547, 1205, 1222)\n            THROW 50217, N''Xung đột khi xóa phòng. Dữ liệu đã được hoàn tác; vui lòng tải lại và thử lại.'', 1;\n        ;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Room_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Room_List\n    @ActorID INT,\n    @RapID INT = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SELECT\n        pc.PhongID,\n        pc.RapID,\n        r.TenRap,\n        pc.TenPhong,\n        pc.LoaiPhong,\n        pc.TrangThai,\n        (\n            SELECT\n                COUNT(*)\n            FROM\n                dbo.GHE g\n            WHERE\n                g.PhongID = pc.PhongID\n        ) AS TongSoGhe\n    FROM\n        dbo.PHONGCHIEU pc\n        INNER JOIN dbo.RAPCHIEUPHIM r ON r.RapID = pc.RapID\n    WHERE\n        @RapID IS NULL\n        OR pc.RapID = @RapID\n    ORDER BY\n        r.TenRap,\n        pc.TenPhong;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Room_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Room_Update\n    @ActorID INT,\n    @PhongID INT,\n    @TenPhong NVARCHAR(100),\n    @LoaiPhong NVARCHAR(50),\n    @TrangThai NVARCHAR(50)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_PHONG'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @RapID INT = (\n        SELECT\n            RapID\n        FROM\n            dbo.PHONGCHIEU\n        WHERE\n            PhongID = @PhongID\n    );\n    IF @RapID IS NULL\n        THROW 50202, N''Phòng không tồn tại.'', 1;\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.PHONGCHIEU\n        WHERE\n            RapID = @RapID\n            AND TenPhong = @TenPhong\n            AND PhongID <> @PhongID\n    )\n        THROW 50201, N''Tên phòng đã tồn tại trong rạp.'', 1;\n    -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n    UPDATE dbo.PHONGCHIEU\n    SET\n        TenPhong = @TenPhong,\n        LoaiPhong = @LoaiPhong,\n        TrangThai = @TrangThai\n    WHERE\n        PhongID = @PhongID;\n    SELECT\n        PhongID,\n        RapID,\n        TenPhong,\n        LoaiPhong,\n        TrangThai\n    FROM\n        dbo.PHONGCHIEU\n    WHERE\n        PhongID = @PhongID;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Seat_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Seat_Create\n    @ActorID INT,\n    @PhongID INT,\n    @HangGhe VARCHAR(10),\n    @SoGhe INT,\n    @LoaiGhe NVARCHAR(50) = N''Thường''\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.PHONGCHIEU\n        WHERE\n            PhongID = @PhongID\n    )\n        THROW 50204, N''Phòng không tồn tại.'', 1;\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.GHE\n        WHERE\n            PhongID = @PhongID\n            AND HangGhe = @HangGhe\n            AND SoGhe = @SoGhe\n    )\n        THROW 50205, N''Vị trí ghế đã tồn tại trong phòng.'', 1;\n    INSERT\n        dbo.GHE(PhongID, HangGhe, SoGhe, LoaiGhe, TrangThai)\n    VALUES\n        (@PhongID, @HangGhe, @SoGhe, @LoaiGhe, N''Hoạt động'');\n    SELECT\n        GheID,\n        PhongID,\n        HangGhe,\n        SoGhe,\n        LoaiGhe,\n        TrangThai\n    FROM\n        dbo.GHE\n    WHERE\n        GheID = SCOPE_IDENTITY();\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Seat_Delete","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Seat_Delete\n    @ActorID INT,\n    @GheID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        -- Mở transaction để các bước ghi được xử lý cùng nhau.\n        BEGIN TRANSACTION;\n        IF NOT EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.GHE\n            WITH\n                (UPDLOCK, HOLDLOCK)\n            WHERE\n                GheID = @GheID\n        )\n            THROW 50206, N''Ghế không tồn tại.'', 1;\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.CHITIETVE\n            WHERE\n                GheID = @GheID\n        )\n            THROW 50207, N''Ghế có lịch sử vé; hãy vô hiệu hóa thay vì xóa.'', 1;\n        -- Xóa các bản ghi thỏa điều kiện đã xác định.\n        DELETE dbo.GHE\n        WHERE\n            GheID = @GheID;\n        -- Chốt các thay đổi của transaction.\n        COMMIT TRANSACTION;\n        SELECT\n            N''Đã xóa ghế.'' AS [Message];\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() <> 0\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Seat_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Seat_List\n    @ActorID INT,\n    @PhongID INT = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SELECT\n        g.GheID,\n        g.PhongID,\n        pc.RapID,\n        r.TenRap,\n        g.HangGhe,\n        g.SoGhe,\n        g.HangGhe + CAST(g.SoGhe AS VARCHAR(10)) AS TenGhe,\n        g.LoaiGhe,\n        g.TrangThai\n    FROM\n        dbo.GHE g\n        INNER JOIN dbo.PHONGCHIEU pc ON pc.PhongID = g.PhongID\n        INNER JOIN dbo.RAPCHIEUPHIM r ON r.RapID = pc.RapID\n    WHERE\n        @PhongID IS NULL\n        OR g.PhongID = @PhongID\n    ORDER BY\n        r.TenRap,\n        pc.TenPhong,\n        g.HangGhe,\n        g.SoGhe;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Seat_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Seat_Update\n    @ActorID INT,\n    @GheID INT,\n    @LoaiGhe NVARCHAR(50),\n    @TrangThai NVARCHAR(50)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_GHE'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SET XACT_ABORT ON;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION AdminSeatUpdate;\n        DECLARE @OldType NVARCHAR(50);\n        SELECT\n            @OldType = LoaiGhe\n        FROM\n            dbo.GHE\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            GheID = @GheID;\n        IF @OldType IS NULL\n            THROW 50206, N''Ghế không tồn tại.'', 1;\n        -- Shared canonical seat lock serializes booking; historical type and\n        -- operational future-ticket restrictions are separate conditions.\n        IF EXISTS (\n            SELECT\n                @LoaiGhe\n            EXCEPT\n            SELECT\n                @OldType\n        )\n            AND EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.CHITIETVE\n            WHERE\n                GheID = @GheID\n        )\n            THROW 50207, N''Ghế có lịch sử vé; không thể thay đổi loại ghế.'', 1;\n        IF dbo.fn_GheCoVeHieuLucSuatTuongLai(@GheID) = 1\n            THROW 50207, N''Ghế có vé hiệu lực ở suất chiếu tương lai.'', 1;\n        -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n        UPDATE dbo.GHE\n        SET\n            LoaiGhe = @LoaiGhe,\n            TrangThai = @TrangThai\n        WHERE\n            GheID = @GheID;\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        SELECT\n            GheID,\n            PhongID,\n            HangGhe,\n            SoGhe,\n            LoaiGhe,\n            TrangThai\n        FROM\n            dbo.GHE\n        WHERE\n            GheID = @GheID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION AdminSeatUpdate;\n        END;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Showtime_Cancel","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Showtime_Cancel\n    @ActorID INT,\n    @SuatChieuID INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    EXEC dbo.sp_Showtime_CancelCascade @SuatChieuID = @SuatChieuID,\n        @NguoiDungID = @ActorID,\n        @LyDo = NULL;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Showtime_Create","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/008_admin_global_portal.sql:266 (dbo.usp_Admin_Showtime_Create)\nCREATE   PROCEDURE dbo.usp_Admin_Showtime_Create\n    @ActorID INT,\n    @PhimID INT,\n    @PhongID INT,\n    @ThoiGianBatDau DATETIME2,\n    @ThoiGianKetThuc DATETIME2,\n    @DinhDang NVARCHAR(50) = N''2D'',\n    @GiaVeCoBan DECIMAL(18, 2)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SET XACT_ABORT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION AdminShowtimeCreate;\n        DECLARE @NewSuatChieuID INT,\n            @LockedPhongID INT;\n        SELECT\n            @LockedPhongID = PhongID\n        FROM\n            dbo.PHONGCHIEU\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            PhongID = @PhongID;\n        IF @LockedPhongID IS NULL\n            THROW 50056, N''Phòng chiếu không tồn tại.'', 1;\n        IF @ThoiGianKetThuc <= @ThoiGianBatDau\n            THROW 50211, N''Thời gian suất chiếu không hợp lệ.'', 1;\n        EXEC dbo.sp_Showtime_ValidateTimes @PhimID = @PhimID,\n            @ThoiGianBatDau = @ThoiGianBatDau,\n            @ThoiGianKetThuc = @ThoiGianKetThuc,\n            @PhongID = @PhongID;\n        INSERT\n            dbo.SUATCHIEU(\n                PhimID,\n                PhongID,\n                ThoiGianBatDau,\n                ThoiGianKetThuc,\n                DinhDang,\n                GiaVeCoBan,\n                TrangThai\n            )\n        VALUES\n            (\n                @PhimID,\n                @PhongID,\n                @ThoiGianBatDau,\n                @ThoiGianKetThuc,\n                @DinhDang,\n                @GiaVeCoBan,\n                N''Mở bán''\n            );\n        SET\n            @NewSuatChieuID = SCOPE_IDENTITY();\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        EXEC dbo.sp_Showtime_GetDetail @SuatChieuID = @NewSuatChieuID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION AdminShowtimeCreate;\n        END;\n        SET XACT_ABORT OFF;\n        ;\n        THROW;\n    END CATCH;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Showtime_List","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"CREATE   PROCEDURE dbo.usp_Admin_Showtime_List\n    @ActorID INT,\n    @RapID INT = NULL,\n    @TuNgay DATE = NULL,\n    @DenNgay DATE = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    SELECT\n        sc.SuatChieuID,\n        sc.PhimID,\n        p.TenPhim,\n        sc.PhongID,\n        pc.TenPhong,\n        pc.RapID,\n        r.TenRap,\n        sc.ThoiGianBatDau,\n        sc.ThoiGianKetThuc,\n        sc.DinhDang,\n        sc.GiaVeCoBan,\n        sc.TrangThai\n    FROM\n        dbo.SUATCHIEU sc\n        INNER JOIN dbo.PHONGCHIEU pc ON pc.PhongID = sc.PhongID\n        INNER JOIN dbo.RAPCHIEUPHIM r ON r.RapID = pc.RapID\n        INNER JOIN dbo.PHIM p ON p.PhimID = sc.PhimID\n    WHERE\n        (\n            @RapID IS NULL\n            OR pc.RapID = @RapID\n        )\n        AND (\n            @TuNgay IS NULL\n            OR dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau) >= @TuNgay\n        )\n        AND (\n            @DenNgay IS NULL\n            OR dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau) <= @DenNgay\n        )\n    ORDER BY\n        sc.ThoiGianBatDau DESC;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"usp_Admin_Showtime_Update","type":"P ","type_desc":"SQL_STORED_PROCEDURE","definition":"-- Baseline: migrations/014_showtime_lifecycle.sql:178 (dbo.usp_Admin_Showtime_Update)\nCREATE   PROCEDURE dbo.usp_Admin_Showtime_Update\n    @ActorID INT,\n    @SuatChieuID INT,\n    @PhimID INT,\n    @ThoiGianBatDau DATETIME2,\n    @ThoiGianKetThuc DATETIME2,\n    @DinhDang NVARCHAR(50),\n    @GiaVeCoBan DECIMAL(18, 2),\n    @TrangThai NVARCHAR(50)\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SET XACT_ABORT ON;\n    -- R3B: current account, actor eligibility, then every required permission.\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG\n        WHERE\n            NguoiDungID = @ActorID\n            AND TrangThai = N''Hoạt động''\n    )\n        THROW 50300, N''Tài khoản không tồn tại hoặc đã bị khóa.'', 1;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            dbo.NGUOIDUNG nd\n            INNER JOIN dbo.VAITRO vt ON vt.VaiTroID = nd.VaiTroID\n        WHERE\n            nd.NguoiDungID = @ActorID\n            AND vt.MaVaiTro IN (''ADMIN'')\n    )\n        THROW 50301, N''Vai trò không được phép thực hiện thao tác này.'', 1;\n    -- Kiểm tra quyền chức năng trước khi thao tác.\n    IF dbo.fn_KiemTraQuyenNguoiDung(@ActorID, ''QL_SUAT_CHIEU'') = 0\n        THROW 50302, N''Không có quyền thực hiện thao tác này.'', 1;\n    DECLARE @OwnTran BIT = CASE\n        WHEN @@TRANCOUNT = 0 THEN 1\n        ELSE 0\n    END;\n    -- Thực hiện nghiệp vụ và bắt lỗi khi có sự cố.\n    BEGIN TRY\n        IF @OwnTran = 1\n            -- Mở transaction để các bước ghi được xử lý cùng nhau.\n            BEGIN TRANSACTION\n        ELSE\n            -- Đặt savepoint khi dùng transaction của bên gọi.\n            SAVE TRANSACTION AdminShowtimeUpdate;\n        DECLARE @OldPhim INT,\n            @OldStart DATETIME2,\n            @OldEnd DATETIME2,\n            @OldFormat NVARCHAR(50),\n            @PhongID INT,\n            @LockedPhongID INT,\n            @OldPrice DECIMAL(18, 2);\n        -- Discover the immutable room, lock parent, then re-read/lock the current child.\n        SELECT\n            @PhongID = PhongID\n        FROM\n            dbo.SUATCHIEU\n        WHERE\n            SuatChieuID = @SuatChieuID;\n        SELECT\n            @LockedPhongID = PhongID\n        FROM\n            dbo.PHONGCHIEU\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            PhongID = @PhongID;\n        IF @LockedPhongID IS NULL\n            THROW 50058, N''Suất chiếu không tồn tại.'', 1;\n        SELECT\n            @OldPhim = PhimID,\n            @OldStart = ThoiGianBatDau,\n            @OldEnd = ThoiGianKetThuc,\n            @OldFormat = DinhDang,\n            @OldPrice = GiaVeCoBan\n        FROM\n            dbo.SUATCHIEU\n        WITH\n            (UPDLOCK, HOLDLOCK)\n        WHERE\n            SuatChieuID = @SuatChieuID\n            AND PhongID = @PhongID;\n        IF @OldPhim IS NULL\n            THROW 50058, N''Suất chiếu không tồn tại.'', 1;\n        IF @TrangThai = N''Đã hủy''\n            THROW 50123, N''Dùng route hủy suất chiếu riêng.'', 1;\n        -- R3.2: history includes all order states; preserve R1/R2 room -> show locks.\n        -- Required structural values are compared NULL-safely, not by field presence.\n        IF EXISTS (\n            SELECT\n                1\n            FROM\n                dbo.DONDATVE\n            WHERE\n                SuatChieuID = @SuatChieuID\n        )\n            AND EXISTS (\n            SELECT\n                @PhimID,\n                @ThoiGianBatDau,\n                @ThoiGianKetThuc,\n                @DinhDang,\n                @GiaVeCoBan\n            EXCEPT\n            SELECT\n                @OldPhim,\n                @OldStart,\n                @OldEnd,\n                @OldFormat,\n                @OldPrice\n        )\n            THROW 50120, N''Suất chiếu có lịch sử đơn; không thể đổi phim, phòng, giờ, định dạng hoặc giá vé cơ bản.'', 1;\n        IF @ThoiGianKetThuc <= @ThoiGianBatDau\n            THROW 50211, N''Thời gian suất chiếu không hợp lệ.'', 1;\n        EXEC dbo.sp_Showtime_ValidateTimes @PhimID = @PhimID,\n            @ThoiGianBatDau = @ThoiGianBatDau,\n            @ThoiGianKetThuc = @ThoiGianKetThuc,\n            @PhongID = @PhongID,\n            @SuatChieuID = @SuatChieuID,\n            @TrangThai = @TrangThai;\n        -- Cập nhật dữ liệu theo điều kiện nghiệp vụ.\n        UPDATE dbo.SUATCHIEU\n        SET\n            PhimID = @PhimID,\n            ThoiGianBatDau = @ThoiGianBatDau,\n            ThoiGianKetThuc = @ThoiGianKetThuc,\n            DinhDang = @DinhDang,\n            GiaVeCoBan = @GiaVeCoBan,\n            TrangThai = @TrangThai\n        WHERE\n            SuatChieuID = @SuatChieuID;\n        IF @OwnTran = 1\n            -- Chốt các thay đổi của transaction.\n            COMMIT TRANSACTION;\n        -- Writer returns the persisted row even after closing sales. Public reads\n        -- continue to apply the R2.1 IsBookable filter in sp_Showtime_GetDetail.\n        SELECT\n            SuatChieuID,\n            PhimID,\n            TenPhim,\n            PosterURL,\n            ThoiLuong,\n            DoTuoi,\n            RapID,\n            TenRap,\n            DiaChiRap,\n            ThanhPho,\n            PhongID,\n            TenPhong,\n            LoaiPhong,\n            ThoiGianBatDau,\n            ThoiGianKetThuc,\n            NgayChieu,\n            GioBatDau,\n            GioKetThuc,\n            DinhDang,\n            GiaVeCoBan,\n            TrangThaiSuatChieu,\n            TongSoGhe,\n            SoGheDaDat,\n            (TongSoGhe - SoGheDaDat) AS SoGheConLai\n        FROM\n            dbo.vw_LichChieuChiTiet\n        WHERE\n            SuatChieuID = @SuatChieuID;\n    END TRY\n    -- Hoàn tác khi cần và chuyển lỗi cho bên gọi.\n    BEGIN CATCH\n        IF XACT_STATE() = - 1\n            -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n            ROLLBACK TRANSACTION;\n        ELSE\n            IF XACT_STATE() = 1\n            BEGIN\n                IF @OwnTran = 1\n                    -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                    ROLLBACK TRANSACTION\n            ELSE\n                -- Hoàn tác transaction hoặc savepoint khi có lỗi.\n                ROLLBACK TRANSACTION AdminShowtimeUpdate;\n        END\n        SET XACT_ABORT OFF;\n        ;\n        THROW;\n    END CATCH\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"PK_BANGGIA","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_BOITHUONG_HUYSUAT","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_CHITIETDOAN","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_CHITIETVE","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_DANHGIAPHIM","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_DIENVIEN","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_DONDATVE","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_GHE","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_HINHANH_RAPCHIEUPHIM","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_HOSOKHACHHANG","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_KHIEUNAI","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_KHUYENMAI","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_LICHSU_PHANCONG_KHIEUNAI","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_NGUOIDUNG","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_PHANCONG_RAP","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_PHIM","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_PHIM_DIENVIEN","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_PHIM_THELOAI","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_PHONGCHIEU","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_QUYEN","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_RAPCHIEUPHIM","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_SANPHAM","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_SUATCHIEU","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_TINNHAN_KHIEUNAI","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_THANHTOAN","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_THELOAI","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_VAITRO","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_VAITRO_QUYEN","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_XULY_KHIEUNAI","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PK_YEUCAU_CHUYENCAP","type":"PK","type_desc":"PRIMARY_KEY_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"TRG_BangGia_KiemTraChongLan","type":"TR","type_desc":"SQL_TRIGGER","definition":"-- ---------------------------------------------------------------------------------------------\n-- (1) Overlapping pricing rules.\n-- \"Overlap\" = same RapID, same (LoaiGhe, LoaiNgay, DinhDang) values (N''Tất cả'' counts as a value of its own),\n-- both TrangThai = N''Áp dụng'', and validity ranges that intersect (NgayKetThuc NULL = open ended; the end day is\n-- inclusive, as in fn_TinhGiaVe). A N''Tất cả'' rule and a specific rule that differ in a column are two different\n-- conditions and may coexist: they are deliberate layers (e.g. VIP +15,000 together with weekend +10,000).\n--\n-- A trigger is used (like TRG_SuatChieu_KiemTraTrungLich) so that every write path is covered: the admin and\n-- manager procedures and direct DML. The trigger takes an UPDLOCK/HOLDLOCK on the cinema row first (assigned to a\n-- variable, no result set, rows locked in RapID order), so two concurrent writers for one cinema are queued and\n-- the second one sees the first one''s committed row (the database runs READ_COMMITTED_SNAPSHOT, so its read does\n-- not block on the other transaction''s uncommitted row: no lock cycle). Existing overlapping rows are never\n-- modified; only rows being inserted/updated to \"Áp dụng\" are checked.\n-- ---------------------------------------------------------------------------------------------\nCREATE\n \nTRIGGER dbo.TRG_BangGia_KiemTraChongLan ON dbo.BANGGIA AFTER\nINSERT\n,\nUPDATE AS\nBEGIN\n    SET NOCOUNT ON;\n    IF NOT EXISTS (\n        SELECT\n            1\n        FROM\n            inserted\n        WHERE\n            TrangThai = N''Áp dụng''\n    )\n        RETURN;\n    DECLARE @KhoaRap INT;\n    SELECT\n        @KhoaRap = r.RapID\n    FROM\n        dbo.RAPCHIEUPHIM r\n    WITH\n        (UPDLOCK, HOLDLOCK)\n    WHERE\n        r.RapID IN (\n            SELECT\n                RapID\n            FROM\n                inserted\n            WHERE\n                TrangThai = N''Áp dụng''\n        );\n    -- against the rows already in the table\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            inserted i\n            INNER JOIN dbo.BANGGIA b ON b.RapID = i.RapID\n            AND b.GiaID <> i.GiaID\n            AND b.LoaiGhe = i.LoaiGhe\n            AND b.LoaiNgay = i.LoaiNgay\n            AND b.DinhDang = i.DinhDang\n        WHERE\n            i.TrangThai = N''Áp dụng''\n            AND b.TrangThai = N''Áp dụng''\n            AND i.NgayBatDau <= ISNULL(b.NgayKetThuc, ''9999-12-31'')\n            AND b.NgayBatDau <= ISNULL(i.NgayKetThuc, ''9999-12-31'')\n    )\n    BEGIN\n        ;\n        THROW 50215, N''Lỗi ràng buộc: Bảng giá đang áp dụng đã có cùng điều kiện trong khoảng thời gian này.'', 1;\n    END\n    -- within the statement itself (multi-row insert/update)\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            inserted i1\n            INNER JOIN inserted i2 ON i1.GiaID < i2.GiaID\n            AND i1.RapID = i2.RapID\n            AND i1.LoaiGhe = i2.LoaiGhe\n            AND i1.LoaiNgay = i2.LoaiNgay\n            AND i1.DinhDang = i2.DinhDang\n        WHERE\n            i1.TrangThai = N''Áp dụng''\n            AND i2.TrangThai = N''Áp dụng''\n            AND i1.NgayBatDau <= ISNULL(i2.NgayKetThuc, ''9999-12-31'')\n            AND i2.NgayBatDau <= ISNULL(i1.NgayKetThuc, ''9999-12-31'')\n    )\n    BEGIN\n        ;\n        THROW 50215, N''Lỗi ràng buộc: Bảng giá đang áp dụng đã có cùng điều kiện trong khoảng thời gian này.'', 1;\n    END\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"TRG_ChiTietVe_KiemTraGheDungPhong","type":"TR","type_desc":"SQL_TRIGGER","definition":"CREATE\n \nTRIGGER dbo.TRG_ChiTietVe_KiemTraGheDungPhong ON dbo.CHITIETVE AFTER\nINSERT\n,\nUPDATE AS\nBEGIN\n    SET NOCOUNT ON;\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            INSERTED i\n            INNER JOIN dbo.DONDATVE ddv ON i.DonDatVeID = ddv.DonDatVeID\n            INNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\n            INNER JOIN dbo.GHE g ON i.GheID = g.GheID\n        WHERE\n            g.PhongID <> sc.PhongID\n    )\n    BEGIN\n        ;\n        THROW 50002, N''Lỗi ràng buộc [BR03]: Ghế được chọn không thuộc phòng chiếu của suất chiếu này.'', 1;\n    END\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"TRG_ChiTietVe_KiemTraTrungGhe","type":"TR","type_desc":"SQL_TRIGGER","definition":"-- Baseline: triggers/04_triggers.sql:87 (dbo.TRG_ChiTietVe_KiemTraTrungGhe)\nCREATE\n \nTRIGGER dbo.TRG_ChiTietVe_KiemTraTrungGhe ON dbo.CHITIETVE AFTER\nINSERT\n,\nUPDATE AS\nBEGIN\n    SET NOCOUNT ON;\n    -- Kiểm tra giữa dòng mới với vé hiện có trong cơ sở dữ liệu\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            INSERTED i\n            INNER JOIN dbo.DONDATVE ddv_new ON i.DonDatVeID = ddv_new.DonDatVeID\n            INNER JOIN dbo.CHITIETVE cv_exist ON i.GheID = cv_exist.GheID\n            AND i.VeID <> cv_exist.VeID\n            INNER JOIN dbo.DONDATVE ddv_exist ON cv_exist.DonDatVeID = ddv_exist.DonDatVeID\n        WHERE\n            ddv_new.SuatChieuID = ddv_exist.SuatChieuID\n            AND i.TrangThai <> N''Đã hủy''\n            AND cv_exist.TrangThai <> N''Đã hủy''\n            AND ddv_new.TrangThai NOT IN (N''Đã hủy'', N''Hết hạn'')\n            AND dbo.fn_DonDangGiuGhe(ddv_exist.TrangThai, ddv_exist.HanGiuCho, dbo.fn_BayGio()) = 1\n    )\n    BEGIN\n        ;\n        THROW 50003, N''Lỗi xung đột [BR02]: Ghế này đã được đặt hoặc đang được giữ bởi một đơn khác cho cùng suất chiếu.'', 1;\n    END\n    -- Kiểm tra trùng lặp trong chính tập INSERTED\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            INSERTED i1\n            INNER JOIN dbo.DONDATVE ddv1 ON i1.DonDatVeID = ddv1.DonDatVeID\n            INNER JOIN INSERTED i2 ON i1.GheID = i2.GheID\n            AND i1.VeID <> i2.VeID\n            INNER JOIN dbo.DONDATVE ddv2 ON i2.DonDatVeID = ddv2.DonDatVeID\n        WHERE\n            ddv1.SuatChieuID = ddv2.SuatChieuID\n            AND i1.TrangThai <> N''Đã hủy''\n            AND i2.TrangThai <> N''Đã hủy''\n    )\n    BEGIN\n        ;\n        THROW 50003, N''Lỗi xung đột [BR02]: Phát hiện chọn trùng cùng một ghế nhiều lần trong cùng một đơn.'', 1;\n    END\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"TRG_DanhGia_KiemTraDaXemPhim","type":"TR","type_desc":"SQL_TRIGGER","definition":"-- Baseline: triggers/04_triggers.sql:133 (dbo.TRG_DanhGia_KiemTraDaXemPhim)\nCREATE\n \nTRIGGER dbo.TRG_DanhGia_KiemTraDaXemPhim ON dbo.DANHGIAPHIM AFTER\nINSERT\n    AS\nBEGIN\n    SET NOCOUNT ON;\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            INSERTED i\n        WHERE\n            NOT EXISTS (\n                SELECT\n                    1\n                FROM\n                    dbo.DONDATVE ddv\n                    INNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\n                WHERE\n                    ddv.NguoiDungID = i.NguoiDungID\n                    AND sc.PhimID = i.PhimID\n                    AND ddv.TrangThai IN (N''Đã thanh toán'', N''Hoàn thành'')\n                    AND sc.ThoiGianBatDau <= dbo.fn_BayGio()\n            )\n    )\n    BEGIN\n        ;\n        THROW 50004, N''Lỗi nghiệp vụ [BR05]: Khách hàng chỉ có thể đánh giá sau khi đã mua vé xem phim và suất chiếu đã diễn ra.'', 1;\n    END\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"TRG_NguoiDung_VaiTroBatBien","type":"TR","type_desc":"SQL_TRIGGER","definition":"CREATE\n \nTRIGGER dbo.TRG_NguoiDung_VaiTroBatBien ON dbo.NGUOIDUNG AFTER\nUPDATE AS\nBEGIN\n    SET NOCOUNT ON;\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            inserted i\n            INNER JOIN deleted d ON d.NguoiDungID = i.NguoiDungID\n        WHERE\n            i.VaiTroID <> d.VaiTroID\n    )\n        THROW 50406, N''Vai trò tài khoản không được thay đổi sau khi tạo.'', 1;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"TRG_SuatChieu_KiemTraTrungLich","type":"TR","type_desc":"SQL_TRIGGER","definition":"CREATE\n \nTRIGGER dbo.TRG_SuatChieu_KiemTraTrungLich ON dbo.SUATCHIEU AFTER\nINSERT\n,\nUPDATE AS\nBEGIN\n    SET NOCOUNT ON;\n    -- Kiểm tra giao nhau giữa bản ghi mới/sửa với các suất chiếu đã có trong bảng\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            INSERTED i\n            INNER JOIN dbo.SUATCHIEU sc ON i.PhongID = sc.PhongID\n            AND i.SuatChieuID <> sc.SuatChieuID\n        WHERE\n            i.TrangThai <> N''Đã hủy''\n            AND sc.TrangThai <> N''Đã hủy''\n            AND i.ThoiGianBatDau < sc.ThoiGianKetThuc\n            AND i.ThoiGianKetThuc > sc.ThoiGianBatDau\n    )\n    BEGIN\n        ;\n        THROW 50001, N''Lỗi ràng buộc [BR01]: Phòng chiếu đã có suất chiếu khác trong khoảng thời gian này.'', 1;\n    END\n    -- Kiểm tra giao nhau giữa các dòng trong chính tập INSERTED (phòng trường hợp insert/update theo lô)\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            INSERTED i1\n            INNER JOIN INSERTED i2 ON i1.PhongID = i2.PhongID\n            AND i1.SuatChieuID <> i2.SuatChieuID\n        WHERE\n            i1.TrangThai <> N''Đã hủy''\n            AND i2.TrangThai <> N''Đã hủy''\n            AND i1.ThoiGianBatDau < i2.ThoiGianKetThuc\n            AND i1.ThoiGianKetThuc > i2.ThoiGianBatDau\n    )\n    BEGIN\n        ;\n        THROW 50001, N''Lỗi ràng buộc [BR01]: Tập suất chiếu mới có khoảng thời gian trùng nhau trong cùng phòng.'', 1;\n    END\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"TRG_XuLyKhieuNai_CapNhatTrangThaiKhieuNai","type":"TR","type_desc":"SQL_TRIGGER","definition":"CREATE\n \nTRIGGER dbo.TRG_XuLyKhieuNai_CapNhatTrangThaiKhieuNai ON dbo.XULY_KHIEUNAI AFTER\nINSERT\n    AS\nBEGIN\n    SET NOCOUNT ON;\n    -- Serialize each affected parent before the separate history read. Identity\n    -- allocation order can differ from trigger/commit order between sessions.\n    DECLARE @AffectedCount INT;\n    SELECT\n        @AffectedCount = COUNT(*)\n    FROM\n        dbo.KHIEUNAI kn\n    WITH\n        (UPDLOCK, HOLDLOCK)\n        INNER JOIN (\n            SELECT DISTINCT\n                KhieuNaiID\n            FROM\n                inserted\n        ) affected ON affected.KhieuNaiID = kn.KhieuNaiID;\n    ;\n    WITH\n        Affected AS (\n            SELECT DISTINCT\n                KhieuNaiID\n            FROM\n                inserted\n        ),\n        LatestProcessing AS (\n            SELECT\n                xl.KhieuNaiID,\n                xl.TrangThaiSauXuLy,\n                ROW_NUMBER() OVER(\n                    PARTITION BY\n                        xl.KhieuNaiID\n                    ORDER BY\n                        xl.XuLyID DESC\n                ) AS rn\n            FROM\n                dbo.XULY_KHIEUNAI xl\n                INNER JOIN Affected a ON a.KhieuNaiID = xl.KhieuNaiID\n        )\n    UPDATE kn\n    SET\n        kn.TrangThai = latest.TrangThaiSauXuLy\n    FROM\n        dbo.KHIEUNAI kn\n        INNER JOIN LatestProcessing latest ON latest.KhieuNaiID = kn.KhieuNaiID\n        AND latest.rn = 1;\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"TRG_XuLyKhieuNai_KiemTraVaiTro","type":"TR","type_desc":"SQL_TRIGGER","definition":"CREATE\n \nTRIGGER dbo.TRG_XuLyKhieuNai_KiemTraVaiTro ON dbo.XULY_KHIEUNAI AFTER\nINSERT\n,\nUPDATE AS\nBEGIN\n    SET NOCOUNT ON;\n    IF EXISTS (\n        SELECT\n            1\n        FROM\n            INSERTED i\n            INNER JOIN dbo.NGUOIDUNG nd ON i.NguoiXuLyID = nd.NguoiDungID\n            INNER JOIN dbo.VAITRO vt ON nd.VaiTroID = vt.VaiTroID\n        WHERE\n            vt.MaVaiTro NOT IN (''CSKH'', ''ADMIN'')\n            OR nd.TrangThai <> N''Hoạt động''\n    )\n    BEGIN\n        ;\n        THROW 50005,\n            N''Lỗi bảo mật [BR07]: Chỉ nhân viên Chăm sóc khách hàng hoặc Quản trị viên mới được ghi nhận lịch sử xử lý khiếu nại.'', 1;\n    END\nEND;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"BANGGIA","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"BOITHUONG_HUYSUAT","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"CHITIETDOAN","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"CHITIETVE","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"DANHGIAPHIM","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"DIENVIEN","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"DONDATVE","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"GHE","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"HINHANH_RAPCHIEUPHIM","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"HOSOKHACHHANG","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"KHIEUNAI","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"KHUYENMAI","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"LICHSU_PHANCONG_KHIEUNAI","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"NGUOIDUNG","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PHANCONG_RAP","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PHIM","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PHIM_DIENVIEN","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PHIM_THELOAI","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"PHONGCHIEU","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"QUYEN","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"RAPCHIEUPHIM","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"SANPHAM","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"SUATCHIEU","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"TINNHAN_KHIEUNAI","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"THANHTOAN","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"THELOAI","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"VAITRO","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"VAITRO_QUYEN","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"XULY_KHIEUNAI","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"YEUCAU_CHUYENCAP","type":"U ","type_desc":"USER_TABLE","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_BOITHUONG_HUYSUAT_Don","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_CHITIETDOAN_Don_SanPham","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_CHITIETVE_MaVe","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_DANHGIAPHIM_Phim_User","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_GHE_ViTri","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_KHUYENMAI_MaCode","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_NGUOIDUNG_Email","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_PHONGCHIEU_TenPhong","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_QUYEN_MaQuyen","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_THELOAI_TenTheLoai","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"UQ_VAITRO_MaVaiTro","type":"UQ","type_desc":"UNIQUE_CONSTRAINT","definition":null,"uses_ansi_nulls":null,"uses_quoted_identifier":null},{"schemaName":"dbo","name":"vw_ChiTietDonDatVe","type":"V ","type_desc":"VIEW","definition":"-- Baseline: views/03_views.sql:106 (dbo.vw_ChiTietDonDatVe)\nCREATE   VIEW dbo.vw_ChiTietDonDatVe AS\nSELECT\n    ddv.DonDatVeID,\n    ddv.NguoiDungID,\n    nd.HoTen AS HoTenKhachHang,\n    nd.Email,\n    nd.SoDienThoai,\n    sc.SuatChieuID,\n    p.PhimID,\n    p.TenPhim,\n    p.PosterURL,\n    p.DoTuoi,\n    p.ThoiLuong,\n    r.RapID,\n    r.TenRap,\n    r.DiaChi AS DiaChiRap,\n    pc.PhongID,\n    pc.TenPhong,\n    pc.LoaiPhong,\n    sc.ThoiGianBatDau,\n    sc.ThoiGianKetThuc,\n    sc.DinhDang,\n    ddv.NgayDat,\n    ddv.TongTienVe,\n    ddv.TongTienDoAn,\n    ddv.TienGiamGia,\n    CASE\n        WHEN ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia < 0 THEN 0\n        ELSE ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia\n    END AS TongTienThanhToan,\n    ddv.DiemSuDung,\n    CASE\n        WHEN ddv.TrangThai = N''Chờ thanh toán''\n        AND ddv.HanGiuCho <= dbo.fn_BayGio() THEN N''Hết hạn''\n        ELSE ddv.TrangThai\n    END AS TrangThaiDon,\n    ddv.HanGiuCho,\n    km.MaCode AS MaKhuyenMai,\n    km.MoTa AS MoTaKhuyenMai,\n    -- Danh sách ghế dạng chuỗi (A1, A2...)\n    STUFF(\n        (\n            SELECT\n                '', '' + (g.HangGhe + CAST(g.SoGhe AS VARCHAR(10)))\n            FROM\n                dbo.CHITIETVE cv2\n                INNER JOIN dbo.GHE g ON cv2.GheID = g.GheID\n            WHERE\n                cv2.DonDatVeID = ddv.DonDatVeID\n                AND cv2.TrangThai <> N''Đã hủy''\n            FOR XML\n                PATH(''''),\n            TYPE\n        ).value(''.'', ''NVARCHAR(MAX)''),\n        1,\n        2,\n        ''''\n    ) AS DanhSachGhe,\n    -- Danh sách mã vé dạng chuỗi\n    STUFF(\n        (\n            SELECT\n                '', '' + cv3.MaVe\n            FROM\n                dbo.CHITIETVE cv3\n            WHERE\n                cv3.DonDatVeID = ddv.DonDatVeID\n                AND cv3.TrangThai <> N''Đã hủy''\n            FOR XML\n                PATH(''''),\n            TYPE\n        ).value(''.'', ''NVARCHAR(MAX)''),\n        1,\n        2,\n        ''''\n    ) AS DanhSachMaVe\nFROM\n    dbo.DONDATVE ddv\n    INNER JOIN dbo.NGUOIDUNG nd ON ddv.NguoiDungID = nd.NguoiDungID\n    INNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\n    INNER JOIN dbo.PHIM p ON sc.PhimID = p.PhimID\n    INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\n    INNER JOIN dbo.RAPCHIEUPHIM r ON pc.RapID = r.RapID\n    LEFT JOIN dbo.KHUYENMAI km ON ddv.KhuyenMaiID = km.KhuyenMaiID;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"vw_DanhSachKhieuNai","type":"V ","type_desc":"VIEW","definition":"CREATE   VIEW dbo.vw_DanhSachKhieuNai AS\nSELECT\n    kn.KhieuNaiID,\n    kn.NguoiDungID AS NguoiGuiID,\n    nd.HoTen AS HoTenNguoiGui,\n    nd.Email AS EmailNguoiGui,\n    nd.SoDienThoai AS SoDienThoaiNguoiGui,\n    kn.DonDatVeID,\n    kn.LoaiKhieuNai,\n    kn.TieuDe,\n    kn.NoiDung,\n    kn.MucDoUuTien,\n    kn.NgayTao,\n    kn.TrangThai AS TrangThaiKhieuNai,\n    kn.NhanVienPhuTrachID,\n    nv_pt.HoTen AS TenNhanVienPhuTrach,\n    nv_pt.Email AS EmailNhanVienPhuTrach,\n    (\n        SELECT\n            COUNT(*)\n        FROM\n            dbo.XULY_KHIEUNAI xl\n        WHERE\n            xl.KhieuNaiID = kn.KhieuNaiID\n    ) AS SoLanXuLy,\n    (\n        SELECT\n            TOP 1 xl.NgayXuLy\n        FROM\n            dbo.XULY_KHIEUNAI xl\n        WHERE\n            xl.KhieuNaiID = kn.KhieuNaiID\n        ORDER BY\n            xl.XuLyID DESC\n    ) AS NgayXuLyCuoi,\n    (\n        SELECT\n            TOP 1 nd_xl.HoTen\n        FROM\n            dbo.XULY_KHIEUNAI xl\n            INNER JOIN dbo.NGUOIDUNG nd_xl ON xl.NguoiXuLyID = nd_xl.NguoiDungID\n        WHERE\n            xl.KhieuNaiID = kn.KhieuNaiID\n        ORDER BY\n            xl.XuLyID DESC\n    ) AS NguoiXuLyCuoi,\n    (\n        SELECT\n            TOP 1 xl.NoiDungXuLy\n        FROM\n            dbo.XULY_KHIEUNAI xl\n        WHERE\n            xl.KhieuNaiID = kn.KhieuNaiID\n        ORDER BY\n            xl.XuLyID DESC\n    ) AS NoiDungXuLyCuoi\nFROM\n    dbo.KHIEUNAI kn\n    INNER JOIN dbo.NGUOIDUNG nd ON kn.NguoiDungID = nd.NguoiDungID\n    LEFT JOIN dbo.NGUOIDUNG nv_pt ON kn.NhanVienPhuTrachID = nv_pt.NguoiDungID;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"vw_DoanhThuTheoRap","type":"V ","type_desc":"VIEW","definition":"CREATE   VIEW dbo.vw_DoanhThuTheoRap AS\n-- Doanh thu tính từ THANHTOAN có TrangThai = ''Thành công'' (không dựa vào trạng thái đơn).\n-- Giao dịch ''Thất bại'' / ''Đang xử lý'' / ''Đã hoàn tiền'' không được tính.\nWITH\n    DonDaThu AS (\n        SELECT\n            ddv.DonDatVeID,\n            pc.RapID,\n            ddv.TongTienVe,\n            ddv.TongTienDoAn,\n            ddv.TienGiamGia,\n            CASE\n                WHEN ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia < 0 THEN 0\n                ELSE ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia\n            END AS TienDaThu,\n            (\n                SELECT\n                    COUNT(*)\n                FROM\n                    dbo.CHITIETVE cv\n                WHERE\n                    cv.DonDatVeID = ddv.DonDatVeID\n                    AND cv.TrangThai <> N''Đã hủy''\n            ) AS SoVeCuaDon\n        FROM\n            dbo.DONDATVE ddv\n            INNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\n            INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\n            INNER JOIN dbo.THANHTOAN tt ON tt.DonDatVeID = ddv.DonDatVeID\n            AND tt.TrangThai = N''Thành công''\n        GROUP BY\n            ddv.DonDatVeID,\n            pc.RapID,\n            ddv.TongTienVe,\n            ddv.TongTienDoAn,\n            ddv.TienGiamGia\n    ),\n    SuatChieuTheoRap AS (\n        SELECT\n            pc.RapID,\n            COUNT(DISTINCT sc.SuatChieuID) AS TongSoSuatChieu\n        FROM\n            dbo.PHONGCHIEU pc\n            LEFT JOIN dbo.SUATCHIEU sc ON pc.PhongID = sc.PhongID\n        GROUP BY\n            pc.RapID\n    )\nSELECT\n    r.RapID,\n    r.TenRap,\n    r.ThanhPho,\n    COUNT(dh.DonDatVeID) AS TongSoDon,\n    ISNULL(sc_rap.TongSoSuatChieu, 0) AS TongSoSuatChieu,\n    ISNULL(SUM(dh.SoVeCuaDon), 0) AS TongSoVeBan,\n    ISNULL(SUM(dh.TongTienVe), 0) AS DoanhThuVe,\n    ISNULL(SUM(dh.TongTienDoAn), 0) AS DoanhThuDoAn,\n    ISNULL(SUM(dh.TienGiamGia), 0) AS TongTienGiam,\n    ISNULL(SUM(dh.TienDaThu), 0) AS DoanhThuThucTe\nFROM\n    dbo.RAPCHIEUPHIM r\n    LEFT JOIN DonDaThu dh ON r.RapID = dh.RapID\n    LEFT JOIN SuatChieuTheoRap sc_rap ON r.RapID = sc_rap.RapID\nGROUP BY\n    r.RapID,\n    r.TenRap,\n    r.ThanhPho,\n    sc_rap.TongSoSuatChieu;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"vw_LichChieuChiTiet","type":"V ","type_desc":"VIEW","definition":"-- Baseline: views/03_views.sql:18 (dbo.vw_LichChieuChiTiet)\nCREATE   VIEW dbo.vw_LichChieuChiTiet AS\nSELECT\n    sc.SuatChieuID,\n    p.PhimID,\n    p.TenPhim,\n    p.ThoiLuong,\n    p.DoTuoi,\n    p.PosterURL,\n    p.TrailerURL,\n    p.TrangThai AS TrangThaiPhim,\n    p.NgayKhoiChieu,\n    p.NgayKetThuc,\n    r.RapID,\n    r.TenRap,\n    r.ThanhPho,\n    r.DiaChi AS DiaChiRap,\n    r.TrangThai AS TrangThaiRap,\n    pc.PhongID,\n    pc.TenPhong,\n    pc.LoaiPhong,\n    pc.TrangThai AS TrangThaiPhong,\n    sc.ThoiGianBatDau,\n    sc.ThoiGianKetThuc,\n    dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau) AS NgayChieu,\n    CONVERT(varchar(5), CONVERT(time, dbo.fn_GioRap(sc.ThoiGianBatDau)), 108) AS GioBatDau,\n    CONVERT(varchar(5), CONVERT(time, dbo.fn_GioRap(sc.ThoiGianKetThuc)), 108) AS GioKetThuc,\n    sc.DinhDang,\n    sc.GiaVeCoBan,\n    sc.TrangThai AS TrangThaiSuatChieu,\n    -- R2.1: one DB-owned showtime eligibility contract. Seat/conflict checks remain separate.\n    CAST(\n        CASE\n            WHEN sc.TrangThai = N''Mở bán''\n            AND sc.ThoiGianBatDau > dbo.fn_BayGio()\n            AND r.TrangThai = N''Hoạt động''\n            AND pc.TrangThai = N''Hoạt động''\n            AND p.TrangThai <> N''Ngừng chiếu''\n            AND dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau) >= p.NgayKhoiChieu\n            AND (\n                p.NgayKetThuc IS NULL\n                OR dbo.fn_NgayKinhDoanh(sc.ThoiGianBatDau) <= p.NgayKetThuc\n            ) THEN 1\n            ELSE 0\n        END AS BIT\n    ) AS IsBookable,\n    (\n        SELECT\n            COUNT(*)\n        FROM\n            dbo.GHE g\n        WHERE\n            g.PhongID = pc.PhongID\n            AND g.TrangThai = N''Hoạt động''\n    ) AS TongSoGhe,\n    (\n        SELECT\n            COUNT(*)\n        FROM\n            dbo.CHITIETVE cv\n            INNER JOIN dbo.DONDATVE ddv ON cv.DonDatVeID = ddv.DonDatVeID\n        WHERE\n            ddv.SuatChieuID = sc.SuatChieuID\n            AND dbo.fn_DonDangGiuGhe(ddv.TrangThai, ddv.HanGiuCho, dbo.fn_BayGio()) = 1\n            AND cv.TrangThai <> N''Đã hủy''\n    ) AS SoGheDaDat\nFROM\n    dbo.SUATCHIEU sc\n    INNER JOIN dbo.PHIM p ON sc.PhimID = p.PhimID\n    INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\n    INNER JOIN dbo.RAPCHIEUPHIM r ON pc.RapID = r.RapID;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"vw_LichSuDatVe","type":"V ","type_desc":"VIEW","definition":"-- Baseline: views/03_views.sql:62 (dbo.vw_LichSuDatVe)\nCREATE   VIEW dbo.vw_LichSuDatVe AS\nSELECT\n    ddv.DonDatVeID,\n    ddv.NguoiDungID,\n    nd.HoTen AS HoTenKhachHang,\n    nd.Email,\n    nd.SoDienThoai,\n    sc.SuatChieuID,\n    p.PhimID,\n    p.TenPhim,\n    p.PosterURL,\n    r.RapID,\n    r.TenRap,\n    pc.TenPhong,\n    sc.ThoiGianBatDau,\n    sc.ThoiGianKetThuc,\n    sc.DinhDang,\n    ddv.NgayDat,\n    ddv.TongTienVe,\n    ddv.TongTienDoAn,\n    ddv.TienGiamGia,\n    CASE\n        WHEN ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia < 0 THEN 0\n        ELSE ddv.TongTienVe + ddv.TongTienDoAn - ddv.TienGiamGia\n    END AS TongTienThanhToan,\n    ddv.DiemSuDung,\n    CASE\n        WHEN ddv.TrangThai = N''Chờ thanh toán''\n        AND ddv.HanGiuCho <= dbo.fn_BayGio() THEN N''Hết hạn''\n        ELSE ddv.TrangThai\n    END AS TrangThaiDon,\n    ddv.HanGiuCho,\n    km.MaCode AS MaKhuyenMai,\n    (\n        SELECT\n            COUNT(*)\n        FROM\n            dbo.CHITIETVE cv\n        WHERE\n            cv.DonDatVeID = ddv.DonDatVeID\n            AND cv.TrangThai <> N''Đã hủy''\n    ) AS SoLuongVe,\n    (\n        SELECT\n            TOP 1 tt.TrangThai\n        FROM\n            dbo.THANHTOAN tt\n        WHERE\n            tt.DonDatVeID = ddv.DonDatVeID\n        ORDER BY\n            tt.ThanhToanID DESC\n    ) AS TrangThaiThanhToanMoiNhat\nFROM\n    dbo.DONDATVE ddv\n    INNER JOIN dbo.NGUOIDUNG nd ON ddv.NguoiDungID = nd.NguoiDungID\n    INNER JOIN dbo.SUATCHIEU sc ON ddv.SuatChieuID = sc.SuatChieuID\n    INNER JOIN dbo.PHIM p ON sc.PhimID = p.PhimID\n    INNER JOIN dbo.PHONGCHIEU pc ON sc.PhongID = pc.PhongID\n    INNER JOIN dbo.RAPCHIEUPHIM r ON pc.RapID = r.RapID\n    LEFT JOIN dbo.KHUYENMAI km ON ddv.KhuyenMaiID = km.KhuyenMaiID;","uses_ansi_nulls":true,"uses_quoted_identifier":true},{"schemaName":"dbo","name":"vw_ThongKePhim","type":"V ","type_desc":"VIEW","definition":"CREATE   VIEW dbo.vw_ThongKePhim AS\nSELECT\n    p.PhimID,\n    p.TenPhim,\n    p.ThoiLuong,\n    p.NgayKhoiChieu,\n    p.DoTuoi,\n    p.PosterURL,\n    p.TrangThai,\n    ISNULL(dg.SoLuotDanhGia, 0) AS SoLuotDanhGia,\n    ISNULL(dg.DiemDanhGiaTrungBinh, 0.0) AS DiemDanhGiaTrungBinh,\n    ISNULL(sc.TongSoSuatChieu, 0) AS TongSoSuatChieu\nFROM\n    dbo.PHIM p\n    LEFT JOIN (\n        SELECT\n            PhimID,\n            COUNT(*) AS SoLuotDanhGia,\n            ROUND(AVG(CAST(SoSao AS FLOAT)), 1) AS DiemDanhGiaTrungBinh\n        FROM\n            dbo.DANHGIAPHIM\n        GROUP BY\n            PhimID\n    ) dg ON p.PhimID = dg.PhimID\n    LEFT JOIN (\n        SELECT\n            PhimID,\n            COUNT(*) AS TongSoSuatChieu\n        FROM\n            dbo.SUATCHIEU\n        GROUP BY\n            PhimID\n    ) sc ON p.PhimID = sc.PhimID;","uses_ansi_nulls":true,"uses_quoted_identifier":true}]';
SELECT [schemaName] COLLATE DATABASE_DEFAULT AS [schemaName],[name] COLLATE DATABASE_DEFAULT AS [name],[type] COLLATE DATABASE_DEFAULT AS [type] INTO #Expected_objects FROM OPENJSON(@expected) WITH ([schemaName] nvarchar(4000) '$.schemaName',[name] nvarchar(4000) '$.name',[type] nvarchar(4000) '$.type');
SELECT [schemaName] COLLATE DATABASE_DEFAULT AS [schemaName],[name] COLLATE DATABASE_DEFAULT AS [name],[type] COLLATE DATABASE_DEFAULT AS [type] INTO #Actual_objects FROM (SELECT s.name schemaName,o.name,o.type,o.type_desc,m.definition,m.uses_ansi_nulls,m.uses_quoted_identifier FROM sys.objects o JOIN sys.schemas s ON s.schema_id=o.schema_id LEFT JOIN sys.sql_modules m ON m.object_id=o.object_id WHERE o.is_ms_shipped=0) actual;
IF EXISTS (SELECT * FROM #Expected_objects EXCEPT SELECT * FROM #Actual_objects) OR EXISTS (SELECT * FROM #Actual_objects EXCEPT SELECT * FROM #Expected_objects)
BEGIN
 SELECT 'Missing or changed' AS Difference,* FROM (SELECT * FROM #Expected_objects EXCEPT SELECT * FROM #Actual_objects) missing;
 SELECT 'Unexpected or changed' AS Difference,* FROM (SELECT * FROM #Actual_objects EXCEPT SELECT * FROM #Expected_objects) extra;
 THROW 51001, 'Verify objects failed.', 1;
END;
DROP TABLE #Expected_objects; DROP TABLE #Actual_objects;
PRINT 'PASS objects';
GO
